-- FLL-GAR-2023 · engineer hints on every field, equation and compliance requirement (hint wave 2026-10-05).
-- Each description now carries a German hint and an English part after the marker "[EN] " (src/lib/eval/hint-text.ts; the form
-- renders the part of the page locale; the approval refusal prints the whole text as "Hinweis" for a block gate without its inputs).
-- Content authored from the printed guideline pages (rendered PDF read in the authoring session; the authoring JSON in the vault
-- carries a source string with the printed page per hint); every number / limit / clause in a hint is traceable to those pages.
-- SAFETY: text only (fields.description, equations.description, compliance_requirements.description); no field, equation, gate,
-- value or severity changes. The pre-block descriptions (encoder notes) are restored by the rollback and kept in the inventory JSON.
-- ORDER: apply AFTER 20261005140000_fll_gar_readiness_fixes.sql — the seven gates REQ-13/14/15/16/19/20/21 and the two attestation
-- fields that block moves off FLL-GAR-10 are addressed here on their new host sheets (FLL-GAR-11/12/13/14/17/18/19); applied before
-- the move, those statements match no row (no harm, but the hints would be missing until a re-run).
-- STAGED — not applied. Apply: node scripts/apply-migration.mjs scripts/migrations/20261005172000_fll_gar_hints.sql
-- Rollback: scripts/migrations/rollback-20261005172000_fll_gar_hints.sql
BEGIN;
UPDATE fields x SET description = 'Ausführender Betrieb, der die Abdichtungsarbeiten herstellt (Firma, Ansprechperson). Verwaltungsangabe für Berichtsköpfe und die Ausführungs-/Abnahmeblätter; keine fachliche Prüfung. Die Richtlinien verlangen die rechtzeitige Einbindung aller beteiligten Gewerke – Genehmigungs-, Planungs-, Material- und Ausführungsseite (§ 4.1).
[EN] Contractor that builds the sealing works (firm, contact person). Administrative entry for report headers and the execution/acceptance sheets; no technical check. The guideline calls for the early involvement of all trades – approval, design, material and execution side (§ 4.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-01' AND x.symbol = 'ausfuehrungsbetrieb';
UPDATE fields x SET description = 'Bauherr bzw. Auftraggeber des Gewässers. Verwaltungsangabe für Berichtsköpfe; keine Prüfung. Fachlich relevant, weil der Auftraggeber bestimmte Nachweise auslöst: Fordert er einen Dichtigkeitsnachweis, ist dieser werkstoff-/bauweisenspezifisch vertraglich zu vereinbaren (§ 4.1, s. Feld Dichtigkeitsnachweis in FLL-GAR-09).
[EN] Client / owner commissioning the water body. Administrative entry for report headers; no check. Relevant because the client triggers certain proofs: if the client demands a tightness proof, it must be agreed contractually per material/construction method (§ 4.1, see the tightness-proof field in FLL-GAR-09).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-01' AND x.symbol = 'bauherr';
UPDATE fields x SET description = 'Planendes Büro (Landschaftsarchitektur, Ingenieurbüro), das die Abdichtungsplanung verantwortet. Verwaltungsangabe für Berichtsköpfe; keine Prüfung. Die Richtlinien sehen die Planungsseite als eines der frühzeitig abzustimmenden Gewerke (§ 4.1).
[EN] Design office (landscape architect, engineering firm) responsible for the sealing design. Administrative entry for report headers; no check. The guideline names the design side as one of the trades to be coordinated early (§ 4.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-01' AND x.symbol = 'planer';
UPDATE fields x SET description = 'Interne Projektnummer des Büros. Reine Kennung für Berichte und Dateinamen; wird in keiner Prüfung verwendet.
[EN] Internal project number of the office. Pure identifier for reports and file names; not used by any check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-01' AND x.symbol = 'project_code';
UPDATE fields x SET description = 'Stichtag der Bewertung (z. B. Datum der Planungsfassung). Erscheint in Berichtsköpfen; keine Prüfung.
[EN] Reference date of the assessment (e.g. date of the design issue). Appears in report headers; no check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-01' AND x.symbol = 'project_date';
UPDATE fields x SET description = 'Sprechender Projektname (z. B. „Löschwasserteich Gewerbegebiet Nord“). Erscheint in allen Berichten; keine Prüfung.
[EN] Descriptive project name (e.g. ''fire-water pond, business park north''). Appears in all reports; no check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-01' AND x.symbol = 'project_name';
UPDATE fields x SET description = 'Adresse des Gewässerstandorts. Dient der Zuordnung in Berichten und als Hinweis für standortabhängige Angaben in FLL-GAR-04/-05 (Exposition, Frost, Lage); keine Prüfung.
[EN] Address of the water-body site. Used for identification in reports and as context for the site-dependent entries in FLL-GAR-04/-05 (exposure, frost, location); no check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-01' AND x.symbol = 'standort_address';
UPDATE fields x SET description = 'Bestätigung, dass das Gewässer im Geltungsbereich der Richtlinien liegt. Ja, wenn der gewählte Gewässertyp nicht zu den vier Ausschlüssen gehört: Deponien, Fischereieinrichtungen, Talsperren und Speicherbecken, Wasserstraßen (§ 1.1). Tor REQ-01 sperrt alle weiteren Arbeitsblätter, bis das Feld auf Ja steht.
[EN] Confirmation that the water body lies within the scope of the guideline. Yes when the selected type is not one of the four exclusions: landfills, fishery facilities, dams and storage reservoirs, waterways (§ 1.1). Gate REQ-01 blocks all further worksheets until this is set to yes.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-02' AND x.symbol = 'gewaesser_in_scope';
UPDATE fields x SET description = 'Art des Gewässers aus der Liste des § 1.1. Im Geltungsbereich: Teiche, Wasserbecken, Bachläufe, Schwimm-/Badeteiche und Freibäder mit biologischer Wasseraufbereitung, Retentionsbodenfilter und Pflanzenkläranlagen, Regenrückhaltebecken, Reitplätze mit regulierbarem Wasserstand (Anstauplätze), Löschwasserteiche, Beschneiungsteiche und -becken. Nicht im Geltungsbereich: Deponien, Fischereieinrichtungen, Talsperren und Speicherbecken, Wasserstraßen. Die Wahl steuert Gleichung FLL-GAR-02-D1 und das Feld „im Geltungsbereich“.
[EN] Type of water body from the § 1.1 list. In scope: ponds, water basins, streams, swimming/bathing ponds and open-air pools with biological water treatment, retention soil filters and constructed wetlands, stormwater retention basins, riding grounds with adjustable water level, fire-fighting ponds, snowmaking ponds and basins. Out of scope: landfills, fishery facilities, dams and storage reservoirs, waterways. The choice drives equation FLL-GAR-02-D1 and the ''in scope'' field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-02' AND x.symbol = 'gewaesser_type';
UPDATE fields x SET description = 'Berechneter Code aus dem Gewässertyp (Gleichung FLL-GAR-02-D1): 0 für die vier Ausschlüsse des § 1.1 (Deponie, Fischereieinrichtung, Talsperre/Speicherbecken, Wasserstraße), sonst 1. Nicht eingeben – Kontrollwert zum manuellen Feld „im Geltungsbereich“, das Tor REQ-01 liest.
[EN] Computed code from the water-body type (equation FLL-GAR-02-D1): 0 for the four § 1.1 exclusions (landfill, fishery, dam/storage reservoir, waterway), otherwise 1. Not an entry – a check value next to the manual ''in scope'' field that gate REQ-01 reads.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-02' AND x.symbol = 'gewaesser_in_scope_code';
UPDATE equations x SET description = 'Leitet aus dem Gewässertyp den Geltungsbereichscode ab: 0, wenn der Typ Deponie, Fischereieinrichtung, Talsperre/Speicherbecken oder Wasserstraße ist („Die Gewässerabdichtungsrichtlinien gelten nicht für …“, § 1.1), sonst 1. Keine gedruckte Formel – Abbildung der Ausschlussliste; Ergebnis dient als Kontrolle des Feldes „im Geltungsbereich“ (REQ-01).
[EN] Derives the scope code from the water-body type: 0 when the type is landfill, fishery facility, dam/storage reservoir or waterway (''the guideline does not apply to …'', § 1.1), otherwise 1. No printed formula – a mapping of the exclusion list; the result cross-checks the ''in scope'' field (REQ-01).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-02' AND x.equation_number = 'FLL-GAR-02-D1';
UPDATE compliance_requirements x SET description = 'Besteht, wenn „Gewässer im Geltungsbereich“ auf Ja steht. Dazu Gewässertyp wählen und das Feld bestätigen; bei Deponie, Fischereieinrichtung, Talsperre/Speicherbecken oder Wasserstraße gelten die Richtlinien nicht und das Projekt kann hier nicht weitergeführt werden (§ 1.1). Sperrtor: ohne Bestätigung bleiben alle Folgeblätter gesperrt.
[EN] Passes when ''water body in scope'' is set to yes. Select the water-body type and confirm the field; for landfill, fishery facility, dam/storage reservoir or waterway the guideline does not apply and the project cannot proceed here (§ 1.1). Blocking gate: without the confirmation all subsequent sheets stay locked.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-02' AND x.code = 'REQ-01';
UPDATE fields x SET description = 'Ergebnis der baurechtlichen Prüfung: Ist für Herstellung, Inbetriebnahme, Nutzung und Instandhaltung des Gewässers eine Genehmigung nach Landesbauordnung erforderlich? Zu prüfen sind u. a. Bauordnung und Abgrabungsgesetze, Genehmigungsverfahren der Länder und Kommunen je nach Größe und Nutzung, Nachbarrecht, Natur-/Umweltschutzrecht, Tierschutz, Hygiene (§ 4.2; § 4.1 „baurechtliche Genehmigungen gemäß LBO“). Tor REQ-02 besteht nur bei Ja.
[EN] Result of the building-law check: does construction, commissioning, use and maintenance of the water body need a permit under the state building code (LBO)? Check e.g. building code and excavation acts, approval procedures of states and municipalities depending on size and use, neighbour law, nature/environmental law, animal welfare, hygiene (§ 4.2; § 4.1 ''building permits per LBO''). Gate REQ-02 passes only with yes.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-03' AND x.symbol = 'lbo_genehmigung_erforderlich';
UPDATE fields x SET description = 'Ergebnis der wasserrechtlichen Prüfung: Ist für die Einleitung von Überschusswasser in natürliche Gewässer, in das angrenzende Gelände oder in das öffentliche Kanalnetz eine Genehmigung nach WHG erforderlich bzw. erteilt? Die Richtlinien nennen die Einleitung „gemäß WHG“ (§ 4.1) und weisen darauf hin, dass Einleitungen genehmigungspflichtig sein können (§ 4.10). Tor REQ-03 besteht nur bei Ja.
[EN] Result of the water-law check: does the discharge of surplus water into natural waters, adjacent ground or the public sewer require or hold a permit under the Federal Water Act (WHG)? The guideline names discharge ''per WHG'' (§ 4.1) and notes that discharges can be subject to approval (§ 4.10). Gate REQ-03 passes only with yes.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-03' AND x.symbol = 'whg_einleitung_genehmigung';
UPDATE compliance_requirements x SET description = 'Besteht, wenn „LBO-Genehmigung erforderlich“ auf Ja steht – d. h. die bauaufsichtlichen Anforderungen sind geprüft und die erforderlichen Genehmigungen beantragt. Die Richtlinien verlangen, im Planungsverlauf zu klären, welche bauaufsichtlichen Anforderungen Herstellung, Inbetriebnahme, Nutzung und Instandhaltung bestimmen (§ 4.2; § 4.1). Sperrtor: Feld belegen, sonst keine Freigabe. Hinweis: Das Tor liest nur den Ja-Wert; ein begründetes „nicht erforderlich“ ist hier nicht abbildbar.
[EN] Passes when ''LBO permit required'' is set to yes – i.e. the building-supervision requirements have been checked and the required permits applied for. The guideline requires clarifying during design which building-law requirements govern construction, commissioning, use and maintenance (§ 4.2; § 4.1). Blocking gate: fill the field, otherwise no approval. Note: the gate reads only the yes value; a justified ''not required'' cannot be recorded here.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-03' AND x.code = 'REQ-02';
UPDATE compliance_requirements x SET description = 'Besteht, wenn „WHG-Einleitungsgenehmigung“ auf Ja steht – die Genehmigungsfrage für die Ableitung des Überschusswassers ist geklärt. Grundlage: Einleitung in natürliche Gewässer gemäß WHG (§ 4.1); Einleitung in das angrenzende Gelände oder das öffentliche Kanalnetz kann genehmigungspflichtig sein (§ 4.10). Sperrtor: Feld belegen; das Tor liest nur Ja.
[EN] Passes when ''WHG discharge permit'' is set to yes – the permit question for the surplus-water discharge is settled. Basis: discharge into natural waters per WHG (§ 4.1); discharge into adjacent ground or the public sewer can be subject to approval (§ 4.10). Blocking gate: fill the field; the gate reads only yes.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-03' AND x.code = 'REQ-03';
UPDATE fields x SET description = 'Geplante maximale Wassertiefe in m aus der Planung (Schnitt). Gehört zur Festlegung der Nutzung – „Dimensionierung (z. B. Volumen, Tiefe)“ (§ 4.1) – und ist die Grundlage für die Füllhöhe in FLL-GAR-05, die nach Tab. 18 die Wassereinwirkungsklasse bestimmt (W1-B ≤ 5 m, W2-B ≤ 10 m, W3-B > 10 m). Pflichtfeld für Tor REQ-04.
[EN] Planned maximum water depth in m from the design (section). Part of the use definition – ''dimensioning (e.g. volume, depth)'' (§ 4.1) – and the basis for the fill height in FLL-GAR-05, which sets the water-action class per Tab. 18 (W1-B ≤ 5 m, W2-B ≤ 10 m, W3-B > 10 m). Required for gate REQ-04.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-04' AND x.symbol = 'gewaesser_tiefe_m';
UPDATE fields x SET description = 'Geplantes Wasservolumen in m³ aus der Planung. Teil der Nutzungsfestlegung („Dimensionierung, z. B. Volumen, Tiefe“, § 4.1); die Wahl des Abdichtungssystems hängt u. a. von Dimensionierung, Profilierung und Neigung ab (§ 4.7). Pflichtfeld für Tor REQ-04.
[EN] Planned water volume in m³ from the design. Part of the use definition (''dimensioning, e.g. volume, depth'', § 4.1); the choice of sealing system depends among other things on dimensioning, profiling and slope (§ 4.7). Required for gate REQ-04.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-04' AND x.symbol = 'gewaesser_volumen_m3';
UPDATE fields x SET description = 'Geplanter Höchstwasserstand in m (Höhenkote oder Höhe über Sohle) aus der Planung; Wellenschlag ist bei der Bemessung zu berücksichtigen (§ 9.1). Er gibt die Höhe der Überlaufeinrichtung vor (§ 4.10) und ist die Bezugshöhe der Randausbildung: Abdichtung im freien Gelände i. d. R. mind. 5 cm, an aufgehenden Bauteilen i. d. R. 30 cm (mit angepasster Randbefestigung ≥ 15 cm) darüber (§ 4.8; Werte in FLL-GAR-23). Pflichtfeld für Tor REQ-04.
[EN] Planned maximum water level in m (elevation or height above the base) from the design; wave action must be taken into account (§ 9.1). It sets the height of the overflow device (§ 4.10) and is the reference for the edge: sealing in free terrain as a rule at least 5 cm above it, at rising structures as a rule 30 cm (≥ 15 cm with adapted edge fastening) (§ 4.8; values entered in FLL-GAR-23). Required for gate REQ-04.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-04' AND x.symbol = 'hoechstwasserstand_m';
UPDATE fields x SET description = 'Vorgesehene Nutzung/Funktion des Gewässers in Worten, z. B. Löschwasserteich, ober-/unterirdisches Regenrückhaltebecken, Badeteich, Zierteich. Die Festlegung der Nutzung bestimmt u. a. die Funktion der Abdichtung, das Abdichtungssystem, Genehmigungen, Standort, Dimensionierung, Randausbildung und Schutzmaßnahmen (§ 4.1); Nutzungsart und Intensität (z. B. mechanische Beanspruchung, Schwimmteich) steuern die Systemwahl (§ 4.7). Pflichtfeld für Tor REQ-04.
[EN] Intended use/function of the water body in words, e.g. fire-fighting pond, above-/below-ground stormwater retention basin, bathing pond, ornamental pond. The use definition determines among other things the sealing function, the sealing system, permits, site, dimensioning, edge design and protection measures (§ 4.1); type and intensity of use (e.g. mechanical stress, swimming pond) drive the system choice (§ 4.7). Required for gate REQ-04.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-04' AND x.symbol = 'nutzung_funktion';
UPDATE compliance_requirements x SET description = 'Besteht, wenn Wassertiefe, Wasservolumen, Höchstwasserstand und Nutzungsfunktion alle eingetragen sind. Die Richtlinien verlangen, die vorgesehene Nutzung zu bestimmen, weil daraus Abdichtungsfunktion, Systemwahl, Dimensionierung, Randausbildung und Schutzmaßnahmen folgen (§ 4.1). Sperrtor: ein leeres Feld verhindert die Freigabe.
[EN] Passes when water depth, water volume, maximum water level and use/function are all entered. The guideline requires the intended use to be defined because sealing function, system choice, dimensioning, edge design and protection measures follow from it (§ 4.1). Blocking gate: any empty field prevents approval.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-04' AND x.code = 'REQ-04';
UPDATE compliance_requirements x SET description = 'Gilt nur für bahnenförmige und flüssige Abdichtungen (Bitumenbahnen, Kunststoff-/Elastomerbahnen, Flüssigkunststoff, PE-Bahnen aus FLL-GAR-09). Dann besteht das Tor, wenn in FLL-GAR-05 Wassereinwirkungsklasse (W1-B…W3-B nach Füllhöhe), Rissklasse (R0-B…R3-B) und Standortklasse (S1-B/S2-B) gesetzt sind. Grundlage ist Tab. 18 auf Basis von DIN 18535-1: Die Einwirkungen und Standortbedingungen werden für diese Bauweisen differenziert (§ 6 Einleitung), und die Bahnen müssen den projektspezifisch erforderlichen Klassen entsprechen (§ 6.1.1). Sperrtor; bei mineralischen Abdichtungen, Stahl, Alkalisilikaten oder GUP nicht aktiv.
[EN] Applies only to sheet and liquid sealings (bituminous sheets, plastic/elastomer sheets, liquid plastic, PE sheets from FLL-GAR-09). The gate then passes when FLL-GAR-05 has the water-action class (W1-B…W3-B by fill height), crack class (R0-B…R3-B) and site class (S1-B/S2-B) set. Basis is Tab. 18 derived from DIN 18535-1: actions and site conditions are differentiated for these construction methods (§ 6 introduction), and the sheets must meet the project-specific classes (§ 6.1.1). Blocking gate; inactive for mineral sealings, steel, alkali silicates or GRP.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-04' AND x.code = 'REQ-05';
UPDATE compliance_requirements x SET description = 'Warnhinweis ohne automatische Bedingung: Ist eine Eisbildung nicht auszuschließen, ist der Randbereich – insbesondere An- und Abschlüsse und Übergänge – ggf. vor Eisdruck zu schützen (§ 4.4). Zum Belegen in FLL-GAR-05 „Eisbildung möglich“ beantworten und bei Ja den Nachweis „Randbereich vor Eisdruck geschützt“ bestätigen; die Schutzmaßnahme (z. B. Randbefestigung, Böschungsprofil) gehört in die Randausbildung (FLL-GAR-23).
[EN] Warning without an automatic condition: if ice formation cannot be excluded, the edge zone – especially connections, terminations and transitions – must be protected against ice pressure where needed (§ 4.4). To document it, answer ''ice formation possible'' in FLL-GAR-05 and, if yes, confirm the attestation ''edge zone protected against ice pressure''; the protective measure (e.g. edge fastening, slope profile) belongs to the edge design (FLL-GAR-23).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-04' AND x.code = 'REQ-06';
UPDATE fields x SET description = 'Ja, wenn am Standort eine Eisbildung auf dem Gewässer nicht auszuschließen ist (Klimadaten, Lage, Nutzung im Winter). Dann ist der Randbereich, insbesondere An-/Abschlüsse und Übergänge, ggf. vor Eisdruck zu schützen (§ 4.4); witterungsbedingte Einflüsse wie Vereisung und Eisdruck bestimmen die Art der Randausbildung (§ 9.1). Bei Ja erscheint der Nachweis „Randbereich vor Eisdruck geschützt“ (REQ-06).
[EN] Yes if ice formation on the water body cannot be excluded at the site (climate data, location, winter use). Then the edge zone, especially connections, terminations and transitions, must be protected against ice pressure where needed (§ 4.4); weather effects such as icing and ice pressure govern the type of edge design (§ 9.1). With yes, the attestation ''edge zone protected against ice pressure'' appears (REQ-06).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-05' AND x.symbol = 'eisbildung_moeglich';
UPDATE fields x SET description = 'Besonnung des Gewässers am Standort: Sonnenexposition, Halbschatten oder Schatten (Lageplan, Umgebung). Die Richtlinien nennen den Standort mit „Exposition, Frosteinwirkung, Lage des Gewässers“ als Aspekt der Nutzungsfestlegung (§ 4.1) und die klimatischen Bedingungen (UV-Strahlung, Temperaturunterschiede, Niederschläge) als Kriterium der Systemwahl (§ 4.7). Die drei Stufen sind eine Einteilung des Arbeitsblatts; die Richtlinien drucken keine Klassen. Kein Grenzwert.
[EN] Sun exposure of the water body at the site: full sun, partial shade or shade (site plan, surroundings). The guideline lists the site with ''exposure, frost action, location of the water body'' as an aspect of the use definition (§ 4.1) and the climatic conditions (UV radiation, temperature differences, precipitation) as a criterion for the system choice (§ 4.7). The three levels are a worksheet classification; the guideline prints no classes. No limit.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-05' AND x.symbol = 'exposition';
UPDATE fields x SET description = 'Ja, wenn der Standort Frost-Tau-Wechseln ausgesetzt ist (Klimadaten, Höhenlage). Frosteinwirkung ist ein Standortaspekt der Nutzungsfestlegung (§ 4.1) und gehört zu den klimatischen Bedingungen der Systemwahl (§ 4.7); Bauwerksflächen unter der Abdichtung müssen frostfrei sein (§ 4.6). Keine Rechenprüfung; dokumentiert die Randbedingung für Werkstoffwahl und Randausbildung.
[EN] Yes if the site is exposed to freeze-thaw cycles (climate data, altitude). Frost action is a site aspect of the use definition (§ 4.1) and belongs to the climatic conditions for the system choice (§ 4.7); structure surfaces under the sealing must be frost-free (§ 4.6). No numeric check; documents the boundary condition for material choice and edge design.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-05' AND x.symbol = 'frosteinwirkung';
UPDATE fields x SET description = 'Füllhöhe = maximale Wassersäule über der Abdichtung in m (aus Wassertiefe/Höchstwasserstand in FLL-GAR-04). Sie ist der „wirksame Druck“, von dem die Wahl der Abdichtungsbauweise abhängt (§ 6 Einleitung), und bestimmt nach Tab. 18 die Wassereinwirkungsklasse: W1-B bis 5 m, W2-B bis 10 m, W3-B über 10 m. Gleichung FLL-GAR-05-D1 leitet daraus den Klassencode ab.
[EN] Fill height = maximum water column above the sealing in m (from water depth/maximum level in FLL-GAR-04). It is the ''effective pressure'' on which the choice of sealing method depends (§ 6 introduction) and sets the water-action class per Tab. 18: W1-B up to 5 m, W2-B up to 10 m, W3-B above 10 m. Equation FLL-GAR-05-D1 derives the class code from it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-05' AND x.symbol = 'fuellhoehe_m';
UPDATE fields x SET description = 'Rissklasse nach Tab. 18 (Grundlage DIN 18535-1) für die abzudichtenden Bauteile: R0-B = keine Rissbreitenveränderung bzw. Neurissbildung; R1-B = neu entstehende Risse oder Rissbreitenveränderung bis max. 0,2 mm; R2-B = bis max. 0,5 mm; R3-B = bis max. 1,0 mm, Rissversatz bis 0,5 mm. Aus der Rissgefährdung des Bauwerks (Tragwerksplanung, § 4.4 Bewegungen/Setzungen) wählen; Bitumenbahnen (§ 6.1.1) und Kunststoff-/Elastomerbahnen (§ 6.2.1) müssen der erforderlichen Rissklasse entsprechen. Pflicht für Tor REQ-05 bei Bahnen-/Flüssigabdichtungen.
[EN] Crack class per Tab. 18 (based on DIN 18535-1) for the components to be sealed: R0-B = no change of crack width or new cracks; R1-B = new cracks or crack-width change up to max. 0.2 mm; R2-B = up to max. 0.5 mm; R3-B = up to max. 1.0 mm with crack offset up to 0.5 mm. Choose from the structure''s cracking risk (structural design, § 4.4 movements/settlements); bituminous sheets (§ 6.1.1) and plastic/elastomer sheets (§ 6.2.1) must meet the required crack class. Required for gate REQ-05 with sheet/liquid sealings.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-05' AND x.symbol = 'rissklasse';
UPDATE fields x SET description = 'Standortklasse nach Tab. 18: S1-B = Behälter im Außenbereich, der nicht mit einem Bauwerk verbunden ist (frei stehendes Gewässer); S2-B = Behälter im Außenbereich, der an ein Bauwerk angrenzt und mit diesem verbunden ist, sowie Behälter im Innenbereich. Aus Lageplan und Gebäudeanschlüssen wählen; die örtlichen Standortbedingungen sind bei Bahnen nachzuweisen (§ 6.1.1). Pflicht für Tor REQ-05 bei Bahnen-/Flüssigabdichtungen.
[EN] Site class per Tab. 18: S1-B = outdoor basin not connected to a building (free-standing water body); S2-B = outdoor basin adjoining and connected to a building, and indoor basins. Choose from site plan and building connections; the local site conditions must be met by the sheets (§ 6.1.1). Required for gate REQ-05 with sheet/liquid sealings.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-05' AND x.symbol = 'standortklasse';
UPDATE fields x SET description = 'Wassereinwirkungsklasse nach Tab. 18, bestimmt durch die Füllhöhe: W1-B ≤ 5 m, W2-B ≤ 10 m, W3-B > 10 m. Manuell nach der Füllhöhe wählen; der berechnete Code (FLL-GAR-05-D1) dient als Kontrolle. Bitumenbahnen (§ 6.1.1) und Kunststoff-/Elastomerbahnen (§ 6.2.1) müssen der projektspezifisch erforderlichen Klasse entsprechen; für Flüssigkunststoffe gilt Tab. 18 nach der Einleitung des § 6. Pflicht für Tor REQ-05 und Eingang der Materialblätter.
[EN] Water-action class per Tab. 18, determined by the fill height: W1-B ≤ 5 m, W2-B ≤ 10 m, W3-B > 10 m. Select manually from the fill height; the computed code (FLL-GAR-05-D1) serves as a check. Bituminous sheets (§ 6.1.1) and plastic/elastomer sheets (§ 6.2.1) must meet the project-specific class; for liquid plastics Tab. 18 applies per the introduction of § 6. Required for gate REQ-05 and input to the material sheets.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-05' AND x.symbol = 'wassereinwirkungsklasse';
UPDATE fields x SET description = 'Berechneter Code der Wassereinwirkungsklasse aus der Füllhöhe (Gleichung FLL-GAR-05-D1): 1 = W1-B (≤ 5 m), 2 = W2-B (≤ 10 m), 3 = W3-B (> 10 m) nach Tab. 18. Nicht eingeben – Kontrollwert zur manuell gewählten Wassereinwirkungsklasse; stimmen beide nicht überein, Füllhöhe oder Klasse korrigieren.
[EN] Computed water-action class code from the fill height (equation FLL-GAR-05-D1): 1 = W1-B (≤ 5 m), 2 = W2-B (≤ 10 m), 3 = W3-B (> 10 m) per Tab. 18. Not an entry – a check value against the manually selected class; if the two disagree, correct the fill height or the class.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-05' AND x.symbol = 'w_klasse_code';
UPDATE fields x SET description = 'Erste Frage der Rissklasse nach Tab. 18: „keine Rissbreitenveränderung bzw. Neurissbildung“ = Rissklasse R0-B; „neu entstehende Risse oder Rissbreitenveränderung“ = R1-B bis R3-B je nach erwarteter Rissbreite (Felder darunter). Aus der Tragwerksplanung/Bauteilbewertung ableiten (Bewegungen durch Befüllen, Schwinden, Temperatur, Setzungen, § 4.4). Eingang der Gleichung FLL-GAR-05-D2.
[EN] First question of the crack class per Tab. 18: ''no change of crack width or new cracks'' = crack class R0-B; ''new cracks or crack-width change'' = R1-B to R3-B depending on the expected crack width (fields below). Derive from the structural design/component assessment (movements from filling, shrinkage, temperature, settlements, § 4.4). Input to equation FLL-GAR-05-D2.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-05' AND x.symbol = 'neurissbildung';
UPDATE fields x SET description = 'Erwartete Rissbreite bzw. Rissbreitenveränderung der abzudichtenden Bauteile in mm (Tragwerksplanung); 0 eintragen, wenn keine Risse erwartet werden. Tab. 18 staffelt: R1-B bis max. 0,2 mm, R2-B bis max. 0,5 mm, R3-B bis max. 1,0 mm. Eingang der Gleichung FLL-GAR-05-D2; das Feld muss belegt sein (auch 0), sonst ist der Rissklassen-Code nicht berechenbar.
[EN] Expected crack width or crack-width change of the components to be sealed in mm (structural design); enter 0 if no cracks are expected. Tab. 18 grades: R1-B up to max. 0.2 mm, R2-B up to max. 0.5 mm, R3-B up to max. 1.0 mm. Input to equation FLL-GAR-05-D2; the field must be filled (even 0), otherwise the crack-class code cannot be computed.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-05' AND x.symbol = 'rissbreite_erwartet_mm';
UPDATE fields x SET description = 'Erwarteter Rissversatz (gegenseitige Verschiebung der Rissufer) in mm; 0 eintragen, wenn keiner erwartet wird. Tab. 18 lässt in Rissklasse R3-B einen Rissversatz bis 0,5 mm zu; größere Versätze decken die gedruckten Klassen nicht. Eingang der Gleichung FLL-GAR-05-D2; das Feld muss belegt sein (auch 0).
[EN] Expected crack offset (relative displacement of the crack faces) in mm; enter 0 if none is expected. Tab. 18 allows a crack offset up to 0.5 mm in crack class R3-B; larger offsets are not covered by the printed classes. Input to equation FLL-GAR-05-D2; the field must be filled (even 0).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-05' AND x.symbol = 'rissversatz_erwartet_mm';
UPDATE fields x SET description = 'Berechneter Rissklassen-Code (Gleichung FLL-GAR-05-D2) aus Neurissbildung, Rissbreite und Rissversatz nach Tab. 18: 0 = R0-B, 1 = R1-B (≤ 0,2 mm), 2 = R2-B (≤ 0,5 mm), 3 = R3-B (≤ 1,0 mm, Versatz ≤ 0,5 mm), 9 = außerhalb der gedruckten Klassen (Rissbreite > 1,0 mm oder Versatz > 0,5 mm); Tab. 18 nennt dafür keine Klasse – Bauweise mit dem Planer klären. Nicht eingeben – Kontrollwert zur manuell gewählten Rissklasse.
[EN] Computed crack-class code (equation FLL-GAR-05-D2) from new cracking, crack width and crack offset per Tab. 18: 0 = R0-B, 1 = R1-B (≤ 0.2 mm), 2 = R2-B (≤ 0.5 mm), 3 = R3-B (≤ 1.0 mm, offset ≤ 0.5 mm), 9 = outside the printed classes (crack width > 1.0 mm or offset > 0.5 mm); Tab. 18 gives no class for this – clarify the construction with the designer. Not an entry – a check value against the manually selected crack class.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-05' AND x.symbol = 'r_klasse_code';
UPDATE fields x SET description = 'Nur sichtbar, wenn Eisbildung möglich ist. Bestätigung, dass der Randbereich – insbesondere An- und Abschlüsse und Übergänge – vor Eisdruck geschützt ist, wie § 4.4 es verlangt („ggf. vor Eisdruck zu schützen“). Die Maßnahme (z. B. Randbefestigung, Böschungsprofil, Schutzlage) in der Randausbildung (FLL-GAR-23) beschreiben; Nachweis für Warnhinweis REQ-06.
[EN] Visible only when ice formation is possible. Confirmation that the edge zone – especially connections, terminations and transitions – is protected against ice pressure as § 4.4 requires (''to be protected against ice pressure where needed''). Describe the measure (e.g. edge fastening, slope profile, protection layer) in the edge design (FLL-GAR-23); evidence for warning REQ-06.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-05' AND x.symbol = 'eisdruck_randschutz_vorgesehen';
UPDATE equations x SET description = 'Ordnet die Füllhöhe (m) der Wassereinwirkungsklasse nach Tab. 18 zu: Füllhöhe ≤ 5 m → 1 (W1-B), ≤ 10 m → 2 (W2-B), > 10 m → 3 (W3-B). Keine gedruckte Formel, sondern die Klassengrenzen der Tabelle; das Ergebnis w_klasse_code kontrolliert die manuell gewählte Wassereinwirkungsklasse, die die Materialblätter für Bitumen-, Kunststoff- und Flüssigabdichtungen lesen.
[EN] Maps the fill height (m) to the water-action class per Tab. 18: fill height ≤ 5 m → 1 (W1-B), ≤ 10 m → 2 (W2-B), > 10 m → 3 (W3-B). No printed formula but the class limits of the table; the result w_klasse_code cross-checks the manually selected class, which the material sheets for bituminous, plastic and liquid sealings read.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-05' AND x.equation_number = 'FLL-GAR-05-D1';
UPDATE equations x SET description = 'Leitet den Rissklassen-Code aus den Tab.-18-Kriterien ab: keine Neurissbildung → 0 (R0-B); sonst Rissbreite ≤ 0,2 mm → 1 (R1-B), ≤ 0,5 mm → 2 (R2-B), ≤ 1,0 mm bei Rissversatz ≤ 0,5 mm → 3 (R3-B); alles darüber → 9 (keine gedruckte Klasse). Eingaben: neurissbildung, rissbreite_erwartet_mm (mm), rissversatz_erwartet_mm (mm) – alle drei müssen belegt sein, 0 bei „keine“. Ergebnis r_klasse_code kontrolliert die manuelle Rissklasse.
[EN] Derives the crack-class code from the Tab. 18 criteria: no new cracking → 0 (R0-B); otherwise crack width ≤ 0.2 mm → 1 (R1-B), ≤ 0.5 mm → 2 (R2-B), ≤ 1.0 mm with crack offset ≤ 0.5 mm → 3 (R3-B); anything beyond → 9 (no printed class). Inputs: neurissbildung, rissbreite_erwartet_mm (mm), rissversatz_erwartet_mm (mm) – all three must be filled, 0 for ''none''. The result r_klasse_code cross-checks the manual crack class.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-05' AND x.equation_number = 'FLL-GAR-05-D2';
UPDATE fields x SET description = 'Ja, wenn das Baugrundgutachten eine dem Einzelfall angemessene, ausreichende Tragfähigkeit und Ebenheit belegt. Maßstab der Richtlinien: mindestens ein Verformungsmodul Ev2 ≥ 45 MPa mit Ev2/Ev1 ≤ 2,5; der Verdichtungsgrad soll DPr ≥ 97 % betragen (§ 4.6). Die Messwerte gehören in die Felder Ev2, Ev1 und DPr (Tore REQ-31/REQ-32); Pflichtfeld für Tor REQ-07.
[EN] Yes when the geotechnical report shows sufficient bearing capacity and evenness appropriate to the case. The guideline''s benchmark: at least a deformation modulus Ev2 ≥ 45 MPa with Ev2/Ev1 ≤ 2.5; the degree of compaction should be DPr ≥ 97 % (§ 4.6). Enter the measured values in the Ev2, Ev1 and DPr fields (gates REQ-31/REQ-32); required for gate REQ-07.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-06' AND x.symbol = 'baugrund_tragfaehig';
UPDATE fields x SET description = 'Bodenart des Baugrunds in Worten aus dem Baugrundgutachten (z. B. Kies-Sand, Lehm, Ton). Der Baugrund soll von einheitlicher bodenphysikalischer Beschaffenheit sein (§ 4.6); Bodenart und Bodenkennwerte sind ein Kriterium der Systemwahl (§ 4.7). Die Bodengruppe nach DIN 18196 für die Schutzlagen-Tabelle 26 wird separat in FLL-GAR-22 gewählt. Pflichtfeld für Tor REQ-07.
[EN] Soil type of the subgrade in words from the geotechnical report (e.g. gravel-sand, loam, clay). The subgrade should be of uniform soil-physical character (§ 4.6); soil type and parameters are a criterion for the system choice (§ 4.7). The DIN 18196 soil group for the protection-layer Table 26 is selected separately in FLL-GAR-22. Required for gate REQ-07.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-06' AND x.symbol = 'baugrund_typ';
UPDATE fields x SET description = 'Ja, wenn nach Baugrundgutachten Setzungen zu erwarten sind (z. B. bei aufgefülltem Bodenmaterial). Die Abdichtung muss Bewegungen und Risse durch Setzungen dauerhaft aufnehmen bzw. überbrücken (§ 4.4); bei erwarteten Setzungen ist im Randbereich eine Nachverdichtung erforderlich (§ 9.2). Größe und Art der Bewegungen müssen bei der Planung vorliegen (§ 4.4) und fließen in die Rissklasse (FLL-GAR-05) ein. Pflichtfeld für Tor REQ-07.
[EN] Yes if settlements are expected according to the geotechnical report (e.g. with filled soil). The sealing must permanently accommodate movements and bridge cracks caused by settlement (§ 4.4); where settlements are expected, re-compaction of the edge zone is required (§ 9.2). Size and kind of movements must be known at design stage (§ 4.4) and feed the crack class (FLL-GAR-05). Required for gate REQ-07.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-06' AND x.symbol = 'setzungen_zu_erwarten';
UPDATE fields x SET description = 'Verformungsmodul Ev2 (Zweitbelastung) des Baugrunds in MPa aus der Baugrundprüfung (z. B. Plattendruckversuch, Prüfbericht). Die Richtlinien verlangen für eine anforderungsgerechte Tragfähigkeit mindestens Ev2 ≥ 45 MPa (§ 4.6). Eingang der Gleichung FLL-GAR-06-D1 (Verhältnis Ev2/Ev1) und des Sperrtors REQ-31.
[EN] Deformation modulus Ev2 (second loading) of the subgrade in MPa from the subgrade test (e.g. plate-load test report). The guideline requires at least Ev2 ≥ 45 MPa for adequate bearing capacity (§ 4.6). Input to equation FLL-GAR-06-D1 (ratio Ev2/Ev1) and to blocking gate REQ-31.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-06' AND x.symbol = 'baugrund_ev2_mpa';
UPDATE fields x SET description = 'Verformungsmodul Ev1 (Erstbelastung) des Baugrunds in MPa aus derselben Prüfung wie Ev2. Dient nur dem Verhältnis Ev2/Ev1, das nach § 4.6 höchstens 2,5 betragen darf (Gleichung FLL-GAR-06-D1, Tor REQ-31). Ohne Ev1 ist das Verhältnis nicht berechenbar und das Tor nicht entscheidbar.
[EN] Deformation modulus Ev1 (first loading) of the subgrade in MPa from the same test as Ev2. Used only for the ratio Ev2/Ev1, which per § 4.6 may be at most 2.5 (equation FLL-GAR-06-D1, gate REQ-31). Without Ev1 the ratio cannot be computed and the gate is undecidable.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-06' AND x.symbol = 'baugrund_ev1_mpa';
UPDATE fields x SET description = 'Berechnetes Verhältnis Ev2/Ev1 (Gleichung FLL-GAR-06-D1, dimensionslos). Maß für die Verdichtung: § 4.6 fordert Ev2/Ev1 ≤ 2,5 neben Ev2 ≥ 45 MPa. Nicht eingeben; Tor REQ-31 prüft den Wert.
[EN] Computed ratio Ev2/Ev1 (equation FLL-GAR-06-D1, dimensionless). Indicator of compaction: § 4.6 requires Ev2/Ev1 ≤ 2.5 in addition to Ev2 ≥ 45 MPa. Not an entry; gate REQ-31 checks the value.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-06' AND x.symbol = 'baugrund_ev2_ev1';
UPDATE fields x SET description = 'Verdichtungsgrad DPr des Baugrunds in % der Proctordichte aus der Verdichtungskontrolle. Die Richtlinien formulieren als Soll-Wert DPr ≥ 97 % (§ 4.6, „soll“); deshalb nur Warntor REQ-32, keine Sperre. Prüfbericht als Nachweis ablegen.
[EN] Degree of compaction DPr of the subgrade in % of Proctor density from the compaction control. The guideline states it as a target: DPr ≥ 97 % (§ 4.6, ''should''); hence only warning gate REQ-32, no block. File the test report as evidence.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-06' AND x.symbol = 'baugrund_dpr_pct';
UPDATE equations x SET description = 'Verhältnis der Verformungsmoduln Ev2/Ev1 (beide in MPa aus der Baugrundprüfung, Ergebnis dimensionslos). § 4.6 nennt die Bedingung in Klammern hinter Ev2 ≥ 45 MPa: Ev2/Ev1 ≤ 2,5. Keine gedruckte Formel, nur der Quotient; das Ergebnis baugrund_ev2_ev1 geht in das Sperrtor REQ-31.
[EN] Ratio of the deformation moduli Ev2/Ev1 (both in MPa from the subgrade test, result dimensionless). § 4.6 states the condition in brackets after Ev2 ≥ 45 MPa: Ev2/Ev1 ≤ 2.5. No printed formula, just the quotient; the result baugrund_ev2_ev1 feeds blocking gate REQ-31.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-06' AND x.equation_number = 'FLL-GAR-06-D1';
UPDATE compliance_requirements x SET description = 'Besteht, wenn Baugrund-Typ eingetragen ist und „tragfähig“ sowie „Setzungen zu erwarten“ beantwortet sind (Ja oder Nein). Die Richtlinien verlangen einen Baugrund mit angemessener Tragfähigkeit und Ebenheit und ggf. Voruntersuchungen zu Bodenkennwerten, hydrologischen Verhältnissen, Wurzelwachstum und Geländelage (§ 4.6); Setzungen müssen von der Abdichtung aufgenommen werden (§ 4.4). Sperrtor: alle drei Felder belegen.
[EN] Passes when the subsoil type is entered and ''bearing capacity adequate'' and ''settlements expected'' are answered (yes or no). The guideline requires a subgrade with adequate bearing capacity and evenness and, where needed, preliminary tests on soil parameters, hydrology, root growth and terrain (§ 4.6); settlements must be accommodated by the sealing (§ 4.4). Blocking gate: fill all three fields.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-06' AND x.code = 'REQ-07';
UPDATE compliance_requirements x SET description = 'Besteht, wenn Ev2 ≥ 45 MPa und das berechnete Verhältnis Ev2/Ev1 ≤ 2,5 ist. Dazu Ev2 und Ev1 (MPa) aus der Baugrundprüfung eintragen; das Verhältnis liefert Gleichung FLL-GAR-06-D1. Die Richtlinien nennen diese Werte als „mindestens … erforderlich“ für eine anforderungsgerechte Tragfähigkeit (§ 4.6) – daher Sperrtor. Bei Unterschreitung Baugrund verbessern (Planum, Kalk-/Zementzugabe, Geogitter, Austausch, § 4.6) und erneut prüfen.
[EN] Passes when Ev2 ≥ 45 MPa and the computed ratio Ev2/Ev1 ≤ 2.5. Enter Ev2 and Ev1 (MPa) from the subgrade test; equation FLL-GAR-06-D1 supplies the ratio. The guideline names these values as ''at least … required'' for adequate bearing capacity (§ 4.6) – hence a blocking gate. If not met, improve the subgrade (formation, lime/cement addition, geogrids, replacement, § 4.6) and retest.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-06' AND x.code = 'REQ-31';
UPDATE compliance_requirements x SET description = 'Warnt, wenn der Verdichtungsgrad DPr unter 97 % liegt. Dazu DPr (%) aus der Verdichtungskontrolle eintragen. Die Richtlinien formulieren „soll DPr ≥ 97 % betragen“ (§ 4.6) – eine Soll-Anforderung, daher Warnung statt Sperre; Abweichungen begründen und nachverdichten.
[EN] Warns when the degree of compaction DPr is below 97 %. Enter DPr (%) from the compaction control. The guideline says ''should be DPr ≥ 97 %'' (§ 4.6) – a ''should'' requirement, hence a warning rather than a block; justify deviations and re-compact.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-06' AND x.code = 'REQ-32';
UPDATE fields x SET description = 'Steilste geplante Böschungsneigung als Verhältnis 1:m (z. B. „1:3“) aus den Profilschnitten. Richtwerte nach Tab. 1 je Abdichtungsart: Grubentone/Lehm, vergütete Böden, Asphaltmastix, GTD, Bitumenbahnen ≤ 1:3; Ortbeton, Asphaltbeton ≤ 1:2; Gussasphalt ≤ 1:5; Kunststoff-/Elastomerbahnen und PEHD ≤ 1:1,5; Flüssigkunststoffe ≤ 1:1. Für Bauweisen mit systembedingter Auflast gilt i. d. R. ≤ 1:3 (§ 4.5). Die Richtwerte entbinden nicht von einer rechnerischen Überprüfung der Stand- und Gleitsicherheit (§ 4.5).
[EN] Steepest planned slope as a ratio 1:m (e.g. ''1:3'') from the profile sections. Guide values per Tab. 1 by sealing type: pit clays/loam, treated soils, asphalt mastic, GCL, bituminous sheets ≤ 1:3; in-situ concrete, asphalt concrete ≤ 1:2; mastic asphalt ≤ 1:5; plastic/elastomer sheets and PEHD ≤ 1:1.5; liquid plastics ≤ 1:1. For systems with ballast layers ≤ 1:3 applies as a rule (§ 4.5). The guide values do not replace a calculated stability and sliding check (§ 4.5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-07' AND x.symbol = 'boeschungsneigung_ratio';
UPDATE fields x SET description = 'Dasselbe Gefälle in Prozent (Spalte 3 der Tab. 1): ≤ 33 % für 1:3-Bauweisen, ≤ 50 % für Ortbeton und Asphaltbeton, ≤ 20 % für Gussasphalt, ≤ 66 % für Kunststoff-/Elastomerbahnen und PEHD, ≤ 100 % für Flüssigkunststoffe. Für Bauweisen mit Auflast i. d. R. ≤ 33 % (§ 4.5). Abweichende nutzungsbedingte Anforderungen (z. B. senkrechte Wände bei Schwimmteichen) erfordern besondere planerische Maßnahmen (Tab. 1, Folgetext).
[EN] The same gradient in percent (column 3 of Tab. 1): ≤ 33 % for 1:3 systems, ≤ 50 % for in-situ concrete and asphalt concrete, ≤ 20 % for mastic asphalt, ≤ 66 % for plastic/elastomer sheets and PEHD, ≤ 100 % for liquid plastics. For systems with ballast ≤ 33 % as a rule (§ 4.5). Deviating use-related requirements (e.g. vertical walls in swimming ponds) need special design measures (text after Tab. 1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-07' AND x.symbol = 'gefaelle_percent';
UPDATE fields x SET description = 'Register: eine Zeile je Böschungsabschnitt mit Zone (z. B. Sumpf-, Flach-, Tiefwasserzone bei naturnaher Profilierung, § 4.5), Neigung 1:m, Gefälle in % und Länge. Je Zeile wird der Tab.-1-Richtwert der in FLL-GAR-09 gewählten Abdichtungsart eingeblendet (Spalte „ok“). Aus den Zeilen berechnet das Blatt die steilste Böschung (FLL-GAR-07-D1) und die Zahl der Abschnitte steiler als der Richtwert (FLL-GAR-07-D2). Richtwerte hängen von Bodenart und Kontaktreibungsfläche ab; in Zweifelsfällen Scherversuche (§ 4.5).
[EN] Register: one row per slope section with zone (e.g. marsh, shallow-water, deep-water zone for near-natural profiling, § 4.5), slope 1:m, gradient in % and length. Each row shows the Tab. 1 guide value of the sealing type chosen in FLL-GAR-09 (column ''ok''). From the rows the sheet computes the steepest slope (FLL-GAR-07-D1) and the number of sections steeper than the guide value (FLL-GAR-07-D2). Guide values depend on soil type and contact friction; in doubt run shear tests (§ 4.5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-07' AND x.symbol = 'boeschungsabschnitte';
UPDATE fields x SET description = 'Nachgeschlagener Richtwert aus Tab. 1 für die in FLL-GAR-09 gewählte Abdichtungsart, als m von 1:m (größer = flacher): 3 für Grubentone/Lehm, vergütete Böden, Asphaltmastix, GTD und Bitumenbahnen; 2 für Ortbeton und Asphaltbeton; 5 für Gussasphalt; 1,5 für Kunststoff-/Elastomerbahnen und PEHD; 1 für Flüssigkunststoffe. Für Asphalt gibt Tab. 1 drei Zeilen nach Mischgutart (Asphaltmastix, Gussasphalt, Asphaltbeton); für Stahl, Alkalisilikate und GUP druckt Tab. 1 keine Zeile. Nicht eingeben; Vergleichswert zur steilsten Böschung.
[EN] Looked-up guide value from Tab. 1 for the sealing type chosen in FLL-GAR-09, as m of 1:m (larger = flatter): 3 for pit clays/loam, treated soils, asphalt mastic, GCL and bituminous sheets; 2 for in-situ concrete and asphalt concrete; 5 for mastic asphalt; 1.5 for plastic/elastomer sheets and PEHD; 1 for liquid plastics. For asphalt Tab. 1 prints three rows by mix type (asphalt mastic, mastic asphalt, asphalt concrete); for steel, alkali silicates and GRP Tab. 1 prints no row. Not an entry; comparison value for the steepest slope.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-07' AND x.symbol = 'boeschungsneigung_limit';
UPDATE fields x SET description = 'Berechnet (Gleichung FLL-GAR-07-D1): kleinstes m aller Zeilen des Registers Böschungsabschnitte = steilste Böschung des Gewässers in der Schreibweise 1:m. Nicht eingeben; wird mit dem Tab.-1-Richtwert der Abdichtungsart verglichen (§ 4.5).
[EN] Computed (equation FLL-GAR-07-D1): smallest m of all rows of the slope-section register = steepest slope of the water body in 1:m notation. Not an entry; compared with the Tab. 1 guide value of the sealing type (§ 4.5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-07' AND x.symbol = 'boeschung_steilste_1m';
UPDATE fields x SET description = 'Berechnet (Gleichung FLL-GAR-07-D2): Anzahl der Böschungsabschnitte, deren Neigung steiler ist als der Tab.-1-Richtwert der gewählten Abdichtungsart. 0 = alle Abschnitte innerhalb der Richtwerte. Ist die Abdichtungsart in FLL-GAR-09 noch nicht gewählt oder hat sie keine Tab.-1-Zeile (Stahl, Alkalisilikate, GUP), bleibt der Wert unentscheidbar. Nicht eingeben.
[EN] Computed (equation FLL-GAR-07-D2): number of slope sections whose slope is steeper than the Tab. 1 guide value of the chosen sealing type. 0 = all sections within the guide values. If the sealing type is not yet chosen in FLL-GAR-09 or has no Tab. 1 row (steel, alkali silicates, GRP), the value stays undecidable. Not an entry.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-07' AND x.symbol = 'boeschung_verletzungen';
UPDATE equations x SET description = 'Steilste Böschung = Minimum von m über alle Zeilen des Registers Böschungsabschnitte (Spalte Neigung 1:m). Kleineres m bedeutet steiler. Keine gedruckte Formel – reine Auswertung der Zonen (Sumpf-, Flach-, Tiefwasserzone, § 4.5); das Ergebnis wird dem werkstoffspezifischen Richtwert der Tab. 1 gegenübergestellt.
[EN] Steepest slope = minimum of m over all rows of the slope-section register (column slope 1:m). Smaller m means steeper. No printed formula – a pure evaluation of the zones (marsh, shallow-water, deep-water zone, § 4.5); the result is set against the material-specific guide value of Tab. 1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-07' AND x.equation_number = 'FLL-GAR-07-D1';
UPDATE equations x SET description = 'Zählt die Zeilen des Registers Böschungsabschnitte, deren Spalte „ok“ 0 ist, d. h. deren Neigung steiler ist als der Tab.-1-Richtwert der Abdichtungsart (z. B. 1:3 für Bitumenbahnen, 1:1,5 für Kunststoffbahnen). Keine gedruckte Formel. Tab. 1 enthält Richtwerte; sie entbinden nicht von einer rechnerischen Überprüfung der Stand- und Gleitsicherheit, z. B. mittels Scherversuchen (§ 4.5).
[EN] Counts the rows of the slope-section register whose column ''ok'' is 0, i.e. whose slope is steeper than the Tab. 1 guide value of the sealing type (e.g. 1:3 for bituminous sheets, 1:1.5 for plastic sheets). No printed formula. Tab. 1 gives guide values; they do not replace a calculated stability and sliding check, e.g. by shear tests (§ 4.5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-07' AND x.equation_number = 'FLL-GAR-07-D2';
UPDATE compliance_requirements x SET description = 'Warnhinweis ohne automatische Bedingung: Jede Böschung soll den werkstoffspezifischen Richtwert der Tab. 1 einhalten (z. B. ≤ 1:3 / ≤ 33 % für Grubentone, GTD und Bitumenbahnen; ≤ 1:2 / ≤ 50 % für Ortbeton und Asphaltbeton; ≤ 1:5 / ≤ 20 % für Gussasphalt; ≤ 1:1,5 / ≤ 66 % für Kunststoff-/Elastomerbahnen und PEHD; ≤ 1:1 / ≤ 100 % für Flüssigkunststoffe). Dazu Abdichtungsart (FLL-GAR-09), Neigung/Gefälle und das Register der Böschungsabschnitte eintragen und FLL-GAR-07-D2 = 0 anstreben. Steilere Böschungen sind möglich, erfordern aber rechnerische Stand-/Gleitsicherheit bzw. besondere planerische Maßnahmen (§ 4.5).
[EN] Warning without an automatic condition: every slope should respect the material-specific guide value of Tab. 1 (e.g. ≤ 1:3 / ≤ 33 % for pit clays, GCL and bituminous sheets; ≤ 1:2 / ≤ 50 % for in-situ concrete and asphalt concrete; ≤ 1:5 / ≤ 20 % for mastic asphalt; ≤ 1:1.5 / ≤ 66 % for plastic/elastomer sheets and PEHD; ≤ 1:1 / ≤ 100 % for liquid plastics). Enter the sealing type (FLL-GAR-09), slope/gradient and the slope-section register and aim for FLL-GAR-07-D2 = 0. Steeper slopes are possible but need a calculated stability/sliding check or special design measures (§ 4.5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-07' AND x.code = 'REQ-08';
UPDATE compliance_requirements x SET description = 'Warnhinweis ohne automatische Bedingung: Das gewählte Abdichtungssystem muss zu Nutzung, Einwirkungen, Wurzel-/Rhizomregime und Geometrie passen. § 4.7 nennt die Kriterien: Nutzungsart und Intensität, Dimensionierung/Profilierung/Neigung, Art des Bauwerks, Baugrund, Klima, bauliche Vorgaben (Randausbildung, Anschlüsse, Durchdringungen, Einbauten), Flora und Fauna (Wurzel-/Rhizomfestigkeit), Nutzungsdauer, Instandhaltung, Umweltverträglichkeit, Wasserqualität, werkstoffspezifische Eigenschaften. Abdichtungsart in FLL-GAR-09 wählen und mit -04, -05, -06 und -24 abgleichen; nicht wurzelfeste Abdichtungen brauchen ggf. eine FLL-geprüfte Wurzelschutzbahn (§ 4.7).
[EN] Warning without an automatic condition: the chosen sealing system must suit use, loads, root/rhizome regime and geometry. § 4.7 lists the criteria: type and intensity of use, dimensioning/profiling/slope, type of structure, subgrade, climate, structural constraints (edge design, connections, penetrations, installations), flora and fauna (root/rhizome resistance), service life, maintenance, environmental compatibility, water quality, material-specific properties. Select the sealing type in FLL-GAR-09 and reconcile it with use (-04), loads (-05), subgrade (-06) and planting (-24); non-root-resistant sealings may need an FLL-tested root barrier (§ 4.7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-07' AND x.code = 'REQ-09';
UPDATE fields x SET description = 'Form des Beckens/Gewässers in Worten (z. B. frei modelliert, rechteckig, mit senkrechten Wänden) aus Lageplan und Schnitten. Die „Art des Bauwerks (z. B. Beckenform, gewachsener Boden)“ ist ein Kriterium der Wahl des Abdichtungssystems (§ 4.7); senkrechte Wände bei Schwimmteichen erfordern besondere planerische Maßnahmen (§ 4.5). Keine Rechenprüfung.
[EN] Shape of the basin/water body in words (e.g. free-form, rectangular, with vertical walls) from site plan and sections. The ''type of structure (e.g. basin shape, natural ground)'' is a criterion for the choice of sealing system (§ 4.7); vertical walls in swimming ponds need special design measures (§ 4.5). No numeric check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-08' AND x.symbol = 'beckenform';
UPDATE fields x SET description = 'Maximale Wassertiefe in m (Planung, Schnitt) – gleicher Wert wie die Gewässertiefe in FLL-GAR-04. Teil der Dimensionierung („Volumen, Tiefe“, § 4.1); Wassertiefe und Beanspruchung bestimmen Art und Anordnung der Schutzlagen (§ 8.1). Keine Rechenprüfung auf diesem Blatt.
[EN] Maximum water depth in m (design, section) – same value as the water depth in FLL-GAR-04. Part of dimensioning (''volume, depth'', § 4.1); water depth and loading govern type and arrangement of protection layers (§ 8.1). No numeric check on this sheet.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-08' AND x.symbol = 'wassertiefe_max';
UPDATE fields x SET description = 'Fläche des Wasserspiegels in m² beim Höchstwasserstand (Lageplan). Grundlage für die Überlaufbemessung: Die Leistungsfähigkeit der Überlaufeinrichtung hängt von Standort, Gewässergröße und Fremdwassereinleitung ab; Regelüberlauf in Anlehnung an DIN 1986-100 mit örtlicher 5-Jahres-Regenspende r5,5, Notüberlauf an Gebäuden mit r5,100 (§ 4.10). Keine Rechenprüfung auf diesem Blatt.
[EN] Water-surface area in m² at maximum water level (site plan). Basis for overflow sizing: the capacity of the overflow device depends on site, water-body size and external inflow; regular overflow in line with DIN 1986-100 with the local 5-year rainfall r5,5, emergency overflow at buildings with r5,100 (§ 4.10). No numeric check on this sheet.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-08' AND x.symbol = 'wasserspiegelflaeche';
UPDATE fields x SET description = 'Beckenvolumen in m³ (Planung) – entspricht dem Gewässervolumen in FLL-GAR-04. Teil der Dimensionierung nach § 4.1 („Volumen, Tiefe“); Eingang der Systemwahl (§ 4.7). Keine Rechenprüfung.
[EN] Basin volume in m³ (design) – corresponds to the water-body volume in FLL-GAR-04. Part of dimensioning per § 4.1 (''volume, depth''); input to the system choice (§ 4.7). No numeric check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-08' AND x.symbol = 'beckenvolumen';
UPDATE fields x SET description = 'Länge der Abdichtungsoberkante (Umfang des Gewässerrands) in m aus dem Lageplan. Mengenangabe für Randausbildung, Randbefestigung und Kapillarsperre (FLL-GAR-23); die Richtlinien nennen keinen Grenzwert. Keine Prüfung.
[EN] Length of the top edge of the sealing (perimeter of the water-body edge) in m from the site plan. Quantity for edge design, edge fastening and capillary barrier (FLL-GAR-23); the guideline gives no limit. No check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-08' AND x.symbol = 'umfang_oberkante';
UPDATE fields x SET description = 'Lage und Art der Überlaufeinrichtung in Worten (z. B. Überlaufrinne Nordufer, Ablauf mit Sieb). Überlaufeinrichtungen leiten Überschusswasser kontrolliert ab – über den Gewässerrand und/oder technische Einrichtungen; ihre Höhe gibt der geplante maximale Wasserstand vor; Abläufe sind durch Siebe oder Gitter zu schützen und die Randbefestigung ist auf die Überlaufeinrichtung abzustimmen (§ 4.10).
[EN] Position and kind of the overflow device in words (e.g. overflow channel north bank, outlet with screen). Overflow devices discharge surplus water in a controlled way – over the edge and/or via technical devices; their height is set by the planned maximum water level; outlets must be protected by screens or grates and the edge fastening matched to the overflow device (§ 4.10).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-08' AND x.symbol = 'ueberlauf_position';
UPDATE fields x SET description = 'Beschreibung der Zugänge für Wartung und Pflege (z. B. Einstieg, Pflegeweg, Lage befahrbarer Randflächen). Randausbildungen sollen Zugangsmöglichkeiten schaffen (§ 4.8); Ein- und Ausstiegsmöglichkeiten für Reinigungs-/Wartungsgeräte und begeh-/befahrbare Randflächen bestimmen die Art der Randausbildung (§ 9.1). Begangene/befahrene Bereiche brauchen eine obere Schutzlage nach Schutzwirksamkeitsklasse (§ 8.3.2, Tab. 27; FLL-GAR-22).
[EN] Description of access for maintenance and care (e.g. entry point, maintenance path, location of trafficable edge areas). Edge designs should provide access (§ 4.8); entry/exit for cleaning and maintenance equipment and walkable/trafficable edge areas govern the type of edge design (§ 9.1). Walked-on/trafficked areas need an upper protection layer per protection-effectiveness class (§ 8.3.2, Tab. 27; FLL-GAR-22).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-08' AND x.symbol = 'zugang_wartung';
UPDATE fields x SET description = 'Ja, wenn das Gewässer an aufgehenden Gebäudeteilen ausgeführt wird oder direkten Kontakt zu ihnen hat (Lageplan). Dann ist ein Notüberlauf mit kanalunabhängigem Entwässerungskonzept nach DIN 1986-100 mit örtlicher 100-Jahres-Regenspende r5,100 zu dimensionieren (§ 4.10; § 9.1) – Pflicht, die das Überlaufblatt FLL-GAR-27 prüft. Außerdem gilt am aufgehenden Bauteil die Überhöhung von i. d. R. 30 cm (§ 4.8).
[EN] Yes if the water body is built against rising building parts or in direct contact with them (site plan). Then an emergency overflow with a sewer-independent drainage concept per DIN 1986-100 and the local 100-year rainfall r5,100 must be sized (§ 4.10; § 9.1) – a duty checked on the overflow sheet FLL-GAR-27. In addition the upstand of as a rule 30 cm at the rising structure applies (§ 4.8).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-08' AND x.symbol = 'gewaesser_an_gebaeudeteilen';
UPDATE fields x SET description = 'Gewählte Abdichtungsbauweise. Die Richtlinien behandeln mineralische Stoffe ohne/mit Zusatzstoffen, mit hydraulischen Bindemitteln (Beton) und mit Bitumen (Asphalt), Verbundwerkstoffe (GTD), Bitumenbahnen, Kunststoff-/Elastomerbahnen, Flüssigkunststoffe, PE-Bahnen (PELD/PEHD), Stahl, Alkalisilikate und GUP. Die Wahl hängt u. a. von Nutzung, Dimensionierung/Neigung, Bauwerk, Baugrund, Klima, Anschlüssen, Flora/Fauna, Nutzungsdauer und Umweltverträglichkeit ab (§ 4.7). Steuert den Tab.-1-Richtwert (FLL-GAR-07), die Tore REQ-05/REQ-11/REQ-17 und die Materialblätter.
[EN] Chosen sealing construction. The guideline covers mineral materials without/with additives, with hydraulic binders (concrete) and with bitumen (asphalt), composites (GCL), bituminous sheets, plastic/elastomer sheets, liquid plastics, PE sheets (PELD/PEHD), steel, alkali silicates and GRP. The choice depends among other things on use, dimensioning/slope, structure, subgrade, climate, connections, flora/fauna, service life and environmental compatibility (§ 4.7). Drives the Tab. 1 guide value (FLL-GAR-07), gates REQ-05/REQ-11/REQ-17 and the material sheets.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-09' AND x.symbol = 'abdichtungs_art';
UPDATE fields x SET description = 'Anzahl der Abdichtungslagen (ohne Schutzlagen) nach Planung/Herstellerangabe. Die Art der Abdichtungsstoffe, die Anzahl der Lagen und deren Anordnung müssen zusammen die Funktion sicherstellen (§ 4.7). Bitumenbahnen sind i. d. R. mehrlagig herzustellen (§ 6.1.1.2) – Warntor REQ-17 erwartet ≥ 2; Abdichtungen aus PE werden i. d. R. einlagig ausgeführt (§ 6.4.1.2). Bei Verzicht auf Schutzlagen (z. B. Schwimmteiche) sind Mehrdicken oder Mehrlagigkeit erforderlich (§ 8.1).
[EN] Number of sealing layers (excluding protection layers) per design/manufacturer. Type of sealing materials, number of layers and their arrangement must together ensure the function (§ 4.7). Bituminous sheets are as a rule multi-layer (§ 6.1.1.2) – warning gate REQ-17 expects ≥ 2; PE sealings are as a rule single-layer (§ 6.4.1.2). Where protection layers are omitted (e.g. swimming ponds), extra thickness or multiple layers are required (§ 8.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-09' AND x.symbol = 'anzahl_lagen';
UPDATE fields x SET description = 'Bestätigung, dass für die gewählten Abdichtungsprodukte die rechtliche Einhaltung von CE-Kennzeichnung, EU-Bauproduktenverordnung und MVV-TB für die jeweilige Anwendung geprüft wurde (§ 4.7; Leistungserklärungen/Datenblätter ablegen). Sperrtor REQ-10 besteht nur bei Ja.
[EN] Confirmation that legal compliance of the chosen sealing products with CE marking, the EU Construction Products Regulation and MVV-TB has been checked for the application (§ 4.7; file declarations of performance/data sheets). Blocking gate REQ-10 passes only with yes.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-09' AND x.symbol = 'ce_kennzeichnung_geprueft';
UPDATE fields x SET description = 'Ja, wenn der Auftraggeber einen Dichtigkeitsnachweis der Abdichtung fordert. Dann ist der Nachweis gemäß den werkstoff- bzw. bauweisenspezifischen Anforderungen vertraglich zu vereinbaren; besonders zu berücksichtigen bei geforderter Wurzel-/Rhizomfestigkeit oder möglicher Faltenbildung (§ 4.1). Vertragliche Festlegung dokumentieren.
[EN] Yes if the client demands a tightness proof of the sealing. It must then be agreed contractually according to the material- or method-specific requirements; to be considered especially where root/rhizome resistance is required or wrinkling cannot be excluded (§ 4.1). Document the contractual agreement.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-09' AND x.symbol = 'dichtigkeitsnachweis_required';
UPDATE fields x SET description = 'Ja, wenn Wurzel- und Rhizomfestigkeit gefordert ist – im Einzelfall ist der Nachweis zu führen; bei vorgesehener Bepflanzung nach dem FLL-Verfahren für Dachbegrünungen, Mindestanforderung ist das Testat „rhizomfest gegen Quecken“; bei wurzelaggressiven/rhizombildenden Arten (z. B. Phragmites australis) zusätzlich die Prüfung der Rhizomfestigkeit von Gewässerabdichtungen (§ 4.3; § 10.4). Stahl, Beton, PEHD gelten als wurzel-/rhizomfest ohne gesonderten Nachweis (§ 10.4). Nachweise in FLL-GAR-22 bestätigen.
[EN] Yes if root and rhizome resistance is required – the proof must be provided case by case; with planned planting per the FLL green-roof procedure, minimum requirement is the certificate ''rhizome-proof against couch grass''; with root-aggressive/rhizome-forming species (e.g. Phragmites australis) additionally the rhizome-resistance test for water-body sealings (§ 4.3; § 10.4). Steel, concrete, PEHD count as root-/rhizome-resistant without separate proof (§ 10.4). Confirm the proofs in FLL-GAR-22.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-09' AND x.symbol = 'wurzel_rhizomfestigkeit_required';
UPDATE fields x SET description = 'Register des Schichtaufbaus: eine Zeile je Funktionsschicht mit Rolle (Abdichtung, Schutzlage unten, Schutzlage oben, Auflast), Abdichtungsart, Dicke in mm und Flächengewicht. Die Richtlinien verlangen, dass Art der Abdichtungsstoffe, Anzahl der Lagen und deren Anordnung zusammen die Funktion sicherstellen (§ 4.7). Abdichtungszeilen erhalten den Tab.-1-Richtwert, Schutzlagen unten die Sand-Mindestdicke und Werkstoffe nach Tab. 26, Schutzlagen oben das SWK-Mindestflächengewicht nach Tab. 27. Summe und Anzahl der Abdichtungszeilen liefern FLL-GAR-09-D1/-D2.
[EN] Register of the layer build-up: one row per functional layer with role (sealing, lower protection layer, upper protection layer, ballast), sealing type, thickness in mm and mass per unit area. The guideline requires that material type, number of layers and their arrangement together ensure the function (§ 4.7). Sealing rows get the Tab. 1 guide value, lower protection layers the minimum sand thickness and materials per Tab. 26, upper protection layers the SWK minimum mass per Tab. 27. Sum and count of sealing rows feed FLL-GAR-09-D1/-D2.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-09' AND x.symbol = 'abdichtungslagen';
UPDATE fields x SET description = 'Berechnet (Gleichung FLL-GAR-09-D1): Summe der Dicken aller Zeilen mit Rolle „Abdichtung“ in mm; Schutzlagen und Auflast zählen nicht. Nicht eingeben; Vergleichswert zu den Nenndicken der Materialblätter (z. B. Tab. 25 für PE: PELD ≥ 0,8/1,5 mm, PEHD ≥ 1,0/2,0/2,5 mm je nach Beanspruchung).
[EN] Computed (equation FLL-GAR-09-D1): sum of the thicknesses of all rows with role ''sealing'' in mm; protection layers and ballast do not count. Not an entry; comparison value for the nominal thicknesses of the material sheets (e.g. Tab. 25 for PE: PELD ≥ 0.8/1.5 mm, PEHD ≥ 1.0/2.0/2.5 mm depending on loading).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-09' AND x.symbol = 'lagen_gesamtdicke_mm';
UPDATE fields x SET description = 'Berechnet (Gleichung FLL-GAR-09-D2): Anzahl der Zeilen mit Rolle „Abdichtung“ im Register. Nicht eingeben; Kontrolle zur manuellen Lagenzahl. Bitumenbahnen i. d. R. mehrlagig (§ 6.1.1.2), PE i. d. R. einlagig (§ 6.4.1.2); Warntor REQ-17 liest weiterhin das manuelle Feld Anzahl Lagen.
[EN] Computed (equation FLL-GAR-09-D2): number of rows with role ''sealing'' in the register. Not an entry; cross-check for the manual layer count. Bituminous sheets as a rule multi-layer (§ 6.1.1.2), PE as a rule single-layer (§ 6.4.1.2); warning gate REQ-17 still reads the manual field number of layers.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-09' AND x.symbol = 'abdichtungslagen_count';
UPDATE equations x SET description = 'Gesamtdicke der Abdichtung = Summe der Spalte Dicke (mm) über alle Registerzeilen mit Rolle „Abdichtung“; andere Rollen gehen mit 0 ein. Keine gedruckte Formel – Auswertung des Schichtaufbaus nach § 4.7 („Anzahl der Lagen und deren Anordnung“). Ergebnis lagen_gesamtdicke_mm, Vergleichswert zu den Nenndicken der Materialblätter.
[EN] Total sealing thickness = sum of the thickness column (mm) over all register rows with role ''sealing''; other roles count 0. No printed formula – evaluation of the layer build-up per § 4.7 (''number of layers and their arrangement''). Result lagen_gesamtdicke_mm, comparison value for the nominal thicknesses of the material sheets.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-09' AND x.equation_number = 'FLL-GAR-09-D1';
UPDATE equations x SET description = 'Anzahl der Abdichtungslagen = Zahl der Registerzeilen mit Rolle „Abdichtung“. Keine gedruckte Formel. Bezug: Bitumenbahnen sind i. d. R. mehrlagig herzustellen (§ 6.1.1.2), PE-Abdichtungen i. d. R. einlagig (§ 6.4.1.2). Ergebnis abdichtungslagen_count; REQ-17 prüft weiterhin das manuelle Feld Anzahl Lagen.
[EN] Number of sealing layers = count of register rows with role ''sealing''. No printed formula. Reference: bituminous sheets are as a rule multi-layer (§ 6.1.1.2), PE sealings as a rule single-layer (§ 6.4.1.2). Result abdichtungslagen_count; REQ-17 still checks the manual field number of layers.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-09' AND x.equation_number = 'FLL-GAR-09-D2';
UPDATE compliance_requirements x SET description = 'Besteht, wenn „CE-Kennzeichnung geprüft“ auf Ja steht. Die Richtlinien verlangen, bei der Produktauswahl die rechtliche Einhaltung von CE-Kennzeichnung, EU-BauPVO und MVV-TB für die jeweilige Anwendung zu prüfen (§ 4.7). Sperrtor: Leistungserklärungen der gewählten Produkte prüfen, ablegen und das Feld bestätigen.
[EN] Passes when ''CE marking checked'' is set to yes. The guideline requires checking legal compliance with CE marking, the EU Construction Products Regulation and MVV-TB for the application when selecting products (§ 4.7). Blocking gate: check and file the declarations of performance of the chosen products and confirm the field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-09' AND x.code = 'REQ-10';
UPDATE compliance_requirements x SET description = 'Gilt nur bei Abdichtungsart Bitumenbahnen; warnt dann, wenn die Anzahl Lagen kleiner als 2 ist. Grundlage: Abdichtungen aus Bitumenbahnen sind i. d. R. mehrlagig herzustellen; zugelassene Stoffarten nach Tab. 19 (Bitumen-/Polymerbitumen-Dachdichtungsbahnen, Schweißbahnen, kaltselbstklebende Polymerbitumenbahnen, Typ BA nach DIN 18535-2) (§ 6.1.1.2; Tab. 19); der Hersteller muss zusätzlich die Wurzel-/Rhizomfestigkeit gemäß FLL nachweisen (§ 6.1.1). Zum Bestehen Anzahl Lagen ≥ 2 eintragen oder die einlagige Ausführung begründen.
[EN] Applies only to sealing type bituminous sheets; warns when the number of layers is below 2. Basis: bituminous-sheet sealings are as a rule multi-layer; permitted material types per Tab. 19 (bitumen/polymer-bitumen roofing sheets, torch-on sheets, cold self-adhesive polymer-bitumen sheets, type BA per DIN 18535-2) (§ 6.1.1.2; Tab. 19); the manufacturer must also prove root/rhizome resistance per FLL (§ 6.1.1). To pass, enter number of layers ≥ 2 or justify a single-layer design.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-09' AND x.code = 'REQ-17';
UPDATE fields x SET description = 'Kalkgehalt VCA des Abdichtungsmaterials in Masse-%, bestimmt nach DIN 18129 in der Eignungsprüfung (bei industriell aufbereiteten Böden aus dem Prüfzeugnis des Herstellers). Tab. 3 verlangt ≤ 15 Masse-%; Tor REQ-12 prüft den Wert.
[EN] Lime content VCA of the sealing material in % by mass, determined per DIN 18129 in the suitability test (for industrially processed soils from the manufacturer''s test certificate). Tab. 3 requires ≤ 15 % by mass; gate REQ-12 checks it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-10' AND x.symbol = 'kalkgehalt_VCA';
UPDATE fields x SET description = 'Durchlässigkeitsbeiwert kf der eingebauten Abdichtungsschicht in m/s aus der Eignungs- bzw. Kontrollprüfung nach DIN EN ISO 17892-11 (hydraulischer Gradient i = 30); Dezimalwert eingeben, z. B. 5e-10. Tab. 3 fordert ≤ 1·10⁻⁹ m/s („sehr schwach durchlässig“ nach Tab. 2, Wasserverlust rd. 950 m³/Jahr je 1.000 m²); Tor REQ-12 prüft den Wert. Das Einbauverfahren muss den kf-Wert über die gesamte Fläche sicherstellen (§5.1.2.1).
[EN] Permeability coefficient kf of the installed sealing layer in m/s from the suitability or control test per DIN EN ISO 17892-11 (hydraulic gradient i = 30); enter a decimal such as 5e-10. Tab. 3 requires ≤ 1·10⁻⁹ m/s (''very slightly permeable'' in Tab. 2, water loss about 950 m³/year per 1,000 m²); gate REQ-12 checks it. The installation method must secure this kf over the whole area (§5.1.2.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-10' AND x.symbol = 'kf_abdichtung';
UPDATE fields x SET description = 'Tonanteil (Korngrößen < 0,002 mm) des Abdichtungsmaterials in Masse-% aus der Korngrößenverteilung nach DIN EN ISO 17892-4 (Eignungsprüfung oder Prüfzeugnis des Herstellers). Tab. 3 verlangt ≥ 15 Masse-%; Tor REQ-12 prüft den Wert.
[EN] Clay fraction (grain sizes < 0.002 mm) of the sealing material in % by mass from the grading per DIN EN ISO 17892-4 (suitability test or manufacturer''s certificate). Tab. 3 requires ≥ 15 % by mass; gate REQ-12 checks it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-10' AND x.symbol = 'kornanteil_unter_2micron';
UPDATE fields x SET description = 'Glühverlust VGL (organische Substanz) des Abdichtungsmaterials in Masse-% nach DIN 18128, aus Eignungsprüfung oder Prüfzeugnis. Tab. 3 verlangt ≤ 5 Masse-%; Tor REQ-12 prüft den Wert.
[EN] Loss on ignition VGL (organic matter) of the sealing material in % by mass per DIN 18128, from the suitability test or certificate. Tab. 3 requires ≤ 5 % by mass; gate REQ-12 checks it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-10' AND x.symbol = 'organische_substanz_VGL';
UPDATE fields x SET description = 'Geplante bzw. eingebaute Dicke der mineralischen Abdichtungsschicht in cm (Planung/Aufmaß, Nivellement). Tab. 4 verlangt für natürlich vorkommende Böden ≥ 30 cm in 2 Lagen von ≥ 15 bis ≤ 20 cm (lagenweiser Einbau, §5.1.2.1), für industriell aufbereitete Böden ≥ 10 cm; Abweichungen von 10 % sind zulässig (Fußnote 1). Vergleichswert ist „Mindestdicke der Abdichtungsschicht nach Tab. 4“; die Oberfläche darf an keiner Stelle mehr als 2 cm von der Sollhöhe abweichen (§5.1.2.1).
[EN] Designed or installed thickness of the mineral sealing layer in cm (design/measurement, levelling). Tab. 4 requires ≥ 30 cm in 2 layers of ≥ 15 to ≤ 20 cm for naturally occurring soils (placed in layers, §5.1.2.1) and ≥ 10 cm for industrially processed soils; deviations of 10 % are permitted (footnote 1). The comparison value is ''minimum sealing-layer thickness per Tab. 4''; the surface may nowhere deviate more than 2 cm from the design level (§5.1.2.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-10' AND x.symbol = 'schichtdicke_abdichtung_cm';
UPDATE fields x SET description = 'Dicke der Auflast/Schutzschicht über der Abdichtung in cm (Planung/Aufmaß). Tab. 4 verlangt ≥ 30 cm bei natürlich vorkommenden Böden (nach Eignungsprüfung) und ≥ 20 cm bei industriell aufbereiteten Böden; 10 % Abweichung zulässig. Die Auflast besteht aus nährstoffarmen, humusfreien Böden oder Mineralgemischen, bevorzugt kalkarmer gebrochener Naturstein 8/32 mm, von der Abdichtung durch eine Trennschicht (Geotextil GRK 4 oder Sand 0/2 in mind. 10 cm) getrennt (§5.1.2). Vergleichswert: „Mindestdicke der Auflast nach Tab. 4“.
[EN] Thickness of the surcharge/protection layer above the sealing in cm (design/measurement). Tab. 4 requires ≥ 30 cm for naturally occurring soils (after the suitability test) and ≥ 20 cm for industrially processed soils; a 10 % deviation is permitted. The layer consists of nutrient-poor, humus-free soil or mineral mixes, preferably low-lime crushed natural stone 8/32 mm, separated from the sealing by a separation layer (geotextile GRK 4 or sand 0/2, at least 10 cm) (§5.1.2). Comparison value: ''minimum surcharge thickness per Tab. 4''.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-10' AND x.symbol = 'schichtdicke_auflast_cm';
UPDATE fields x SET description = 'Verdichtungsgrad DPr der eingebauten Abdichtungsschicht in % der Proctordichte, bestimmt nach DIN 18125-2 (Kontrollprüfung nach Einbau, §5.1.3.3). Tab. 3 verlangt ≥ 97 %, und zwar an allen Stellen, auch an Anschlüssen und Durchdringungen (§5.1.2.1); Tor REQ-12 prüft den Wert.
[EN] Degree of compaction DPr of the installed sealing layer in % of Proctor density, determined per DIN 18125-2 (control test after installation, §5.1.3.3). Tab. 3 requires ≥ 97 % everywhere, including at connections and penetrations (§5.1.2.1); gate REQ-12 checks it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-10' AND x.symbol = 'verdichtungsgrad_Dpr';
UPDATE fields x SET description = 'Wahl der Tab.-4-Zeile: „natürlich vorkommende Böden“ (rohe oder homogenisierte Grubentone/Lehme, Eignungsprüfung vor dem Einbau) oder „industriell aufbereitete Böden“ (z. B. vakuumverpresste Grubentone als Teichbauelemente, Eigenschaften vorab durch Prüfzeugnis des Herstellers nachgewiesen). Die Wahl bestimmt die Mindestdicken von Abdichtung und Auflast nach Tab. 4.
[EN] Choose the Tab. 4 row: ''naturally occurring soils'' (raw or homogenised pit clays/loams, suitability test before installation) or ''industrially processed soils'' (e.g. vacuum-extruded pit clays as pond elements, properties proven beforehand by the manufacturer''s test certificate). The choice sets the minimum thicknesses of sealing and surcharge per Tab. 4.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-10' AND x.symbol = 'mineral_typ';
UPDATE fields x SET description = 'Wird aus Tab. 4 zum gewählten Abdichtungswerkstoff übernommen: ≥ 30 cm (in 2 Lagen von ≥ 15 bis ≤ 20 cm) bei natürlich vorkommenden Böden, ≥ 10 cm bei industriell aufbereiteten Böden. Vergleichswert für die eingegebene Schichtdicke der Abdichtung; Fußnote 1 lässt 10 % Abweichung zu. Nicht zu bearbeiten.
[EN] Filled from Tab. 4 for the chosen sealing material: ≥ 30 cm (in 2 layers of ≥ 15 to ≤ 20 cm) for naturally occurring soils, ≥ 10 cm for industrially processed soils. Comparison value for the entered sealing-layer thickness; footnote 1 allows a 10 % deviation. Not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-10' AND x.symbol = 'schichtdicke_abdichtung_min';
UPDATE fields x SET description = 'Wird aus Tab. 4 übernommen: ≥ 30 cm Auflast/Schutzschicht bei natürlich vorkommenden Böden, ≥ 20 cm bei industriell aufbereiteten Böden (10 % Abweichung zulässig, Fußnote 1). Vergleichswert für die eingegebene Auflastdicke; nicht zu bearbeiten.
[EN] Filled from Tab. 4: ≥ 30 cm surcharge/protection layer for naturally occurring soils, ≥ 20 cm for industrially processed soils (10 % deviation permitted, footnote 1). Comparison value for the entered surcharge thickness; not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-10' AND x.symbol = 'schichtdicke_auflast_min';
UPDATE fields x SET description = 'Tatsächlicher Einbauwassergehalt w der Abdichtungsschicht in Masse-%, bestimmt nach DIN 18121-2 / DIN 18127 (Kontrollprüfung, §5.1.3.3). Tab. 3 Zeile 7 verlangt wPr ≤ w ≤ w0,97Pr; liegt w ≤ wPr, muss stattdessen der Luftporenanteil na ≤ 5 % sein. Der in der Eignungsprüfung festgelegte Einbauwassergehalt ist einzuhalten (§5.1.2.1); Tor REQ-12 prüft beide Varianten.
[EN] Actual placement water content w of the sealing layer in % by mass, determined per DIN 18121-2 / DIN 18127 (control test, §5.1.3.3). Tab. 3 row 7 requires wPr ≤ w ≤ w0.97Pr; if w ≤ wPr the air-void content na must be ≤ 5 % instead. The water content fixed in the suitability test must be kept (§5.1.2.1); gate REQ-12 checks both variants.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-10' AND x.symbol = 'einbauwassergehalt_w_pct';
UPDATE fields x SET description = 'Proctor-Wassergehalt wPr des Abdichtungsmaterials in Masse-% aus dem Proctorversuch (DIN 18127) der Eignungsprüfung. Untere Grenze des Einbauwassergehalts nach Tab. 3 Zeile 7 (wPr ≤ w); unterschreitet w diesen Wert, gilt stattdessen die Luftporenbedingung na ≤ 5 %.
[EN] Proctor water content wPr of the sealing material in % by mass from the Proctor test (DIN 18127) of the suitability test. Lower bound of the placement water content per Tab. 3 row 7 (wPr ≤ w); if w falls below it, the air-void condition na ≤ 5 % applies instead.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-10' AND x.symbol = 'w_pr_pct';
UPDATE fields x SET description = 'Wassergehalt w0,97Pr auf der nassen Seite der Proctorkurve, bei dem noch 97 % der Proctordichte erreicht werden (Eignungsprüfung, DIN 18127). Obere Grenze des Einbauwassergehalts nach Tab. 3 Zeile 7 (w ≤ w0,97Pr).
[EN] Water content w0.97Pr on the wet side of the Proctor curve at which 97 % of Proctor density is still reached (suitability test, DIN 18127). Upper bound of the placement water content per Tab. 3 row 7 (w ≤ w0.97Pr).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-10' AND x.symbol = 'w_097pr_pct';
UPDATE fields x SET description = 'Luftporenanteil na der eingebauten Abdichtungsschicht in %, bestimmt nach DIN 18121-2. Nur erforderlich, wenn der Einbauwassergehalt w ≤ wPr liegt (trockene Seite): Dann verlangt Tab. 3 Zeile 7 na ≤ 5 %. Liegt w zwischen wPr und w0,97Pr, kann das Feld leer bleiben.
[EN] Air-void content na of the installed sealing layer in %, determined per DIN 18121-2. Needed only when the placement water content w ≤ wPr (dry side): then Tab. 3 row 7 requires na ≤ 5 %. If w lies between wPr and w0.97Pr the field may stay empty.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-10' AND x.symbol = 'luftporenanteil_na_pct';
UPDATE compliance_requirements x SET description = 'Gilt für mineralische Abdichtungen ohne Zusatzstoffe. Besteht, wenn alle Tab.-3-Werte eingehalten sind: Kornanteil < 0,002 mm ≥ 15 Masse-%, organische Substanz VGL ≤ 5 Masse-%, Kalkgehalt VCA ≤ 15 Masse-%, kf ≤ 1·10⁻⁹ m/s, Verdichtungsgrad DPr ≥ 97 % und Einbauwassergehalt wPr ≤ w ≤ w0,97Pr – oder bei w ≤ wPr ein Luftporenanteil na ≤ 5 %. Einzugeben: die fünf Kennwerte aus Eignungs-/Kontrollprüfung sowie w, wPr, w0,97Pr und ggf. na. Die Anforderungen gelten im eingebauten Zustand und sind in der Leistungsbeschreibung festzulegen (§5.1.1.1).
[EN] Applies to mineral sealings without additives. Passes when all Tab. 3 values are met: fraction < 0.002 mm ≥ 15 % by mass, organic matter VGL ≤ 5 % by mass, lime content VCA ≤ 15 % by mass, kf ≤ 1·10⁻⁹ m/s, degree of compaction DPr ≥ 97 % and placement water content wPr ≤ w ≤ w0.97Pr – or, when w ≤ wPr, an air-void content na ≤ 5 %. Enter the five parameters from the suitability/control tests plus w, wPr, w0.97Pr and na where needed. The requirements apply in the installed state and must be fixed in the specification (§5.1.1.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-10' AND x.code = 'REQ-12';
UPDATE fields x SET description = 'Art des Zusatzstoffs, mit dem der anstehende Boden vergütet wird: natürlicher Herkunft (pulverförmiges Calcium- oder Natrium-Bentonit mit i. d. R. > 60 Masse-% Montmorillonit, kaolinitische Tonmehle) oder synthetischer Herkunft (ein- bzw. zweikomponentige Polymersysteme, die in bindige Böden eingemischt werden und deren Festigkeit erhöhen). Produktbezeichnung laut Hersteller eintragen (§5.2).
[EN] Type of additive used to improve the in-situ soil: natural origin (powdered calcium or sodium bentonite with as a rule > 60 % by mass montmorillonite, kaolinitic clay flours) or synthetic origin (one- or two-component polymer systems mixed into cohesive soils, raising their strength). Enter the product name per the manufacturer (§5.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-11' AND x.symbol = 'mz_zusatzstofftyp';
UPDATE fields x SET description = 'Dosierung des Zusatzstoffs (Mischungsverhältnis) in %, mit der Bezugsbasis des Eignungsprüfberichts. Sie ist vorab in der Eignungsprüfung festzulegen, damit die gleichwertigen Anforderungen der Tab. 3 erreicht werden; eine quantitative Angabe kann nur über eine Bodenanalyse erfolgen (§5.2.1.1, §5.2.2, §5.2.3.1). Wert aus dem Eignungsprüfbericht übernehmen.
[EN] Dosage of the additive (mixing ratio) in %, on the reference basis stated in the suitability-test report. It must be fixed beforehand in the suitability test so that the equivalent Tab. 3 requirements are reached; a quantitative figure can only come from a soil analysis (§5.2.1.1, §5.2.2, §5.2.3.1). Take it from the suitability-test report.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-11' AND x.symbol = 'mz_zusatzstoff_anteil';
UPDATE fields x SET description = 'Geplante bzw. eingebaute Dicke der vergüteten Abdichtungsschicht in cm. Tab. 5 verlangt ≥ 30 cm in 2 Lagen von 15 bis 20 cm, nach Eignungsprüfung; 10 % Abweichung zulässig (Fußnote 1). Die Nenndicken der Tab. 5 sind einzuhalten (§5.2.2.1); Vergleichswert ist „Mindestdicke nach Tab. 5“. Dazu gehört eine Auflast/Schutzschicht ≥ 30 cm (Tab. 5).
[EN] Designed or installed thickness of the improved sealing layer in cm. Tab. 5 requires ≥ 30 cm in 2 layers of 15 to 20 cm, after the suitability test; a 10 % deviation is permitted (footnote 1). The Tab. 5 nominal thicknesses must be kept (§5.2.2.1); the comparison value is ''minimum thickness per Tab. 5''. A surcharge/protection layer ≥ 30 cm belongs to it (Tab. 5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-11' AND x.symbol = 'mz_dicke';
UPDATE fields x SET description = 'Durchlässigkeitsbeiwert kf der vergüteten Schicht in m/s (DIN EN ISO 17892-11) aus Eignungs- oder Kontrollprüfung; Dezimalwert wie 5e-10 eingeben. Die vergütete Schicht muss die gleichwertigen Anforderungen der Tab. 3 erfüllen, also ≤ 1·10⁻⁹ m/s (§5.2.1.1); Tor REQ-13 prüft den Wert. Tab. 2 ordnet Mineralböden mit Bentonit/Tonmehl/Kunststoff je nach Dosierung 1·10⁻⁸ bis 1·10⁻¹⁰ m/s zu.
[EN] Permeability coefficient kf of the improved layer in m/s (DIN EN ISO 17892-11) from the suitability or control test; enter a decimal such as 5e-10. The improved layer must meet the equivalent Tab. 3 requirements, i.e. ≤ 1·10⁻⁹ m/s (§5.2.1.1); gate REQ-13 checks it. Tab. 2 places mineral soils with bentonite/clay flour/polymer at 1·10⁻⁸ to 1·10⁻¹⁰ m/s depending on dosage.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-11' AND x.symbol = 'mz_durchlaessigkeit_kf';
UPDATE fields x SET description = 'Mischverfahren und Verdichtung der Abdichtungsschicht: Baumischverfahren (mixed-in-place, Einarbeitung des Bentonitpulvers/Tonmehls auf der Baustelle) oder Zentralmischverfahren (mixed-in-plant, Zwangsmischung in stationärer/mobiler Anlage), mit dem eingesetzten Verdichtungsgerät. Einbau und Verdichtung erfolgen lagenweise beim Einbauwassergehalt der Eignungsprüfung; der Verdichtungsgrad muss DPr ≥ 97 % an allen Stellen erreichen (§5.2.2, §5.2.2.1).
[EN] Mixing method and compaction of the sealing layer: mixed-in-place (bentonite powder/clay flour worked in on site) or mixed-in-plant (forced mixing in a stationary/mobile plant), with the compaction equipment used. Placement and compaction are done in layers at the suitability-test water content; the degree of compaction must reach DPr ≥ 97 % everywhere (§5.2.2, §5.2.2.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-11' AND x.symbol = 'mz_einbau_verdichtung';
UPDATE fields x SET description = 'Bestätigung, dass die Eignungsprüfung vor dem Einbau die Dichtwirkung nachgewiesen hat: Eignung des Mineralbodens und der zugemischten Zusatzstoffe (Bentonit/Tonmehl) im Hinblick auf Tab. 5 im eingebauten Zustand, Kennwerte nach Tab. 3 (auch bei synthetischen Zusatzstoffen) und festgelegte Dosierung (§5.2.3.1). Tor REQ-13 verlangt den Haken zusammen mit kf ≤ 1·10⁻⁹ m/s.
[EN] Confirm that the suitability test before installation proved the sealing effect: suitability of the mineral soil and the admixed additives (bentonite/clay flour) with respect to Tab. 5 in the installed state, Tab. 3 parameters (also for synthetic additives) and the fixed dosage (§5.2.3.1). Gate REQ-13 needs this tick together with kf ≤ 1·10⁻⁹ m/s.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-11' AND x.symbol = 'mz_dichtungswirkung_nachgewiesen';
UPDATE fields x SET description = 'Wird berechnet (Gleichung FLL-GAR-11-D1) aus der einzigen Zeile der Tab. 5: ≥ 30 cm Abdichtungsschicht, in 2 Lagen von 15 bis 20 cm, nach Eignungsprüfung. Vergleichswert für die eingegebene Schichtdicke; 10 % Abweichung zulässig (Fußnote 1). Nicht zu bearbeiten.
[EN] Computed (equation FLL-GAR-11-D1) from the single row of Tab. 5: ≥ 30 cm sealing layer, in 2 layers of 15 to 20 cm, after the suitability test. Comparison value for the entered layer thickness; a 10 % deviation is permitted (footnote 1). Not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-11' AND x.symbol = 'mz_dicke_min_tab5';
UPDATE equations x SET description = 'Liest die Mindestdicke der Abdichtungsschicht aus Tab. 5 (natürlich vorkommende Mineralböden mit Bentonit/Tonmehl bzw. Kunststoffen): 30 cm. Keine Eingaben nötig; das Ergebnis mz_dicke_min_tab5 in cm ist der Vergleichswert für die Schichtdicke. Die Nenndicken der Tab. 5 sind einzuhalten (§5.2.2.1), Abweichungen von 10 % zulässig.
[EN] Looks up the minimum sealing-layer thickness in Tab. 5 (naturally occurring mineral soils with bentonite/clay flour or polymers): 30 cm. No inputs needed; the result mz_dicke_min_tab5 in cm is the comparison value for the layer thickness. The Tab. 5 nominal thicknesses must be kept (§5.2.2.1), deviations of 10 % permitted.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-11' AND x.equation_number = 'FLL-GAR-11-D1';
UPDATE compliance_requirements x SET description = 'Gilt nur bei mineralischen Abdichtungen mit Zusatzstoffen (Blatt FLL-GAR-11). Besteht, wenn der dort eingegebene Durchlässigkeitsbeiwert kf ≤ 1·10⁻⁹ m/s ist und „Dichtungswirkung nachgewiesen“ bestätigt ist. Güte und Menge der Zusatzstoffe müssen die gleichwertigen Anforderungen der Tab. 3 erfüllen; die Dosierung wird vorab in der Eignungsprüfung festgelegt (§5.2.1.1, §5.2.3.1). Die Nenndicken der Tab. 5 sind zusätzlich einzuhalten.
[EN] Applies only to mineral sealings with additives (sheet FLL-GAR-11). Passes when the permeability kf entered there is ≤ 1·10⁻⁹ m/s and ''sealing performance verified'' is ticked. Quality and quantity of the additives must meet the equivalent requirements of Tab. 3; the dosage is fixed beforehand in the suitability test (§5.2.1.1, §5.2.3.1). The nominal thicknesses of Tab. 5 must be kept in addition.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-11' AND x.code = 'REQ-13';
UPDATE fields x SET description = 'Anwendungsfall nach Tab. 7, der Festigkeits-, Expositions- und Feuchtigkeitsklasse sowie die Bewehrungsüberdeckung festlegt: Wasserbecken und Teiche, Bachläufe (offene Gerinne) und Schwimmbecken/Schwimmteiche mit Badewasserqualität → C25/30 (C35/45 bei häufig schwankendem Wasserstand, Fußnote 1), XC4, XF1 (XF3 bei häufig schwankendem Wasserstand), WF, c nom 40 mm; Schwimmbecken mit Sole-/Meerwasserqualität → C35/45, XC4, XF2, XD2, XS2 (3) je nach Salzgehalt, WA, 55 mm; Pflanzenkläranlagen/Bodenretentionsfilter → C35/45, XC4, XF3, XA1, WA, 40 mm.
[EN] Application case per Tab. 7, which fixes strength, exposure and moisture class and the reinforcement cover: water basins and ponds, streams (open channels) and swimming pools/ponds with bathing-water quality → C25/30 (C35/45 with frequently fluctuating water level, footnote 1), XC4, XF1 (XF3 with frequently fluctuating water level), WF, c nom 40 mm; pools with brine/sea-water quality → C35/45, XC4, XF2, XD2, XS2 (3) depending on salt content, WA, 55 mm; constructed wetlands/soil-retention filters → C35/45, XC4, XF3, XA1, WA, 40 mm.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-12' AND x.symbol = 'anwendungsfall_concrete';
UPDATE fields x SET description = 'Bauteil nach Tab. 8: Wände oder Bodenplatte. Zusammen mit der Ausführungsart bestimmt es die Mindest-Bauteildicke: Wände ≥ 240 mm (Ortbeton, Elementwände, Spritzbeton) bzw. ≥ 200 mm (Fertigteile); Bodenplatte ≥ 250 mm (Ortbeton, Spritzbeton) bzw. ≥ 200 mm (Fertigteile); für Bodenplatten aus Elementwänden druckt Tab. 8 keinen Wert.
[EN] Component per Tab. 8: walls or floor slab. Together with the execution type it sets the minimum component thickness: walls ≥ 240 mm (cast-in-place, element walls, sprayed concrete) or ≥ 200 mm (precast); floor slab ≥ 250 mm (cast-in-place, sprayed concrete) or ≥ 200 mm (precast); for floor slabs made of element walls Tab. 8 prints no value.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-12' AND x.symbol = 'bauteil_type';
UPDATE fields x SET description = 'Dicke des Betonbauteils d in cm aus der Ausführungsplanung. Sie wählt die Tab.-6-Zeile: bei d ≤ 40 cm gelten w/z ≤ 0,60, Zementgehalt ≥ 280 kg/m³ und fck ≥ C25/30, bei d > 40 cm nur w/z ≤ 0,70 (Gleichung FLL-GAR-12-D1, Tor REQ-14). Zusätzlich muss sie die Mindestdicke der Tab. 8 erreichen – dort in mm gedruckt (z. B. Wände aus Ortbeton ≥ 240 mm = 24 cm).
[EN] Thickness of the concrete component d in cm from the execution design. It selects the Tab. 6 row: for d ≤ 40 cm w/c ≤ 0.60, cement content ≥ 280 kg/m³ and fck ≥ C25/30 apply, for d > 40 cm only w/c ≤ 0.70 (equation FLL-GAR-12-D1, gate REQ-14). It must also reach the Tab. 8 minimum – printed there in mm (e.g. cast-in-place walls ≥ 240 mm = 24 cm).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-12' AND x.symbol = 'bauteildicke_cm';
UPDATE fields x SET description = 'Herstellungsart des wasserundurchlässigen Bauteils nach §5.3 und Tab. 8: Ortbeton, Elementwände (Fertigplatten i. d. R. 6–7 cm dick, Verfüllung mit Ortbeton im Zwischenraum von mind. 10 bzw. 12 cm, Fußnote 1), Fertigteile (z. B. Muldensteine, beckenförmige Bauteile) oder Spritzbeton/faserverstärkter Spritzbeton nach DIN EN 14487 (Bemessung in Anlehnung an die DAfStb-Richtlinie, Fußnote 2). Bestimmt die Mindestdicke nach Tab. 8.
[EN] Execution type of the watertight component per §5.3 and Tab. 8: cast-in-place concrete, element walls (precast shells as a rule 6–7 cm thick, cast-in-place fill in the gap of at least 10 or 12 cm, footnote 1), precast elements (e.g. trough blocks, basin-shaped parts) or sprayed/fibre-reinforced sprayed concrete per DIN EN 14487 (design based on the DAfStb guideline, footnote 2). Sets the Tab. 8 minimum thickness.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-12' AND x.symbol = 'beton_ausfuehrungsart';
UPDATE fields x SET description = 'Festigkeitsklasse des Betons (charakteristische Druckfestigkeit fck, i. d. R. bezogen auf die Prüfung im Betonalter von 28 Tagen) aus dem Betonentwurf, z. B. „C25/30“. Tab. 6 verlangt bei Bauteildicke ≤ 40 cm ≥ C25/30; Tab. 7 verlangt je Anwendungsfall C25/30 bzw. C35/45 (Sole/Meerwasser, Pflanzenkläranlagen, häufig schwankender Wasserstand). Die in den Expositionsklassen geforderte Mindestdruckfestigkeitsklasse ist auch der Planung und statischen Berechnung zugrunde zu legen (§5.3.1). Vergleichswert: „Festigkeitsklasse – Soll nach Tab. 7“.
[EN] Strength class of the concrete (characteristic compressive strength fck, as a rule from testing at 28 days) from the concrete design, e.g. ''C25/30''. Tab. 6 requires ≥ C25/30 for component thickness ≤ 40 cm; Tab. 7 requires C25/30 or C35/45 per application case (brine/sea water, constructed wetlands, frequently fluctuating water level). The minimum strength class required by the exposure classes must also underlie the design and structural analysis (§5.3.1). Comparison value: ''strength class – target per Tab. 7''.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-12' AND x.symbol = 'druckfestigkeit_fck';
UPDATE fields x SET description = 'Bestätigung, dass der Wassereindringwiderstand des Betons an Probekörpern nach DIN EN 12390-8 geprüft wurde. Nur diese Prüfung weist den Wassereindringwiderstand nach; sie ist gesondert zu vereinbaren, ebenso Prüfverfahren und Konformitätskriterien (§5.3.3, Tab. 6 Fußnote 1). Prüfbericht des Betonherstellers/Prüflabors ablegen.
[EN] Confirm that the water-penetration resistance of the concrete was tested on specimens per DIN EN 12390-8. Only this test proves the penetration resistance; it must be agreed separately, as must the test method and conformity criteria (§5.3.3, Tab. 6 footnote 1). File the test report of the concrete producer/laboratory.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-12' AND x.symbol = 'wassereindringtiefe_geprueft';
UPDATE fields x SET description = 'Wasserzementwert w/z des Betons aus dem Betonentwurf (Sortenverzeichnis/Lieferschein); Zusatzstoffe können angerechnet werden (Tab. 6 Fußnote 3). Tab. 6 verlangt ≤ 0,60 bei Bauteildicke ≤ 40 cm und ≤ 0,70 bei > 40 cm; der zutreffende Höchstwert wird als wz_max berechnet, Tor REQ-14 prüft ihn.
[EN] Water-cement ratio w/c of the concrete from the mix design (mix record/delivery note); additions may be counted (Tab. 6 footnote 3). Tab. 6 requires ≤ 0.60 for component thickness ≤ 40 cm and ≤ 0.70 above 40 cm; the applicable maximum is computed as wz_max and gate REQ-14 checks it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-12' AND x.symbol = 'wasserzementwert';
UPDATE fields x SET description = 'Zementgehalt Z des Betons in kg/m³ aus dem Betonentwurf; Zusatzstoffe können angerechnet werden (Tab. 6 Fußnote 3). Tab. 6 verlangt ≥ 280 kg/m³ bei Bauteildicke ≤ 40 cm (Tor REQ-14); bei > 40 cm druckt Tab. 6 keinen Mindestwert. Hinweis: Bei Zementgehalt < 240 kg/m³ steigt die Mindest-Frischbetontemperatur nach Tab. 9 auf + 10 °C.
[EN] Cement content Z of the concrete in kg/m³ from the mix design; additions may be counted (Tab. 6 footnote 3). Tab. 6 requires ≥ 280 kg/m³ for component thickness ≤ 40 cm (gate REQ-14); for > 40 cm Tab. 6 prints no minimum. Note: with cement content < 240 kg/m³ the minimum fresh-concrete temperature per Tab. 9 rises to + 10 °C.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-12' AND x.symbol = 'zementgehalt_kg_m3';
UPDATE fields x SET description = 'Wird aus Tab. 7 zum gewählten Anwendungsfall übernommen: C25/30 für Wasserbecken/Teiche, Bachläufe und Badewasser-Schwimmbecken (C35/45 bei häufig schwankendem Wasserstand, z. B. Wasserwechselzone – Fußnote 1), C35/45 für Sole-/Meerwasserbecken und Pflanzenkläranlagen. Vergleichswert für die eingegebene Festigkeitsklasse; der Planung und statischen Berechnung zugrunde zu legen (§5.3.1). Nicht zu bearbeiten.
[EN] Filled from Tab. 7 for the chosen application case: C25/30 for water basins/ponds, streams and bathing-water pools (C35/45 with frequently fluctuating water level, e.g. fluctuation zone – footnote 1), C35/45 for brine/sea-water pools and constructed wetlands. Comparison value for the entered strength class; to underlie design and structural analysis (§5.3.1). Not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-12' AND x.symbol = 'festigkeitsklasse_soll';
UPDATE fields x SET description = 'Wird aus Tab. 7 übernommen, wie gedruckt: XC4, XF1 (3) für Wasserbecken/Teiche, Bachläufe und Badewasser-Schwimmbecken (XF3 bei häufig schwankendem Wasserstand, Fußnote 1); XC4, XF2, XD2, XS2 (3) je nach Salzgehalt für Sole-/Meerwasserbecken; XC4, XF3, XA1 für Pflanzenkläranlagen. XC = Karbonatisierung, XF = Frostangriff, XD/XS = Chloride, XA = chemischer Angriff (§5.3.1.1). Vorgabe für die Betonbestellung; nicht zu bearbeiten.
[EN] Filled from Tab. 7 as printed: XC4, XF1 (3) for water basins/ponds, streams and bathing-water pools (XF3 with frequently fluctuating water level, footnote 1); XC4, XF2, XD2, XS2 (3) depending on salt content for brine/sea-water pools; XC4, XF3, XA1 for constructed wetlands. XC = carbonation, XF = frost attack, XD/XS = chlorides, XA = chemical attack (§5.3.1.1). Target for ordering the concrete; not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-12' AND x.symbol = 'expositionsklassen_soll';
UPDATE fields x SET description = 'Wird aus Tab. 7 übernommen: Feuchtigkeitsklasse WF für Wasserbecken/Teiche, Bachläufe und Badewasser-Schwimmbecken, WA für Sole-/Meerwasserbecken und Pflanzenkläranlagen. Eine Einstufung in WF oder WA hat nach §5.3.1.1 stets zu erfolgen. Vorgabe für die Betonbestellung; nicht zu bearbeiten.
[EN] Filled from Tab. 7: moisture class WF for water basins/ponds, streams and bathing-water pools, WA for brine/sea-water pools and constructed wetlands. A classification as WF or WA must always be made per §5.3.1.1. Target for ordering the concrete; not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-12' AND x.symbol = 'feuchtigkeitsklasse_soll';
UPDATE fields x SET description = 'Wird aus Tab. 7 übernommen: Bewehrungsüberdeckung c nom 40 mm für Wasserbecken/Teiche, Bachläufe, Badewasser-Schwimmbecken und Pflanzenkläranlagen, 55 mm für Sole-/Meerwasserbecken. c nom setzt sich aus Mindestüberdeckung und Vorhaltemaß zusammen (Fußnote 2). Vorgabe für die Bewehrungsplanung; nicht zu bearbeiten.
[EN] Filled from Tab. 7: reinforcement cover c nom 40 mm for water basins/ponds, streams, bathing-water pools and constructed wetlands, 55 mm for brine/sea-water pools. c nom is the minimum cover plus the allowance (footnote 2). Target for the reinforcement design; not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-12' AND x.symbol = 'c_nom_min';
UPDATE fields x SET description = 'Wird aus Tab. 8 zu Bauteil × Ausführungsart übernommen, in mm: Wände ≥ 240 (Ortbeton), ≥ 240 (Elementwände, Fußnote 1), ≥ 200 (Fertigteile), ≥ 240 (Spritzbeton, Fußnote 2); Bodenplatte ≥ 250 (Ortbeton), kein Wert (Elementwände), ≥ 200 (Fertigteile), ≥ 250 (Spritzbeton). Grundlage ist Beanspruchungsklasse 1 (Druckwasser) der DAfStb-WU-Richtlinie (§5.3.1.2). Vergleich mit der Bauteildicke (cm) nur nach Umrechnung. Nicht zu bearbeiten.
[EN] Filled from Tab. 8 for component × execution type, in mm: walls ≥ 240 (cast-in-place), ≥ 240 (element walls, footnote 1), ≥ 200 (precast), ≥ 240 (sprayed concrete, footnote 2); floor slab ≥ 250 (cast-in-place), no value (element walls), ≥ 200 (precast), ≥ 250 (sprayed concrete). Basis is stress class 1 (pressing water) of the DAfStb WU guideline (§5.3.1.2). Compare with the component thickness (cm) only after conversion. Not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-12' AND x.symbol = 'bauteildicke_min';
UPDATE fields x SET description = 'Wird berechnet (Gleichung FLL-GAR-12-D1) aus der Bauteildicke nach Tab. 6: 0,60 bei d ≤ 40 cm, 0,70 bei d > 40 cm. Höchstwert für den eingegebenen Wasserzementwert; Tor REQ-14 prüft gegen dieselben Grenzen. Nicht zu bearbeiten.
[EN] Computed (equation FLL-GAR-12-D1) from the component thickness per Tab. 6: 0.60 for d ≤ 40 cm, 0.70 for d > 40 cm. Upper limit for the entered water-cement ratio; gate REQ-14 checks against the same limits. Not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-12' AND x.symbol = 'wz_max';
UPDATE fields x SET description = 'Lufttemperatur beim Betonieren als Fall der Tab. 9: „+ 5 °C bis 3 °C – allgemein“ (Mindesttemperatur des Frischbetons + 5 °C), „+ 5 °C bis 3 °C – Zementgehalt < 240 kg/m³ oder Zemente mit niedriger Hydratationswärme“ (+ 10 °C) oder „unter + 3 °C“ (+ 10 °C, wenigstens 3 Tage zu halten). Aus dem Betonierprotokoll; bestimmt die Mindest-Frischbetontemperatur für Tor REQ-43. Auf gefrorenem Baugrund, an gefrorenen Bauteilen und vereister Schalung darf nicht betoniert werden (§5.3.2.1).
[EN] Air temperature during concreting as a Tab. 9 case: ''+ 5 °C to 3 °C – general'' (minimum fresh-concrete temperature + 5 °C), ''+ 5 °C to 3 °C – cement content < 240 kg/m³ or low-heat cements'' (+ 10 °C) or ''below + 3 °C'' (+ 10 °C, to be held for at least 3 days). From the concreting record; sets the minimum fresh-concrete temperature for gate REQ-43. No concreting on frozen ground, frozen components or iced formwork (§5.3.2.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-12' AND x.symbol = 'frischbeton_lufttemperatur_fall';
UPDATE fields x SET description = 'Wird aus Tab. 9 zum gewählten Lufttemperatur-Fall übernommen: + 5 °C allgemein, + 10 °C bei Zementgehalt < 240 kg/m³ oder Zementen mit niedriger Hydratationswärme, + 10 °C bei Lufttemperatur unter + 3 °C. Untere Grenze für die Frischbetontemperatur (Tor REQ-43); die obere Grenze + 30 °C steht in §5.3.2.1 (DIN 1045-3). Nicht zu bearbeiten.
[EN] Filled from Tab. 9 for the chosen air-temperature case: + 5 °C in general, + 10 °C with cement content < 240 kg/m³ or low-heat cements, + 10 °C at air temperature below + 3 °C. Lower limit for the fresh-concrete temperature (gate REQ-43); the upper limit + 30 °C is stated in §5.3.2.1 (DIN 1045-3). Not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-12' AND x.symbol = 'frischbeton_temp_min_c';
UPDATE fields x SET description = 'Gemessene Temperatur des Frischbetons bei Anlieferung/Einbau in °C (Betonierprotokoll, Lieferschein). Nach DIN 1045-3 müssen mindestens + 5 °C bzw. die Tab.-9-Mindesttemperatur und höchstens + 30 °C eingehalten werden, um bleibende Beeinträchtigungen der Frischbetoneigenschaften zu vermeiden; Tor REQ-43 prüft beide Grenzen. Bei extrem niedrigen oder hohen Lufttemperaturen ist die Betontemperatur zu überwachen (§5.3.2.1).
[EN] Measured temperature of the fresh concrete at delivery/placing in °C (concreting record, delivery note). Per DIN 1045-3 at least + 5 °C or the Tab. 9 minimum and at most + 30 °C must be kept to avoid lasting impairment of the fresh-concrete properties; gate REQ-43 checks both limits. At extremely low or high air temperatures the concrete temperature must be monitored (§5.3.2.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-12' AND x.symbol = 'frischbeton_temperatur_c';
UPDATE fields x SET description = 'Zementfestigkeitsklasse des verwendeten Zements nach Tab. 10 (Lieferschein/Betonsortenverzeichnis): „52,5 R; 52,5 N; 42,5 R“, „42,5 N; 32,5 R“ oder „32,5 N“. Bestimmt zusammen mit der Betontemperatur die Erhärtungszeit bis zur Gefrierbeständigkeit (Festigkeit mindestens 5 N/mm² und Schutz vor Fremdwasser), die Tab. 10 für w/z = 0,60 angibt (§5.3.2.1).
[EN] Cement strength class of the cement used per Tab. 10 (delivery note/mix record): ''52.5 R; 52.5 N; 42.5 R'', ''42.5 N; 32.5 R'' or ''32.5 N''. Together with the concrete temperature it sets the curing time until frost resistance (strength at least 5 N/mm² and protection from external water), which Tab. 10 gives for w/c = 0.60 (§5.3.2.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-12' AND x.symbol = 'zementfestigkeitsklasse_tab10';
UPDATE fields x SET description = 'Wird aus Tab. 10 zur gewählten Zementfestigkeitsklasse übernommen – Erhärtungszeit in Tagen bis zur Gefrierbeständigkeit bei 5 °C Betontemperatur und w/z = 0,60: 0,75 (52,5 R; 52,5 N; 42,5 R), 2 (42,5 N; 32,5 R), 5 (32,5 N). Information für Nachbehandlung und Frostschutz; bei anderem w/z gilt die Tabelle nicht unmittelbar. Nicht zu bearbeiten.
[EN] Filled from Tab. 10 for the chosen cement strength class – curing time in days until frost resistance at 5 °C concrete temperature and w/c = 0.60: 0.75 (52.5 R; 52.5 N; 42.5 R), 2 (42.5 N; 32.5 R), 5 (32.5 N). Information for curing and frost protection; for another w/c the table does not apply directly. Not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-12' AND x.symbol = 'erhaertungszeit_tage_bei_5c';
UPDATE fields x SET description = 'Wird aus Tab. 10 zur gewählten Zementfestigkeitsklasse übernommen – Erhärtungszeit in Tagen bis zur Gefrierbeständigkeit bei 12 °C Betontemperatur und w/z = 0,60: 0,5 (52,5 R; 52,5 N; 42,5 R), 1,5 (42,5 N; 32,5 R), 3,5 (32,5 N). Information für Nachbehandlung und Frostschutz; bei anderem w/z gilt die Tabelle nicht unmittelbar. Nicht zu bearbeiten.
[EN] Filled from Tab. 10 for the chosen cement strength class – curing time in days until frost resistance at 12 °C concrete temperature and w/c = 0.60: 0.5 (52.5 R; 52.5 N; 42.5 R), 1.5 (42.5 N; 32.5 R), 3.5 (32.5 N). Information for curing and frost protection; for another w/c the table does not apply directly. Not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-12' AND x.symbol = 'erhaertungszeit_tage_bei_12c';
UPDATE fields x SET description = 'Wird aus Tab. 10 zur gewählten Zementfestigkeitsklasse übernommen – Erhärtungszeit in Tagen bis zur Gefrierbeständigkeit bei 20 °C Betontemperatur und w/z = 0,60: 0,5 (52,5 R; 52,5 N; 42,5 R), 1 (42,5 N; 32,5 R), 2 (32,5 N). Information für Nachbehandlung und Frostschutz; bei anderem w/z gilt die Tabelle nicht unmittelbar. Nicht zu bearbeiten.
[EN] Filled from Tab. 10 for the chosen cement strength class – curing time in days until frost resistance at 20 °C concrete temperature and w/c = 0.60: 0.5 (52.5 R; 52.5 N; 42.5 R), 1 (42.5 N; 32.5 R), 2 (32.5 N). Information for curing and frost protection; for another w/c the table does not apply directly. Not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-12' AND x.symbol = 'erhaertungszeit_tage_bei_20c';
UPDATE equations x SET description = 'Wählt nach Tab. 6 den Höchstwert des Wasserzementwerts aus der Bauteildicke d (cm): d ≤ 40 cm → wz_max = 0,60; d > 40 cm → wz_max = 0,70. Eingabe: Bauteildicke; Ergebnis: wz_max (dimensionslos) als Vergleichswert für den eingegebenen w/z. Bei d ≤ 40 cm verlangt Tab. 6 zusätzlich Zementgehalt ≥ 280 kg/m³ und fck ≥ C25/30.
[EN] Selects per Tab. 6 the maximum water-cement ratio from the component thickness d (cm): d ≤ 40 cm → wz_max = 0.60; d > 40 cm → wz_max = 0.70. Input: component thickness; result: wz_max (dimensionless) as the comparison value for the entered w/c. For d ≤ 40 cm Tab. 6 additionally requires cement content ≥ 280 kg/m³ and fck ≥ C25/30.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-12' AND x.equation_number = 'FLL-GAR-12-D1';
UPDATE compliance_requirements x SET description = 'Gilt bei Beton. Besteht, wenn die gemessene Frischbetontemperatur mindestens die Tab.-9-Mindesttemperatur des gewählten Lufttemperatur-Falls erreicht (+ 5 °C allgemein; + 10 °C bei Zementgehalt < 240 kg/m³, niedriger Hydratationswärme oder Lufttemperatur unter + 3 °C) und höchstens + 30 °C beträgt. Einzugeben: Lufttemperatur-Fall (füllt die Mindesttemperatur) und Frischbetontemperatur. Die Grenztemperaturen nach DIN 1045-3 müssen eingehalten werden, um bleibende Beeinträchtigungen der Frischbetoneigenschaften zu vermeiden (§5.3.2.1).
[EN] Applies to concrete. Passes when the measured fresh-concrete temperature reaches at least the Tab. 9 minimum of the chosen air-temperature case (+ 5 °C in general; + 10 °C with cement content < 240 kg/m³, low heat of hydration or air temperature below + 3 °C) and is at most + 30 °C. Enter the air-temperature case (fills the minimum) and the fresh-concrete temperature. The DIN 1045-3 limit temperatures must be kept to avoid lasting impairment of the fresh-concrete properties (§5.3.2.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-12' AND x.code = 'REQ-43';
UPDATE compliance_requirements x SET description = 'Gilt nur bei Beton (Blatt FLL-GAR-12). Besteht nach Tab. 6, wenn bei Bauteildicke d ≤ 40 cm der Wasserzementwert ≤ 0,60 und der Zementgehalt ≥ 280 kg/m³ ist bzw. bei d > 40 cm der Wasserzementwert ≤ 0,70. Einzugeben: Bauteildicke, w/z und Zementgehalt aus dem Betonentwurf (Sortenverzeichnis des Betonwerks). Tab. 6 verlangt bei d ≤ 40 cm außerdem fck ≥ C25/30; für wasserdichte Bauteile ist stets Beton mit hohem Wassereindringwiderstand nach WU-Richtlinie zu verwenden (§5.3.1).
[EN] Applies only to concrete (sheet FLL-GAR-12). Passes per Tab. 6 when, for a component thickness d ≤ 40 cm, the water-cement ratio is ≤ 0.60 and the cement content ≥ 280 kg/m³, or for d > 40 cm the water-cement ratio is ≤ 0.70. Enter component thickness, w/c and cement content from the concrete design (ready-mix plant''s mix record). For d ≤ 40 cm Tab. 6 also requires fck ≥ C25/30; watertight components always need concrete with high water-penetration resistance per the WU guideline (§5.3.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-12' AND x.code = 'REQ-14';
UPDATE fields x SET description = 'Hohlraumgehalt der eingebauten, verdichteten Asphaltbetonschicht in Vol.-%, aus der Eigen-/Fremdüberwachung (nur zerstörungsfreie Prüfverfahren, §5.4.3.2) oder der Kontrollprüfung nach TL Asphalt-StB. Asphaltbeton gilt nur als wasserdicht, wenn er ≥ 40 mm dick ist und ≤ 3 Vol.-% Hohlraum aufweist (§5.4.1.1, Tab. 12 Fußnote 1); am Marshall-Probekörper der Eignungsprüfung muss der Hohlraumgehalt < 2 Vol.-% liegen (§5.4.3.1). Tor REQ-15 prüft ≤ 3 Vol.-%. Für Asphaltmastix/Gussasphalt entfällt der Nachweis.
[EN] Void content of the installed, compacted asphalt-concrete layer in % by volume, from self-/third-party monitoring (non-destructive test methods only, §5.4.3.2) or the control test per TL Asphalt-StB. Asphalt concrete counts as watertight only when ≥ 40 mm thick with ≤ 3 % voids (§5.4.1.1, Tab. 12 footnote 1); the Marshall specimen of the suitability test must show < 2 % voids (§5.4.3.1). Gate REQ-15 checks ≤ 3 %. Not needed for mastic or poured asphalt.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-13' AND x.symbol = 'hohlraumgehalt_asphaltbeton_vol_pct';
UPDATE fields x SET description = 'Eingebaute Dicke der Asphalt-Abdichtungsschicht in cm (Planung/Dickenmessung). Tab. 12 nennt einzuhaltende Nenndicken in mm: Asphaltmastix 7–15 mm (Mittelwert 10 mm), Gussasphalt 25–40 mm (40 mm bei einlagigem Einbau), wasserdichter Asphaltbeton ≥ 40 mm (§5.4.1.2). Vergleichswerte sind „Mindestdicke/Maximaldicke nach Tab. 12“ in mm – 1 cm = 10 mm.
[EN] Installed thickness of the asphalt sealing layer in cm (design/thickness measurement). Tab. 12 gives nominal thicknesses to be kept, in mm: mastic asphalt 7–15 mm (mean 10 mm), poured asphalt 25–40 mm (40 mm for single-layer placement), watertight asphalt concrete ≥ 40 mm (§5.4.1.2). Comparison values are ''minimum/maximum thickness per Tab. 12'' in mm – 1 cm = 10 mm.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-13' AND x.symbol = 'asph_dicke';
UPDATE fields x SET description = 'Bindemittel bzw. Mischgut der Abdichtung als Freitext (Produkt/Sorte laut Lieferschein). Maßgebend sind DIN EN 13813 für Gussasphalt, DIN EN 12970 für Asphaltmastix und die TL Asphalt-StB 07 für Asphaltbeton; der Hersteller muss zusätzlich die Wurzel-/Rhizomfestigkeit nach FLL nachweisen (§5.4.1). Die Mischgutart selbst wird im Feld „Mischgutart (Tab. 12)“ gewählt.
[EN] Binder or mix of the sealing as free text (product/grade per delivery note). Governing are DIN EN 13813 for poured asphalt, DIN EN 12970 for mastic asphalt and TL Asphalt-StB 07 for asphalt concrete; the manufacturer must additionally prove root/rhizome resistance per FLL (§5.4.1). The mix type itself is chosen in ''mix type (Tab. 12)''.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-13' AND x.symbol = 'asph_bindemittel';
UPDATE fields x SET description = 'Kornverteilung/Mischgutzusammensetzung laut Eignungsprüfung des Asphaltwerks. Die Zusammensetzung von Asphaltbeton richtet sich nach den TL Asphalt-StB 07 und den zu erwartenden Belastungen; Gussasphalt und Asphaltmastix sind durch ihre Zusammensetzung wasserundurchlässig und dampfdicht (§5.4.1, §5.4.1.1). Die Mischgutzusammensetzung wird in der Eigen-/Fremdüberwachung geprüft (§5.4.3.2).
[EN] Grading/mix composition per the suitability test of the asphalt plant. The composition of asphalt concrete follows TL Asphalt-StB 07 and the expected loads; poured and mastic asphalt are impermeable and vapour-tight by composition (§5.4.1, §5.4.1.1). The mix composition is checked in self-/third-party monitoring (§5.4.3.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-13' AND x.symbol = 'asph_kornverteilung';
UPDATE fields x SET description = 'Verdichtungsgrad der Asphaltbetonschicht in % (Kontrollprüfung nach TL Asphalt-StB). Asphaltbeton muss mit geeigneten Geräten (Walzen, Rüttelplatten) verdichtet werden, Arbeitsnähte durch Walzen; Asphaltmastix und Gussasphalt brauchen keine Verdichtung (§5.4.2.1). Die Richtlinie druckt keinen Zahlenwert – die Dichtheit wird über den Hohlraumgehalt ≤ 3 Vol.-% nachgewiesen (§5.4.1.1); Wert nach EAAW/Leistungsbeschreibung angeben.
[EN] Degree of compaction of the asphalt-concrete layer in % (control test per TL Asphalt-StB). Asphalt concrete must be compacted with suitable equipment (rollers, vibrating plates), working seams by rolling; mastic and poured asphalt need no compaction (§5.4.2.1). The guideline prints no figure – tightness is proven via the void content ≤ 3 % by volume (§5.4.1.1); state the value per EAAW/specification.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-13' AND x.symbol = 'asph_verdichtungsgrad';
UPDATE fields x SET description = 'Ausführung der Arbeitsnähte: Bei Asphaltbeton sind Nähte durch Walzen zu verdichten; beim Einbau heiß an kalt ist die kalte Nahtflanke durch Erwärmen für den Anschluss der heißen Bahn vorzubereiten (§5.4.2.1). Asphaltmastix und Gussasphalt werden i. d. R. von Hand eingebaut (DIN 18533). Verfahren laut Ausführungskonzept/EAAW eintragen.
[EN] Execution of working seams: for asphalt concrete seams must be compacted by rolling; when placing hot against cold, the cold seam face must be warmed to bond the hot lane (§5.4.2.1). Mastic and poured asphalt are usually placed by hand (DIN 18533). Enter the method per the execution concept/EAAW.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-13' AND x.symbol = 'asph_nahttechnik';
UPDATE fields x SET description = 'Mischgutart nach Tab. 12: Asphaltmastix (DIN EN 12970), Gussasphalt (DIN EN 13813) oder wasserdichter Asphaltbeton (TL Asphalt-StB 07). Die Wahl füllt Mindest-/Maximaldicke nach Tab. 12 und die Richtwert-Böschungsneigung nach Tab. 1 (Asphaltmastix ≤ 1:3, Gussasphalt ≤ 1:5, Asphaltbeton ≤ 1:2). Gussasphalt darf nicht auf ungebundenen Unterlagen eingebaut werden; alle drei auf Flächen ≤ 1:5 (§5.4.2).
[EN] Mix type per Tab. 12: mastic asphalt (DIN EN 12970), poured asphalt (DIN EN 13813) or watertight asphalt concrete (TL Asphalt-StB 07). The choice fills minimum/maximum thickness per Tab. 12 and the guide slope per Tab. 1 (mastic ≤ 1:3, poured asphalt ≤ 1:5, asphalt concrete ≤ 1:2). Poured asphalt must not be placed on unbound bases; all three on surfaces ≤ 1:5 (§5.4.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-13' AND x.symbol = 'mischgutart';
UPDATE fields x SET description = 'Wird aus Tab. 12 zur gewählten Mischgutart übernommen, in mm: Asphaltmastix 7, Gussasphalt 25, wasserdichter Asphaltbeton 40 (Fußnote 1: Hohlraumgehalt im eingebauten Zustand ≤ 3 Vol.-%). Die Nenndicken sind einzuhalten (§5.4.1.2); Vergleich mit der Asphaltdicke (cm) nur nach Umrechnung. Nicht zu bearbeiten.
[EN] Filled from Tab. 12 for the chosen mix type, in mm: mastic asphalt 7, poured asphalt 25, watertight asphalt concrete 40 (footnote 1: void content in the installed state ≤ 3 % by volume). The nominal thicknesses must be kept (§5.4.1.2); compare with the asphalt thickness (cm) only after conversion. Not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-13' AND x.symbol = 'asph_dicke_min';
UPDATE fields x SET description = 'Wird aus Tab. 12 übernommen, in mm: Asphaltmastix 15, Gussasphalt 40 (bei einlagigem Einbau, Fußnote 2); für Asphaltbeton druckt Tab. 12 keinen Höchstwert („–“). Mittelwert für Asphaltmastix 10 mm. Nicht zu bearbeiten.
[EN] Filled from Tab. 12, in mm: mastic asphalt 15, poured asphalt 40 (for single-layer placement, footnote 2); for asphalt concrete Tab. 12 prints no maximum (''–''). Mean value for mastic asphalt 10 mm. Not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-13' AND x.symbol = 'asph_dicke_max';
UPDATE fields x SET description = 'Wird aus Tab. 1 zur gewählten Mischgutart übernommen – Richtwert der Böschungsneigung 1:m in Regelbauweise: Asphaltmastix ≤ 1:3 (33 %), Gussasphalt ≤ 1:5 (20 %), Asphaltbeton ≤ 1:2 (50 %). Richtwerte, die u. a. von Bodenart und Kontaktreibungsfläche abhängen (§4.5); die Böschung des Vorhabens darf nicht steiler sein. Nicht zu bearbeiten.
[EN] Filled from Tab. 1 for the chosen mix type – guide value of the slope 1:m in standard construction: mastic asphalt ≤ 1:3 (33 %), poured asphalt ≤ 1:5 (20 %), asphalt concrete ≤ 1:2 (50 %). Guide values depending e.g. on soil type and contact friction surface (§4.5); the project slope must not be steeper. Not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-13' AND x.symbol = 'asph_neigung_max_1m';
UPDATE compliance_requirements x SET description = 'Gilt nur bei Asphalt (Blatt FLL-GAR-13). Besteht, wenn der Hohlraumgehalt der eingebauten Asphaltbetonschicht ≤ 3 Vol.-% ist (Tab. 12 Fußnote 1). Asphaltbeton gilt nur dann als wasserdicht, wenn er zusätzlich mit mindestens 40 mm Dicke eingebaut ist (§5.4.1.1); am Marshall-Probekörper der Eignungsprüfung muss der Hohlraumgehalt < 2 Vol.-% liegen (§5.4.3.1). Für Asphaltmastix und Gussasphalt sind die Nenndicken der Tab. 12 einzuhalten.
[EN] Applies only to asphalt (sheet FLL-GAR-13). Passes when the void content of the installed asphalt-concrete layer is ≤ 3 % by volume (Tab. 12 footnote 1). Asphalt concrete counts as watertight only if it is also placed at least 40 mm thick (§5.4.1.1); the Marshall specimen of the suitability test must show < 2 % voids (§5.4.3.1). For mastic asphalt and poured asphalt the nominal thicknesses of Tab. 12 apply.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-13' AND x.code = 'REQ-15';
UPDATE fields x SET description = 'Bentonit-Flächeneinheit Mclay der GTD in g/m², bezogen auf Wassergehalt 0 Masse-%, nach DIN EN 14196 aus Leistungserklärung/CE-Dokument des Herstellers. Tab. 13 verlangt ≥ 3.600 g/m² bei Na-Bentonit und ≥ 8.000 g/m² bei Ca-Bentonit (Tor REQ-16); Vergleichswert „Mindestwert Tab. 13“. Für vernadelte Na-Bentonitmatten nennt Tab. 15 Zeile 2 ebenfalls ≥ 3.600 g/m².
[EN] Bentonite mass per unit area Mclay of the GCL in g/m², at 0 % water content, per DIN EN 14196 from the manufacturer''s declaration of performance/CE document. Tab. 13 requires ≥ 3,600 g/m² for Na bentonite and ≥ 8,000 g/m² for Ca bentonite (gate REQ-16); comparison value ''minimum per Tab. 13''. For needle-punched Na-bentonite mats Tab. 15 row 2 also states ≥ 3,600 g/m².' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-14' AND x.symbol = 'bentonit_flaecheneinheit_g_m2';
UPDATE fields x SET description = 'Bentonitart der GTD laut Herstellerangabe: Natrium-Bentonit (hohes Wasseraufnahme- und Quellvermögen ≥ 24 ml) oder Calcium-Bentonit (Quellvermögen ca. 8–12 ml, daher Flächengewichte ≥ 8.000 g/m² erforderlich – bei Verlegung, Überlappungen und Anschlüssen zu berücksichtigen). Die Wahl bestimmt die Tab.-13-Mindestwerte für Flächeneinheit und Quellvermögen (§5.5.1.1).
[EN] Bentonite type of the GCL per the manufacturer: sodium bentonite (high water uptake and swell index ≥ 24 ml) or calcium bentonite (swell index about 8–12 ml, hence mass per unit area ≥ 8,000 g/m² required – to be considered for laying, overlaps and connections). The choice sets the Tab. 13 minima for mass per unit area and swell index (§5.5.1.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-14' AND x.symbol = 'bentonit_type';
UPDATE fields x SET description = 'Größtkorn des Bodenmaterials der Auflast unmittelbar über der GTD in mm (Lieferschein/Sieblinie). §5.5.2.1 begrenzt es auf 16 mm, bei Ungleichförmigkeitszahl U ≥ 5 auf 32 mm; der zulässige Wert wird als groesstkorn_max_mm berechnet. Die Auflast ist im Vor-Kopf-Verfahren aufzubringen, ohne Überlappungskanten zu verdrücken oder zu verschieben.
[EN] Maximum grain size of the surcharge soil directly above the GCL in mm (delivery note/grading curve). §5.5.2.1 limits it to 16 mm, or 32 mm when the uniformity coefficient U ≥ 5; the permitted value is computed as groesstkorn_max_mm. The surcharge is placed by the head-on method without crushing or displacing overlap edges.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-14' AND x.symbol = 'groesstkorn_auflast_mm';
UPDATE fields x SET description = 'Funktion der Auflast über der GTD nach Tab. 16: „Quellgegendruck beim Erstquellen“ (z. B. Bereiche unterhalb eines permanenten Wasserspiegels) → ≥ 0,30 m; „Austrocknung und Frosteinwirkung“ → ≥ 0,60 m. Bei polyolefinbeschichteter GTD deckt die 0,30-m-Zeile auch den Schutz vor Austrocknung ab, ≥ 0,60 m bleibt für Frosteinwirkung. Anhaltswerte, auch gegen Wellenschlag/Wartung dauerhaft einzuhalten; Abweichungen nach Nutzung und Standort (§5.5.1.2).
[EN] Function of the surcharge above the GCL per Tab. 16: ''counter-pressure at first swelling'' (e.g. areas below a permanent water level) → ≥ 0.30 m; ''drying out and frost'' → ≥ 0.60 m. For a polyolefin-coated GCL the 0.30 m row also covers protection against drying, ≥ 0.60 m remains for frost. Guide values, to be kept permanently also against wave action/maintenance; deviations per use and site (§5.5.1.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-14' AND x.symbol = 'gtd_auflast_funktion';
UPDATE fields x SET description = 'Angabe, ob die GTD eine zusätzliche polyolefine Beschichtung trägt (üblicherweise einseitig auf der Gewebeseite; Tab. 15 Zeile 5: ≥ 400 g/m² PE-Beschichtung). Nach oben verlegt schützt sie vor Austrocknung und Durchwurzelung des Bentonits und erlaubt eine dünnere Schutzabdeckung (Tab. 16); sie unterbindet den direkten Kontakt Bentonit–Frischbeton. Bestimmt die Tab.-16-Auflastdicke und die Tab.-15-Kennwerte (§5.5.1.1).
[EN] Whether the GCL carries an additional polyolefin coating (usually one-sided on the woven side; Tab. 15 row 5: ≥ 400 g/m² PE coating). Laid upwards it protects the bentonite against drying and root penetration and allows a thinner protective cover (Tab. 16); it prevents direct contact between bentonite and fresh concrete. Sets the Tab. 16 surcharge thickness and the Tab. 15 values (§5.5.1.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-14' AND x.symbol = 'gtd_polyolefin_beschichtung';
UPDATE fields x SET description = 'Dicke der GTD im trockenen Zustand in mm laut Herstellerdatenblatt. Sie hängt von Bentoniteinlage und Geokunststoffkomponenten ab und beträgt nach §5.5.1.2 6 bis 10 mm. Für die Dicke der gesamten Abdichtung ist jedoch die Auflast über der GTD maßgebend (Tab. 16).
[EN] Thickness of the GCL in the dry state in mm per the manufacturer''s data sheet. It depends on the bentonite fill and the geosynthetic components and is 6 to 10 mm per §5.5.1.2. For the thickness of the whole sealing, however, the surcharge above the GCL governs (Tab. 16).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-14' AND x.symbol = 'gtd_schichtdicke_mm';
UPDATE fields x SET description = 'Geplante Überlappung der GTD-Bahnen in Längsrichtung in cm (Verlegeplan). Nach §5.5.2.1 beträgt die Mindestüberlappung längs i. d. R. 30 cm; Tor REQ-16 prüft ≥ 30 cm. Überlappungen sind in Gefällerichtung dachziegelartig, faltenfrei und frei von Fremdstoffen auszuführen, keine gleichen Oberflächenseiten aufeinander; abgedichtet werkseitig mit ≥ 800 g/m² Natriumbentonit im Überlappungsbereich oder auf der Baustelle mit Bentonitpulver/-paste (§5.5.1.1).
[EN] Planned lengthwise overlap of the GCL rolls in cm (laying plan). Per §5.5.2.1 the lengthwise minimum overlap is as a rule 30 cm; gate REQ-16 checks ≥ 30 cm. Overlaps are laid shingle-fashion down the slope, free of folds and foreign matter, never like surfaces on each other; sealed with ≥ 800 g/m² sodium bentonite factory-impregnated in the overlap zone or with bentonite powder/paste on site (§5.5.1.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-14' AND x.symbol = 'gtd_ueberlappung_laengs_cm';
UPDATE fields x SET description = 'Geplante Querüberlappung am Ende jeder Rolle in cm. Nach §5.5.2.1 i. d. R. 50 cm; Tor REQ-16 prüft ≥ 50 cm. Querüberlappungen in Böschungsfallrichtung sind zu vermeiden; bei Neigungen 1:3 oder steiler dachziegelartig ausführen. Kreuzstöße sind unzulässig, T-Stöße auf ein Minimum zu reduzieren, Überlappungen in Tiefpunkten zu vermeiden.
[EN] Planned crosswise overlap at the end of each roll in cm. Per §5.5.2.1 as a rule 50 cm; gate REQ-16 checks ≥ 50 cm. Avoid cross overlaps down the slope; at slopes 1:3 or steeper lay them shingle-fashion. Cross joints are not permitted, T-joints must be kept to a minimum, overlaps at low points avoided.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-14' AND x.symbol = 'gtd_ueberlappung_quer_cm';
UPDATE fields x SET description = 'Quellvermögen des Bentonits in ml nach ASTM D 5890 aus der Leistungserklärung des Herstellers. Tab. 13 verlangt ≥ 24 ml bei Na-Bentonit und ≥ 8 ml bei Ca-Bentonit (Tor REQ-16); Vergleichswert „Mindestwert Tab. 13“. Tab. 15 Zeile 3 nennt für vernadelte Na-Bentonitmatten ebenfalls ≥ 24 ml.
[EN] Swell index of the bentonite in ml per ASTM D 5890 from the manufacturer''s declaration of performance. Tab. 13 requires ≥ 24 ml for Na bentonite and ≥ 8 ml for Ca bentonite (gate REQ-16); comparison value ''minimum per Tab. 13''. Tab. 15 row 3 also states ≥ 24 ml for needle-punched Na-bentonite mats.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-14' AND x.symbol = 'quellvermoegen_ml';
UPDATE fields x SET description = 'Wird aus Tab. 13 zum gewählten Bentonittyp übernommen: ≥ 3.600 g/m² (Na-Bentonit) bzw. ≥ 8.000 g/m² (Ca-Bentonit), bezogen auf Wassergehalt 0 Masse-% (DIN EN 14196). Mindestanforderung an das Bentonit; Vergleichswert für die eingegebene Flächeneinheit. Nicht zu bearbeiten.
[EN] Filled from Tab. 13 for the chosen bentonite type: ≥ 3,600 g/m² (Na bentonite) or ≥ 8,000 g/m² (Ca bentonite), at 0 % water content (DIN EN 14196). Minimum requirement for the bentonite; comparison value for the entered mass per unit area. Not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-14' AND x.symbol = 'bentonit_flaecheneinheit_min';
UPDATE fields x SET description = 'Wird aus Tab. 13 zum gewählten Bentonittyp übernommen: Quellvermögen ≥ 24 ml (Na-Bentonit) bzw. ≥ 8 ml (Ca-Bentonit) nach ASTM D 5890. Vergleichswert für das eingegebene Quellvermögen. Nicht zu bearbeiten.
[EN] Filled from Tab. 13 for the chosen bentonite type: swell index ≥ 24 ml (Na bentonite) or ≥ 8 ml (Ca bentonite) per ASTM D 5890. Comparison value for the entered swell index. Not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-14' AND x.symbol = 'quellvermoegen_min';
UPDATE fields x SET description = 'Wird aus Tab. 16 zu Beschichtung × Auflastfunktion übernommen, in m: ohne Beschichtung – Quellgegendruck ≥ 0,30 m, Austrocknung/Frost ≥ 0,60 m; mit polyolefiner Beschichtung – Quellgegendruck und Austrocknung ≥ 0,30 m, Frosteinwirkung ≥ 0,60 m. Anhaltswerte, dauerhaft auch gegen Wellenschlag/Wartung einzuhalten; Vergleichswert für die Auflastdicke (cm) auf Blatt FLL-GAR-10. Zusätzlich fordert §5.5.2.1 eine Bodenauflast ≥ 5 kN/m², was etwa 30 cm entspricht. Nicht zu bearbeiten.
[EN] Filled from Tab. 16 for coating × surcharge function, in m: without coating – counter-swell pressure ≥ 0.30 m, drying/frost ≥ 0.60 m; with polyolefin coating – counter-swell pressure and drying ≥ 0.30 m, frost ≥ 0.60 m. Guide values, to be kept permanently also against wave action/maintenance; comparison value for the surcharge thickness (cm) on sheet FLL-GAR-10. §5.5.2.1 additionally requires a soil surcharge ≥ 5 kN/m², about 30 cm. Not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-14' AND x.symbol = 'gtd_auflast_min_m';
UPDATE fields x SET description = 'Ungleichförmigkeitszahl U des Auflastbodens aus der Korngrößenverteilung (Lieferschein/Bodenprüfung), dimensionslos. Eingang der Gleichung FLL-GAR-14-D1: Bei U ≥ 5 darf das Größtkorn der Auflast 32 mm, sonst 16 mm nicht überschreiten (§5.5.2.1).
[EN] Uniformity coefficient U of the surcharge soil from its grading (delivery note/soil test), dimensionless. Input of equation FLL-GAR-14-D1: with U ≥ 5 the maximum grain size of the surcharge may not exceed 32 mm, otherwise 16 mm (§5.5.2.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-14' AND x.symbol = 'ungleichfoermigkeit_u';
UPDATE fields x SET description = 'Wird berechnet (Gleichung FLL-GAR-14-D1): zulässiger Größtkorndurchmesser der Bodenauflast = 32 mm bei U ≥ 5, sonst 16 mm (§5.5.2.1). Vergleichswert für das eingegebene Größtkorn der Auflast. Nicht zu bearbeiten.
[EN] Computed (equation FLL-GAR-14-D1): permitted maximum grain size of the soil surcharge = 32 mm when U ≥ 5, otherwise 16 mm (§5.5.2.1). Comparison value for the entered maximum grain size of the surcharge. Not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-14' AND x.symbol = 'groesstkorn_max_mm';
UPDATE fields x SET description = 'Art des Träger-/Deckgeotextils der GTD nach Tab. 14: Bändchengewebe oder mechanisch verfestigter PP-Vliesstoff. Das Bentonit wird auf das Trägergeotextil aufgerieselt und vom Deckgeotextil überdeckt; beide Lagen sind durch Vernadelung/Vernähung kraftschlüssig verbunden (§5.5.1.1). Die Wahl bestimmt die Mindest-Flächeneinheit nach Tab. 14 (≥ 100 g/m² Bändchengewebe, ≥ 200 g/m² PP-Vliesstoff).
[EN] Type of the carrier/cover geotextile of the GCL per Tab. 14: woven slit-film fabric (Bändchengewebe) or mechanically bonded PP nonwoven. The bentonite is spread onto the carrier geotextile and covered by the cover geotextile; both layers are bonded through needle-punching/stitching (§5.5.1.1). The choice sets the minimum mass per unit area per Tab. 14 (≥ 100 g/m² woven, ≥ 200 g/m² PP nonwoven).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-14' AND x.symbol = 'gtd_geotextil_art_tab14';
UPDATE fields x SET description = 'Wird aus Tab. 14 zur gewählten Geotextilart übernommen: ≥ 100 g/m² bei Bändchengewebe, ≥ 200 g/m² bei mechanisch verfestigtem PP-Vliesstoff (DIN EN ISO 9864). Mindestwert für die eingegebene Flächeneinheit MA; Tor REQ-42 prüft dagegen. Nicht zu bearbeiten.
[EN] Filled from Tab. 14 for the chosen geotextile type: ≥ 100 g/m² for woven slit-film fabric, ≥ 200 g/m² for mechanically bonded PP nonwoven (DIN EN ISO 9864). Minimum for the entered mass per unit area MA; gate REQ-42 checks against it. Not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-14' AND x.symbol = 'gtd_geotextil_flaecheneinheit_min';
UPDATE fields x SET description = 'Flächeneinheit MA des Träger-/Deckgeotextils in g/m² nach DIN EN ISO 9864 aus der Leistungserklärung des Herstellers. Tab. 14 verlangt ≥ 100 g/m² bei Bändchengewebe und ≥ 200 g/m² bei PP-Vliesstoff; Tor REQ-42 prüft gegen den Mindestwert. Tab. 15 nennt für vernadelte Na-Bentonitmatten Deckvliesstoff ≥ 200 g/m² und Trägergewebe ≥ 100 g/m².
[EN] Mass per unit area MA of the carrier/cover geotextile in g/m² per DIN EN ISO 9864 from the manufacturer''s declaration of performance. Tab. 14 requires ≥ 100 g/m² for woven slit-film fabric and ≥ 200 g/m² for PP nonwoven; gate REQ-42 checks against the minimum. Tab. 15 states cover nonwoven ≥ 200 g/m² and carrier woven ≥ 100 g/m² for needle-punched Na-bentonite mats.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-14' AND x.symbol = 'gtd_geotextil_flaecheneinheit_g_m2';
UPDATE fields x SET description = 'Zugfestigkeit der GTD längs und quer in kN/m nach DIN EN ISO 10319 (Leistungserklärung/CE-Dokument). Tab. 15 Zeile 8 verlangt ≥ 10 kN/m mit und ohne Beschichtung – eine festgelegte Mindestanforderung, die für alle Verbindungsverfahren, Bentonitarten und Oberflächenausbildungen gilt (§5.5.1.1). Tor REQ-42 prüft ≥ 10 kN/m; den kleineren der beiden Richtungswerte eintragen.
[EN] Tensile strength of the GCL in machine and cross direction in kN/m per DIN EN ISO 10319 (declaration of performance/CE document). Tab. 15 row 8 requires ≥ 10 kN/m with and without coating – a fixed minimum that applies to all bonding methods, bentonite types and surface finishes (§5.5.1.1). Gate REQ-42 checks ≥ 10 kN/m; enter the smaller of the two directional values.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-14' AND x.symbol = 'gtd_zugfestigkeit_kn_m';
UPDATE fields x SET description = 'Dehnung bei Zugfestigkeit der GTD in % nach DIN EN ISO 10319 (Leistungserklärung). Tab. 15 Zeile 8 verlangt ≤ 30 % – festgelegte Mindestanforderung für alle GTD-Arten (§5.5.1.1); Tor REQ-42 prüft den Wert. Den größeren der beiden Richtungswerte eintragen.
[EN] Elongation at tensile strength of the GCL in % per DIN EN ISO 10319 (declaration of performance). Tab. 15 row 8 requires ≤ 30 % – a fixed minimum requirement for all GCL types (§5.5.1.1); gate REQ-42 checks it. Enter the larger of the two directional values.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-14' AND x.symbol = 'gtd_zugfestigkeitsdehnung_pct';
UPDATE fields x SET description = 'Verbundfestigkeit (Schälwiderstand) der GTD in N/m nach ASTM D 6496 aus der Leistungserklärung; sie belegt, dass das Bentonit erosionssicher zwischen den Geotextilien eingekapselt ist und das Produkt Aufschälen/Abscheren widersteht. Tab. 15 Zeile 9 verlangt ≥ 360 N/m – festgelegte Mindestanforderung (§5.5.1.1); Tor REQ-42 prüft den Wert.
[EN] Peel strength of the GCL in N/m per ASTM D 6496 from the declaration of performance; it shows that the bentonite is encapsulated erosion-proof between the geotextiles and the product resists peeling/shearing. Tab. 15 row 9 requires ≥ 360 N/m – a fixed minimum requirement (§5.5.1.1); gate REQ-42 checks it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-14' AND x.symbol = 'gtd_verbundfestigkeit_n_m';
UPDATE fields x SET description = 'Durchlässigkeitsbeiwert kf der GTD in m/s nach DIN EN 16416 (i = 150, ca. 27,5 kPa Auflast, ermittelt bei d = 1 cm) aus der Leistungserklärung; Dezimalwert wie 3e-11 eingeben. Tab. 15 Zeile 10 verlangt ≤ 5,0·10⁻¹¹ m/s – festgelegte Mindestanforderung (§5.5.1.1); Tor REQ-42 prüft den Wert. Fabrikneue Na-Bentonit-Bahnen liegen in der Qualitätssicherung bei kf = 2·10⁻¹¹ bis 7·10⁻¹¹ m/s.
[EN] Permeability coefficient kf of the GCL in m/s per DIN EN 16416 (i = 150, about 27.5 kPa surcharge, determined at d = 1 cm) from the declaration of performance; enter a decimal such as 3e-11. Tab. 15 row 10 requires ≤ 5.0·10⁻¹¹ m/s – a fixed minimum requirement (§5.5.1.1); gate REQ-42 checks it. Factory-new Na-bentonite liners show kf = 2·10⁻¹¹ to 7·10⁻¹¹ m/s in quality control.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-14' AND x.symbol = 'gtd_kf_m_s';
UPDATE fields x SET description = 'Permittivität der GTD nach DIN EN 16416 (i = 150, ca. 27,5 kPa Auflast) aus der Leistungserklärung; Tab. 15 druckt sie in m/s. Zeile 11 verlangt ≤ 5,0·10⁻⁹ m/s – festgelegte Mindestanforderung (§5.5.1.1); Tor REQ-42 prüft den Wert. Dezimalwert wie 4e-9 eingeben.
[EN] Permittivity of the GCL per DIN EN 16416 (i = 150, about 27.5 kPa surcharge) from the declaration of performance; Tab. 15 prints it in m/s. Row 11 requires ≤ 5.0·10⁻⁹ m/s – a fixed minimum requirement (§5.5.1.1); gate REQ-42 checks it. Enter a decimal such as 4e-9.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-14' AND x.symbol = 'gtd_permittivitaet_m_s';
UPDATE equations x SET description = 'Leitet aus der Ungleichförmigkeitszahl U des Auflastbodens das zulässige Größtkorn ab: U ≥ 5 → 32 mm, sonst 16 mm (§5.5.2.1: „Der Größtkorndurchmesser darf 16 mm bzw. 32 mm bei U ≥ 5 nicht überschreiten.“). Eingabe: U (dimensionslos); Ergebnis groesstkorn_max_mm in mm als Vergleichswert für das eingegebene Größtkorn der Auflast.
[EN] Derives the permitted maximum grain size from the uniformity coefficient U of the surcharge soil: U ≥ 5 → 32 mm, otherwise 16 mm (§5.5.2.1: the maximum grain diameter may not exceed 16 mm, or 32 mm with U ≥ 5). Input: U (dimensionless); result groesstkorn_max_mm in mm as the comparison value for the entered maximum grain size of the surcharge.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-14' AND x.equation_number = 'FLL-GAR-14-D1';
UPDATE compliance_requirements x SET description = 'Gilt bei GTD. Besteht, wenn die Flächeneinheit des Geotextils mindestens den Tab.-14-Wert der gewählten Geotextilart erreicht (≥ 100 g/m² Bändchengewebe, ≥ 200 g/m² PP-Vliesstoff) und die festgelegten Mindestanforderungen der Tab. 15 Zeilen 8–11 erfüllt sind: Zugfestigkeit ≥ 10 kN/m, Zugfestigkeitsdehnung ≤ 30 %, Verbundfestigkeit ≥ 360 N/m, kf ≤ 5,0·10⁻¹¹ m/s, Permittivität ≤ 5,0·10⁻⁹ m/s. Einzugeben: Geotextilart und alle fünf Kennwerte aus der Leistungserklärung. Zeilen 2–7 der Tab. 15 können produktabhängig abweichen und werden nicht geprüft (§5.5.1.1).
[EN] Applies to GCLs. Passes when the geotextile''s mass per unit area reaches at least the Tab. 14 value of the chosen geotextile type (≥ 100 g/m² woven slit-film, ≥ 200 g/m² PP nonwoven) and the fixed minimum requirements of Tab. 15 rows 8–11 are met: tensile strength ≥ 10 kN/m, elongation at tensile strength ≤ 30 %, peel strength ≥ 360 N/m, kf ≤ 5.0·10⁻¹¹ m/s, permittivity ≤ 5.0·10⁻⁹ m/s. Enter the geotextile type and all five values from the declaration of performance. Rows 2–7 of Tab. 15 may differ by product and are not checked (§5.5.1.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-14' AND x.code = 'REQ-42';
UPDATE compliance_requirements x SET description = 'Gilt nur bei GTD (Blatt FLL-GAR-14). Besteht, wenn das Bentonit die Mindestwerte der Tab. 13 erfüllt – Na-Bentonit: Flächeneinheit ≥ 3.600 g/m² und Quellvermögen ≥ 24 ml; Ca-Bentonit: ≥ 8.000 g/m² und ≥ 8 ml – und die Überlappungen längs ≥ 30 cm und quer am Rollenende ≥ 50 cm betragen (§5.5.2.1 nennt diese Werte „i. d. R.“). Einzugeben: Bentonittyp, Flächeneinheit und Quellvermögen aus Leistungserklärung/CE-Dokument des Herstellers sowie die geplanten Überlappungen.
[EN] Applies only to GCLs (sheet FLL-GAR-14). Passes when the bentonite meets the Tab. 13 minima – Na bentonite: mass per unit area ≥ 3,600 g/m² and swell index ≥ 24 ml; Ca bentonite: ≥ 8,000 g/m² and ≥ 8 ml – and the overlaps are ≥ 30 cm lengthwise and ≥ 50 cm crosswise at roll ends (§5.5.2.1 gives these ''as a rule''). Enter bentonite type, mass per unit area and swell index from the manufacturer''s declaration of performance/CE document plus the planned overlaps.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-14' AND x.code = 'REQ-16';
UPDATE fields x SET description = 'Produkt-/Typbezeichnung der Bitumen- oder Polymerbitumenbahn laut Herstellerdatenblatt als Freitext. Zulässig sind die in Tab. 19 genannten Bahnen nach DIN EN 13969 in Verbindung mit DIN SPEC 20000-202, Anwendungstyp BA, die der projektspezifischen Wassereinwirkungsklasse (W1-B bis W3-B), Rissklasse (R0-B bis R3-B) und Standortbedingung (S1-B/S2-B) entsprechen; der Hersteller muss die Wurzel-/Rhizomfestigkeit nach FLL nachweisen (§6.1.1, §6.1.1.1). Das gedruckte Kurzzeichen wird im Feld „Kurzzeichen (Tab. 19)“ gewählt.
[EN] Product/type designation of the bitumen or polymer-bitumen sheet per the manufacturer''s data sheet, as free text. Permitted are the sheets listed in Tab. 19 per DIN EN 13969 with DIN SPEC 20000-202, application type BA, matching the project''s water-action class (W1-B to W3-B), crack class (R0-B to R3-B) and site condition (S1-B/S2-B); the manufacturer must prove root/rhizome resistance per FLL (§6.1.1, §6.1.1.1). The printed designation is chosen in ''designation (Tab. 19)''.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-15' AND x.symbol = 'bb_bahnentyp';
UPDATE fields x SET description = 'Dicke der einzelnen Bitumenbahn in mm laut Herstellerdatenblatt. Die Richtlinie druckt keinen Mindestwert: Die Bahnendicke ist abhängig von der verwendeten Stoffart, die als Anwendungstyp in DIN EN 13969 in Verbindung mit DIN/TS 20.000-202 geregelt ist (§6.1.1.2). Wert der Leistungserklärung übernehmen.
[EN] Thickness of the individual bitumen sheet in mm per the manufacturer''s data sheet. The guideline prints no minimum: the sheet thickness depends on the material type, regulated as application type in DIN EN 13969 with DIN/TS 20.000-202 (§6.1.1.2). Take the value from the declaration of performance.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-15' AND x.symbol = 'bb_dicke';
UPDATE fields x SET description = 'Anzahl der Bahnenlagen der Abdichtung. Abdichtungen aus Bitumenbahnen sind i. d. R. mehrlagig herzustellen (§6.1.1.2); die Bahnen sind innerhalb einer Lage und von Lage zu Lage gegeneinander versetzt einzubauen (§6.1.2). Eine einlagige Ausführung weicht vom Regelfall ab.
[EN] Number of sheet layers of the sealing. Bitumen-sheet sealings are as a rule built up in several layers (§6.1.1.2); sheets are staggered within a layer and from layer to layer (§6.1.2). A single-layer build-up departs from the standard case.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-15' AND x.symbol = 'bb_lagen_anzahl';
UPDATE fields x SET description = 'Verlegeart der Bahnen (z. B. vollflächig verklebt/verschweißt, lose mit Auflast) nach DIN 18535 und DIN 18533. Standardneigung in Regelbauweise 1:3 (33 % Gefälle); mit Schutzschichten oder in Kombination mit Betonbauweisen sind steilere Neigungen möglich. Mindestüberlappung an Nähten 80 mm, an Stößen und Anschlüssen 100 mm; bei edelstahlkaschierten Schweißbahnen längs mind. 100 mm, an Quernähten, Stößen und Anschlüssen mind. 200 mm (§6.1.2).
[EN] Laying method of the sheets (e.g. fully bonded/welded, loose with surcharge) per DIN 18535 and DIN 18533. Standard slope in regular construction 1:3 (33 %); with protection layers or combined with concrete construction steeper slopes are possible. Minimum overlap at seams 80 mm, at butt joints and connections 100 mm; for stainless-steel-laminated torch-on sheets at least 100 mm lengthwise and 200 mm at cross seams, butt joints and connections (§6.1.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-15' AND x.symbol = 'bb_verlegeart';
UPDATE fields x SET description = 'Fügetechnik der Nähte je nach Bahnenart (§6.1.2.1): Gießverfahren, Gieß- und Einwalzverfahren, Flämmverfahren, Schweißverfahren oder Kaltselbstklebeverfahren, nach DIN 18535 und DIN 18533. Naht- und Stoßverbindungen sind auf der Baustelle auf Dichtheit zu prüfen, i. d. R. optisch (Raupenbildung). Verfahren und Prüfergebnis eintragen.
[EN] Seam joining technique by sheet type (§6.1.2.1): pouring, pour-and-roll, torching, welding or cold self-adhesive method, per DIN 18535 and DIN 18533. Seam and butt joints must be checked for tightness on site, as a rule visually (bead formation). Enter method and test result.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-15' AND x.symbol = 'bb_nahtverbindung';
UPDATE fields x SET description = 'Zugfestigkeit der Bahn in N/50 mm laut Leistungserklärung/CE-Dokument des Herstellers. Die Richtlinie nennt keinen Zahlenwert; die bahnenspezifischen Anforderungen an die Werkstoffeigenschaften stehen in den Werkstoffnormen (DIN EN 13969) und werden durch Eigen- und Fremdüberwachung des Herstellers sichergestellt (§6.1.3.2). Für spezielle Einsatzgebiete sind die Eigenschaften bei der Planung objektspezifisch zu klären (§6.1.3.1).
[EN] Tensile strength of the sheet in N/50 mm per the manufacturer''s declaration of performance/CE document. The guideline gives no figure; the sheet-specific material requirements are listed in the material standards (DIN EN 13969) and secured by the manufacturer''s self- and third-party monitoring (§6.1.3.2). For special applications the properties must be clarified for the specific project during design (§6.1.3.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-15' AND x.symbol = 'bb_zugfestigkeit';
UPDATE fields x SET description = 'Kurzzeichen der Bahn nach DIN SPEC 20000-202 aus Tab. 19 (14 gedruckte Bahnen, Anwendungstyp BA): Bitumen-Dachdichtungsbahnen G 200 DD / PV 200 DD, Polymerbitumen-Dachdichtungsbahnen PYE G 200 DD / PYE PV 200 DD, Bitumenschweißbahnen G 200 S4 / PV 200 S5 / KTG S4 / KTP S4, Polymerbitumenschweißbahnen PYE G 200 S4 / PYE PV 200 S5 / PYE KTG S4 / PYE KTP S5, kaltselbstklebende Polymerbitumenbahnen mit Trägereinlage PYE-KTG KSP-2,8 / PYE-KTP KSP-2,8. Aus dem Herstellerdatenblatt übernehmen; die Bahnenart wird daraus gefüllt (§6.1.1.1).
[EN] Designation of the sheet per DIN SPEC 20000-202 from Tab. 19 (14 printed sheets, application type BA): bitumen roofing sheets G 200 DD / PV 200 DD, polymer-bitumen roofing sheets PYE G 200 DD / PYE PV 200 DD, bitumen torch-on sheets G 200 S4 / PV 200 S5 / KTG S4 / KTP S4, polymer-bitumen torch-on sheets PYE G 200 S4 / PYE PV 200 S5 / PYE KTG S4 / PYE KTP S5, cold self-adhesive polymer-bitumen sheets with carrier PYE-KTG KSP-2,8 / PYE-KTP KSP-2,8. Take it from the manufacturer''s data sheet; the sheet type is filled from it (§6.1.1.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-15' AND x.symbol = 'bb_kurzzeichen_tab19';
UPDATE fields x SET description = 'Wird aus Tab. 19 zum gewählten Kurzzeichen übernommen: Bitumen-Dachdichtungsbahnen, Polymerbitumen-Dachdichtungsbahnen, Bitumenschweißbahnen, Polymerbitumenschweißbahnen oder kaltselbstklebende Polymerbitumenbahnen mit Trägereinlage. Die Bahnenart bestimmt die mögliche Fügetechnik (§6.1.2.1). Nicht zu bearbeiten.
[EN] Filled from Tab. 19 for the chosen designation: bitumen roofing sheets, polymer-bitumen roofing sheets, bitumen torch-on sheets, polymer-bitumen torch-on sheets or cold self-adhesive polymer-bitumen sheets with carrier. The sheet type determines the possible joining technique (§6.1.2.1). Not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-15' AND x.symbol = 'bb_bahnenart_tab19';
UPDATE fields x SET description = 'Stoffart der zu fügenden Kunststoff-/Elastomerbahn nach Tab. 22: EVA, PIB, PVC-P, ECB, FPO, TPE, EPDM oder EPDM mit PBS (Polymerbitumenschicht). Zusammen mit dem Fügeverfahren bestimmt sie die Mindestfügebreite der Nähte (Tab. 22); Tab. 20 erläutert die Aufbau-Kurzzeichen (u. a. PBS = Polymerbitumenschicht); die Stoffnamen stehen in den Beispielen unter Tab. 20 und in der Bahnbezeichnung des Herstellers.
[EN] Material of the plastic/elastomer sheet to be joined per Tab. 22: EVA, PIB, PVC-P, ECB, FPO, TPE, EPDM or EPDM with PBS (polymer-bitumen layer). Together with the joining method it sets the minimum joint width of the seams (Tab. 22); Tab. 20 explains the build-up codes (e.g. PBS = polymer-bitumen layer); the material names appear in the examples below Tab. 20 and in the manufacturer''s sheet designation.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-16' AND x.symbol = 'bahn_material_naht';
UPDATE fields x SET description = 'Dicke der Kunststoff-/Elastomerbahn in mm laut Bahnbezeichnung (die Zahl im Kurzzeichen, z. B. „…-1,2“, Tab. 20) bzw. Datenblatt. §6.2.1.2 verlangt mindestens 1,2 mm; bei werkseitig vorkonfektionierten Bahnen für gering beanspruchte Nutzungen (z. B. Gartenteiche) sind ≥ 1,0 mm zulässig. Tor REQ-18 prüft gegen die berechnete Mindestdicke; Abdichtungen mit diesen Bahnen sind i. d. R. einlagig.
[EN] Thickness of the plastic/elastomer sheet in mm per the sheet designation (the number in the abbreviation, e.g. ''…-1,2'', Tab. 20) or data sheet. §6.2.1.2 requires at least 1.2 mm; for factory-prefabricated liners for low-stress uses (e.g. garden ponds) ≥ 1.0 mm is permitted. Gate REQ-18 checks against the computed minimum; sealings with these sheets are as a rule single-layer.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-16' AND x.symbol = 'bahnendicke_mm';
UPDATE fields x SET description = 'Fügeverfahren der Nähte nach Tab. 22: Quellschweißen (EVA, PIB, PVC-P), Heißluft- oder Heizkeilschweißen (ECB, EVA, PIB, FPO, PVC-P, TPE, EPDM), Heißvulkanisation/Hot Bonding (EPDM) oder Heißluftschweißen (EPDM mit PBS). Verfahren und Stoffart ergeben die Mindestfügebreite; Nahtverbindungen sind nach DIN 18535 und DIN 18533 herzustellen (§6.2.2.1).
[EN] Seam joining method per Tab. 22: solvent welding (EVA, PIB, PVC-P), hot-air or hot-wedge welding (ECB, EVA, PIB, FPO, PVC-P, TPE, EPDM), hot vulcanisation/hot bonding (EPDM) or hot-air welding (EPDM with PBS). Method and material give the minimum joint width; seams are made per DIN 18535 and DIN 18533 (§6.2.2.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-16' AND x.symbol = 'fuegeverfahren';
UPDATE fields x SET description = 'Ausgeführte Breite der Überlappung an Längs- und Quernähten in mm (Verlegeplan/Aufmaß). §6.2.2.1 verlangt mindestens 40 mm, bei Bahnen mit Polymerbitumenbeschichtung mindestens 60 mm; Vergleichswert „Mindestbreite der Überlappung“. Die Überlappung ist von der Fügebreite (tatsächlich verschweißte Breite nach Tab. 22) zu unterscheiden.
[EN] Executed overlap width at longitudinal and cross seams in mm (laying plan/measurement). §6.2.2.1 requires at least 40 mm, for sheets with polymer-bitumen coating at least 60 mm; comparison value ''minimum overlap width''. The overlap is distinct from the joint width (actually welded width per Tab. 22).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-16' AND x.symbol = 'naht_ueberlappung_kunststoff_mm';
UPDATE fields x SET description = 'Mindestfügebreite der Nähte in mm nach Tab. 22 für die gewählte Kombination aus Fügeverfahren und Stoffart: Quellschweißen EVA/PIB/PVC-P 30; Heißluft-/Heizkeilschweißen ECB, EVA, PIB, FPO, PVC-P, TPE 20 und EPDM 30; Heißvulkanisation EPDM 20; Heißluftschweißen EPDM mit PBS 40. Wert aus Tab. 22 eintragen; er dient den Blättern FLL-GAR-15/18 und wird je Naht auch im Nahtregister geführt (§6.2.2.1).
[EN] Minimum joint width of the seams in mm per Tab. 22 for the chosen combination of joining method and material: solvent welding EVA/PIB/PVC-P 30; hot-air/hot-wedge welding ECB, EVA, PIB, FPO, PVC-P, TPE 20 and EPDM 30; hot vulcanisation EPDM 20; hot-air welding EPDM with PBS 40. Enter the Tab. 22 value; it serves sheets FLL-GAR-15/18 and is also carried per seam in the seam register (§6.2.2.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-16' AND x.symbol = 'nahtbreite_min_mm';
UPDATE fields x SET description = 'Angabe, ob die Bahn eine Polymerbitumenbeschichtung (PBS, Tab. 20) trägt, z. B. EPDM-BV-V-(X)-PBS nach Tab. 21. Mit Beschichtung steigt die Mindestbreite der Überlappung an Längs-/Quernähten von 40 mm auf 60 mm (§6.2.2.1), und für EPDM mit PBS gilt Heißluftschweißen mit 40 mm Mindestfügebreite (Tab. 22).
[EN] Whether the sheet carries a polymer-bitumen coating (PBS, Tab. 20), e.g. EPDM-BV-V-(X)-PBS per Tab. 21. With the coating the minimum overlap at longitudinal/cross seams rises from 40 mm to 60 mm (§6.2.2.1), and EPDM with PBS is hot-air welded with a 40 mm minimum joint width (Tab. 22).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-16' AND x.symbol = 'polymerbitumen_beschichtung';
UPDATE fields x SET description = 'Wird aus §6.2.2.1 übernommen: Mindestbreite der Überlappung an Längs- und Quernähten 40 mm, bei Bahnen mit Polymerbitumenbeschichtung 60 mm – „einzuhalten“. Vergleichswert für die eingegebene Nahtüberlappung. Nicht zu bearbeiten.
[EN] Filled from §6.2.2.1: minimum overlap width at longitudinal and cross seams 40 mm, for sheets with polymer-bitumen coating 60 mm – to be kept. Comparison value for the entered seam overlap. Not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-16' AND x.symbol = 'naht_ueberlappung_min_mm';
UPDATE fields x SET description = 'Register aller Nähte der Abdichtung, eine Zeile je Naht: Fügeverfahren, Stoffart, ausgeführte Fügebreite in mm und Prüfergebnis. Je Zeile wird die Mindestfügebreite aus Tab. 22 ermittelt (z. B. Heißluftschweißen EPDM 30 mm, PVC-P 20 mm, Quellschweißen PVC-P 30 mm); Zeilen darunter zählt Gleichung FLL-GAR-16-D1 als Verstöße, Tor REQ-39 verlangt null. Eine nicht in Tab. 22 gedruckte Kombination hat keinen Grenzwert und bleibt unentscheidbar. Jede Naht ist auf Dichtheit zu prüfen – mindestens zwei der Verfahren mechanische Prüfung (Reißnadel), optische Prüfung, Anblasprüfung, Vakuumprüfung nach DIN 18535-2 (§6.2.2.1).
[EN] Register of all seams of the sealing, one row per seam: joining method, material, executed joint width in mm and test result. For each row the minimum joint width is taken from Tab. 22 (e.g. hot-air welding EPDM 30 mm, PVC-P 20 mm, solvent welding PVC-P 30 mm); rows below it are counted as violations by equation FLL-GAR-16-D1, gate REQ-39 requires zero. A combination not printed in Tab. 22 has no limit and stays undecidable. Every seam must be tested for tightness – at least two of mechanical test (scriber), visual test, air-blow test, vacuum test per DIN 18535-2 (§6.2.2.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-16' AND x.symbol = 'naehte';
UPDATE fields x SET description = 'Wird berechnet (Gleichung FLL-GAR-16-D1): Anzahl der Zeilen des Nahtregisters, deren Fügebreite unter der Mindestfügebreite der Tab. 22 liegt. Tor REQ-39 verlangt 0; ein leeres Register ergibt ebenfalls 0, daher alle Nähte erfassen. Nicht zu bearbeiten.
[EN] Computed (equation FLL-GAR-16-D1): number of seam-register rows whose joint width lies below the Tab. 22 minimum. Gate REQ-39 requires 0; an empty register also yields 0, so record every seam. Not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-16' AND x.symbol = 'naht_verletzungen';
UPDATE fields x SET description = 'Auswahl, ob die Bahn werkseitig vorkonfektioniert für eine gering beanspruchte Nutzung (z. B. Gartenteich) geliefert wird. „ja“: Bahnendicken ≥ 1,0 mm zulässig; „nein“: Regelfall mit Mindestdicke 1,2 mm (§6.2.1.2). Eingang der Gleichung FLL-GAR-16-D2; nach Herstellerangabe und Nutzung des Gewässers wählen.
[EN] Select whether the liner is delivered factory-prefabricated for a low-stress use (e.g. garden pond). ''yes'': thicknesses ≥ 1.0 mm permitted; ''no'': standard case with minimum thickness 1.2 mm (§6.2.1.2). Input of equation FLL-GAR-16-D2; choose per manufacturer''s statement and the use of the water body.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-16' AND x.symbol = 'bahn_vorkonfektioniert';
UPDATE fields x SET description = 'Wird berechnet (Gleichung FLL-GAR-16-D2): 1,0 mm bei werkseitig vorkonfektionierter Bahn für gering beanspruchte Nutzung, sonst 1,2 mm (§6.2.1.2). Vergleichswert für die eingegebene Bahnendicke; Tor REQ-18 prüft Bahnendicke ≥ Mindestdicke. Nicht zu bearbeiten.
[EN] Computed (equation FLL-GAR-16-D2): 1.0 mm for a factory-prefabricated liner for low-stress use, otherwise 1.2 mm (§6.2.1.2). Comparison value for the entered sheet thickness; gate REQ-18 checks sheet thickness ≥ minimum. Not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-16' AND x.symbol = 'bahnendicke_min_mm';
UPDATE fields x SET description = 'Bahnbezeichnung nach DIN/TS 20.000-202 aus Tab. 21 (Anwendung Typ BA), gegliedert nach Bahnenart: homogene Bahnen (z. B. EVA-BV-1,2, EPDM-BV-1,1, PVC-P-NB-1,2, FPO-BV-1,2, PIB-BV-1,5), mit Selbstklebeschicht (-SK), mit Einlagen (-E-GV-), mit Verstärkung (-V-(X)-), mit Kaschierung (-K-(X)-) und Kombinationen. (X) steht für die Art der Verstärkung/Kaschierung nach Tab. 20 (z. B. PV, GG, PG, PPV); Fußnote 1: alternativ werkseitige Polymerbitumenschicht. Aus dem Herstellerdatenblatt übernehmen; Stoffgruppe und Bahnenart werden daraus gefüllt (§6.2.1.1).
[EN] Sheet designation per DIN/TS 20.000-202 from Tab. 21 (application type BA), grouped by sheet type: homogeneous sheets (e.g. EVA-BV-1,2, EPDM-BV-1,1, PVC-P-NB-1,2, FPO-BV-1,2, PIB-BV-1,5), with self-adhesive layer (-SK), with inserts (-E-GV-), with reinforcement (-V-(X)-), with lamination (-K-(X)-) and combinations. (X) stands for the kind of reinforcement/lamination per Tab. 20 (e.g. PV, GG, PG, PPV); footnote 1: alternatively a factory polymer-bitumen layer. Take it from the manufacturer''s data sheet; material group and sheet type are filled from it (§6.2.1.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-16' AND x.symbol = 'bahn_bezeichnung_tab21';
UPDATE fields x SET description = 'Wird aus Tab. 21 zur gewählten Bahnbezeichnung übernommen: Kunststoffbahn (EVA, PVC-P, PIB, FPO, ECB) oder Elastomerbahn (EPDM, TPE). Die Stoffart ist auch für Fügeverfahren und Mindestfügebreite nach Tab. 22 maßgebend. Nicht zu bearbeiten.
[EN] Filled from Tab. 21 for the chosen sheet designation: plastic sheet (EVA, PVC-P, PIB, FPO, ECB) or elastomer sheet (EPDM, TPE). The material also governs the joining method and minimum joint width per Tab. 22. Not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-16' AND x.symbol = 'bahn_stoffgruppe_tab21';
UPDATE fields x SET description = 'Wird aus Tab. 21 übernommen: homogene Bahnen, homogene Bahnen mit Selbstklebeschicht, Bahnen mit Einlagen, mit Einlage und Selbstklebeschicht/Polymerbitumenbeschichtung, mit Verstärkung, mit Verstärkung und Selbstklebeschicht/Polymerbitumenbeschichtung, mit Kaschierungen oder mit Kaschierung und Selbstklebeschicht. Aufbau nach §6.2: Einlage = innen liegendes Glasvlies ≤ 80 g/m², Verstärkung innen liegend aus Gewebe/Gelege/Vliesstoff, Kaschierung auf der Unterseite. Nicht zu bearbeiten.
[EN] Filled from Tab. 21: homogeneous sheets, homogeneous sheets with self-adhesive layer, sheets with inserts, with insert and self-adhesive layer/polymer-bitumen coating, with reinforcement, with reinforcement and self-adhesive layer/polymer-bitumen coating, with laminations or with lamination and self-adhesive layer. Build-up per §6.2: insert = internal glass fleece ≤ 80 g/m², reinforcement internal of woven/laid/nonwoven fabric, lamination on the underside. Not to be edited.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-16' AND x.symbol = 'bahn_bahnenart_tab21';
UPDATE equations x SET description = 'Zählt die Zeilen des Nahtregisters, deren ausgeführte Fügebreite unter der Mindestfügebreite der Tab. 22 für ihre Kombination aus Fügeverfahren und Stoffart liegt (Quellschweißen 30 mm; Heißluft-/Heizkeilschweißen 20 mm, EPDM 30 mm; Heißvulkanisation EPDM 20 mm; Heißluftschweißen EPDM mit PBS 40 mm). Eingabe: Nahtregister; Ergebnis naht_verletzungen (Anzahl) für Tor REQ-39. Zeilen ohne gedruckte Tab.-22-Kombination machen das Ergebnis unentscheidbar.
[EN] Counts the seam-register rows whose executed joint width lies below the Tab. 22 minimum for their combination of joining method and material (solvent welding 30 mm; hot-air/hot-wedge welding 20 mm, EPDM 30 mm; hot vulcanisation EPDM 20 mm; hot-air welding EPDM with PBS 40 mm). Input: seam register; result naht_verletzungen (count) for gate REQ-39. Rows without a printed Tab. 22 combination make the result undecidable.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-16' AND x.equation_number = 'FLL-GAR-16-D1';
UPDATE equations x SET description = 'Bestimmt die Mindestdicke der Kunststoff-/Elastomerbahn aus der Auswahl „werkseitig vorkonfektioniert für gering beanspruchte Nutzung“: ja → 1,0 mm, nein → 1,2 mm (§6.2.1.2: Mindestdicke 1,2 mm; bei werkseitig vorkonfektionierten Bahnen für gering beanspruchte Nutzungen, z. B. Gartenteiche, ≥ 1,0 mm zulässig). Ergebnis bahnendicke_min_mm in mm, Vergleichswert für die Bahnendicke in Tor REQ-18.
[EN] Determines the minimum thickness of the plastic/elastomer sheet from the selection ''factory-prefabricated for low-stress use'': yes → 1.0 mm, no → 1.2 mm (§6.2.1.2: minimum 1.2 mm; for factory-prefabricated liners for low-stress uses such as garden ponds ≥ 1.0 mm permitted). Result bahnendicke_min_mm in mm, comparison value for the sheet thickness in gate REQ-18.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-16' AND x.equation_number = 'FLL-GAR-16-D2';
UPDATE compliance_requirements x SET description = 'Gilt bei Kunststoff-/Elastomerbahnen. Besteht, wenn die eingegebene Bahnendicke mindestens die berechnete Mindestdicke erreicht: 1,2 mm im Regelfall, 1,0 mm nur bei werkseitig vorkonfektionierten Bahnen für gering beanspruchte Nutzungen wie Gartenteiche (§6.2.1.2). Einzugeben: Bahnendicke (aus Bahnbezeichnung/Datenblatt) und die Auswahl „vorkonfektioniert“. Die Mindestfügebreiten der Nähte nach Tab. 22 prüft Tor REQ-39.
[EN] Applies to plastic/elastomer sheets. Passes when the entered sheet thickness reaches at least the computed minimum: 1.2 mm in the standard case, 1.0 mm only for factory-prefabricated liners for low-stress uses such as garden ponds (§6.2.1.2). Enter the sheet thickness (from designation/data sheet) and the ''prefabricated'' selection. The minimum joint widths of the seams per Tab. 22 are checked by gate REQ-39.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-16' AND x.code = 'REQ-18';
UPDATE compliance_requirements x SET description = 'Gilt bei Kunststoff-/Elastomerbahnen. Besteht, wenn keine Naht im Nahtregister unter der Mindestfügebreite der Tab. 22 liegt (Zähler naht_verletzungen = 0): Quellschweißen 30 mm (EVA, PIB, PVC-P); Heißluft-/Heizkeilschweißen 20 mm (ECB, EVA, PIB, FPO, PVC-P, TPE) bzw. 30 mm (EPDM); Heißvulkanisation EPDM 20 mm; Heißluftschweißen EPDM mit PBS 40 mm. Einzugeben: je Naht Fügeverfahren, Stoffart und Fügebreite – ein leeres Register besteht formal, daher alle Nähte erfassen. Je nach Stoffart sind Fügeverfahren und Mindestfügebreiten einzuhalten (§6.2.2.1).
[EN] Applies to plastic/elastomer sheets. Passes when no seam in the seam register lies below the Tab. 22 minimum joint width (counter naht_verletzungen = 0): solvent welding 30 mm (EVA, PIB, PVC-P); hot-air/hot-wedge welding 20 mm (ECB, EVA, PIB, FPO, PVC-P, TPE) or 30 mm (EPDM); hot vulcanisation EPDM 20 mm; hot-air welding EPDM with PBS 40 mm. Enter joining method, material and joint width per seam – an empty register passes formally, so record every seam. Joining methods and minimum joint widths must be kept per material (§6.2.2.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-16' AND x.code = 'REQ-39';
UPDATE fields x SET description = 'Freitext zum eingesetzten Flüssigkunststoff-System (Produktname, Komponenten 1K/2K) aus Hersteller-Datenblatt und Zulassung. Die Richtlinie lässt flexibles ungesättigtes Polyesterharz (UP), Polyurethanharz (PUR 1K/2K) und Polymethylmethacrylatharz (PMMA) zu; das Produkt muss der ETAG 005/EAD 030350-00-0402 entsprechen, für bauaufsichtlich relevante Abdichtungen genügt auch ein AbP nach MVV TB (§6.3.1, Tab. 23). Die eigentliche Stoffwahl erfolgt im Feld „Stoff nach Tab. 23“.
[EN] Free text for the liquid-applied system used (product name, 1K/2K components) from the manufacturer''s data sheet and approval. The guideline admits flexible unsaturated polyester resin (UP), polyurethane resin (PUR 1K/2K) and polymethyl methacrylate resin (PMMA); the product must comply with ETAG 005/EAD 030350-00-0402, and for building-code-relevant sealings an AbP per MVV TB is also acceptable (§6.3.1, Tab. 23). The actual material choice is made in the field ''material per Tab. 23''.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-17' AND x.symbol = 'fk_systemtyp';
UPDATE fields x SET description = 'Dicke der ausgehärteten Flüssigabdichtung in mm aus der Schichtdickenmessung (Ausführungsprotokoll) oder der Systembeschreibung. Sie muss den Angaben der Zulassung (ETA, AbP) entsprechen und beträgt nach Tab. 23 mind. 2,0 mm; nennt die ETA eine höhere Mindestdicke, gilt der höhere Wert (§6.3.1.2). Tor REQ-41 vergleicht den Wert mit der Tab.-23-Mindestdicke und der Zulassungsdicke.
[EN] Thickness of the cured liquid-applied sealing in mm from the film-thickness measurement (execution record) or the system description. It must match the approval (ETA, AbP) and is at least 2.0 mm per Tab. 23; if the ETA states a higher minimum, the higher value applies (§6.3.1.2). Gate REQ-41 compares the value with the Tab. 23 minimum and the approval minimum.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-17' AND x.symbol = 'fk_trockenschichtdicke';
UPDATE fields x SET description = 'Art der Einlage (z. B. Glasvlies, Polyestervlies) laut Zulassung und Datenblatt. Die Einlage muss Bestandteil der Zulassung sein (§6.3), ein Flächengewicht von mind. 110 g/m² haben (§6.3.2) und die Einlagebahnen müssen sich mind. 50 mm überlappen (§6.3.2.1). Das Flächengewicht selbst wird im Feld „Flächengewicht der eingesetzten Einlage“ eingetragen.
[EN] Type of insert (e.g. glass fleece, polyester fleece) per approval and data sheet. The insert must be part of the approval (§6.3), have a mass per unit area of at least 110 g/m² (§6.3.2), and the insert strips must overlap by at least 50 mm (§6.3.2.1). The mass per unit area itself is entered in the field ''mass per unit area of the insert used''.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-17' AND x.symbol = 'fk_armierung';
UPDATE fields x SET description = 'Verfahren, mit dem Träger- und Deckschicht aufgebracht werden: die Richtlinie nennt Streichen, Rollen oder Spritzen. Die Abdichtung wird i. d. R. vollflächig haftend und mindestens zweischichtig (Träger-, Deckschicht) mit Einlage ausgeführt, nach DIN 18535-3 / DIN 18533-3, den Vorgaben der Zulassung und der Hersteller-Verarbeitungsvorschrift (§6.3.2).
[EN] Method used to apply the base and top coat: the guideline names brushing, rolling or spraying. The sealing is normally fully bonded and applied in at least two coats (base and top coat) with an insert, per DIN 18535-3 / DIN 18533-3, the approval and the manufacturer''s application instructions (§6.3.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-17' AND x.symbol = 'fk_auftragsverfahren';
UPDATE fields x SET description = 'Gemessene Haftzugfestigkeit der Abdichtung zum Untergrund in N/mm² aus dem Prüfbericht einer Haftzugprüfung. Die Richtlinie nennt keinen Zahlenwert, verlangt aber einen vollflächigen Haftungsverbund zum Untergrund zur Vermeidung der Hinterläufigkeit; der Untergrund muss in Festigkeit und Oberflächenbeschaffenheit geeignet, vorbereitet und ggf. grundiert sein (§6.3.2). Vergleichswert: Angabe der Zulassung bzw. des Herstellers.
[EN] Measured adhesive tensile strength of the sealing to the substrate in N/mm² from a pull-off test report. The guideline prints no number but requires a full-surface adhesive bond to the substrate to prevent water running behind; the substrate must be suitable in strength and surface condition, prepared and primed if needed (§6.3.2). Reference value: the approval''s or manufacturer''s figure.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-17' AND x.symbol = 'fk_haftung_untergrund';
UPDATE fields x SET description = 'Angabe zur UV-/Witterungsbeständigkeit des Systems laut Hersteller-Datenblatt bzw. Zulassung (z. B. dauerhaft freiliegend geeignet oder Schutzschicht nötig). Nach §6.3 bietet der ausgehärtete Belag als einlagige Abdichtung ausreichenden Widerstand gegenüber natürlichen Witterungs- und Alterungsprozessen; §4.11 verlangt je nach stofflicher Beschaffenheit einen Schutz gegen UV-Einwirkung. Grundlage für die Entscheidung über Schutzschichten (FLL-GAR-22).
[EN] Statement on the UV/weathering resistance of the system per manufacturer''s data sheet or approval (e.g. suitable permanently exposed, or protection layer needed). Per §6.3 the cured coating as a single-layer sealing offers sufficient resistance to natural weathering and ageing; §4.11 requires protection against UV exposure depending on the material. Basis for the protection-layer decision (FLL-GAR-22).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-17' AND x.symbol = 'fk_uv_bestaendigkeit';
UPDATE fields x SET description = 'Wahl des Flüssigkunststoffs nach Tab. 23: UP = flexibles ungesättigtes Polyesterharz, PUR = flexibles Polyurethanharz (1K oder 2K), PMMA = flexibles Polymethylmethacrylatharz. Für alle drei gelten dieselben Leistungsstufen nach ETAG 005/EAD 030350-00-0402: Klimazonen M, S; Nutzungsdauer W3 (25 Jahre); Nutzlast P4 (befahrbar in Abstimmung mit dem Planer); Neigung S1–S4; Temperaturbeständigkeit TL3, TH3, TL4, TH4 (Anhang 3) sowie Einlage ≥ 110 g/m² und Schichtdicke ≥ 2,0 mm. Die Wahl füllt die Mindestwerte für Tor REQ-41.
[EN] Choice of liquid-applied plastic per Tab. 23: UP = flexible unsaturated polyester resin, PUR = flexible polyurethane resin (1K or 2K), PMMA = flexible polymethyl methacrylate resin. All three carry the same performance levels per ETAG 005/EAD 030350-00-0402: climate zones M, S; working life W3 (25 years); imposed load P4 (trafficable in agreement with the designer); slope S1–S4; temperature resistance TL3, TH3, TL4, TH4 (Annex 3), plus insert ≥ 110 g/m² and thickness ≥ 2.0 mm. The choice fills the minimum values for gate REQ-41.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-17' AND x.symbol = 'fk_stoff_tab23';
UPDATE fields x SET description = 'Wird aus Tab. 23 zum gewählten Stoff übernommen: Die Mindestschichtdicke der ausgehärteten Abdichtung beträgt für UP, PUR und PMMA gleichermaßen 2,0 mm (§6.3.1.2). Untere Grenze für die Trockenschichtdicke in Tor REQ-41; eine höhere Mindestdicke der Zulassung wird im Feld daneben erfasst.
[EN] Filled from Tab. 23 for the chosen material: the minimum thickness of the cured sealing is 2.0 mm for UP, PUR and PMMA alike (§6.3.1.2). Lower limit for the dry film thickness in gate REQ-41; a higher approval minimum is entered in the adjacent field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-17' AND x.symbol = 'fk_schichtdicke_min_mm';
UPDATE fields x SET description = 'Mindestschichtdicke laut Zulassung des Produkts (ETA oder AbP), aus dem Zulassungsdokument. Nur eintragen, wenn sie über 2,0 mm liegt: „Wenn die in der ETA angegebene Mindestschichtdicke höher ist, gilt der höhere Wert“ (§6.3.1.2). Leer lassen, wenn die Zulassung keinen höheren Wert nennt — Tor REQ-41 prüft dann nur gegen Tab. 23.
[EN] Minimum thickness per the product''s approval (ETA or AbP), taken from the approval document. Enter only if it exceeds 2.0 mm: ''if the minimum thickness stated in the ETA is higher, the higher value applies'' (§6.3.1.2). Leave empty if the approval states no higher value — gate REQ-41 then checks against Tab. 23 only.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-17' AND x.symbol = 'fk_eta_mindestschichtdicke_mm';
UPDATE fields x SET description = 'Wird aus Tab. 23 übernommen: Flächengewicht der Einlage ≥ 110 g/m², für alle drei Stoffe gleich; §6.3.2 wiederholt die Forderung („Einlagen … mit einem Flächengewicht von mind. 110 g/m²“). Untere Grenze für das Ist-Flächengewicht in Tor REQ-41.
[EN] Filled from Tab. 23: mass per unit area of the insert ≥ 110 g/m², the same for all three materials; §6.3.2 repeats the requirement (''inserts … with a mass per unit area of at least 110 g/m²''). Lower limit for the actual mass per unit area in gate REQ-41.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-17' AND x.symbol = 'fk_einlage_min_g_m2';
UPDATE fields x SET description = 'Tatsächliches Flächengewicht der eingebauten Einlage in g/m² (z. B. Glasvlies, Polyestervlies) laut Hersteller-Datenblatt bzw. Lieferschein. Es muss mind. 110 g/m² betragen (§6.3.2, Tab. 23), und die Einlage muss Bestandteil der Zulassung sein (§6.3). Tor REQ-41 vergleicht den Wert mit der Tab.-23-Vorgabe.
[EN] Actual mass per unit area of the installed insert in g/m² (e.g. glass fleece, polyester fleece) per manufacturer''s data sheet or delivery note. It must be at least 110 g/m² (§6.3.2, Tab. 23), and the insert must be part of the approval (§6.3). Gate REQ-41 compares the value with the Tab. 23 requirement.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-17' AND x.symbol = 'fk_einlage_g_m2';
UPDATE fields x SET description = 'Bestätigung nur für Abdichtungen mit Flüssigkunststoff: Das Produkt ist mit den Klassen-Kurzzeichen des Anhangs 3 ausgewiesen (Klimazone M/S, Nutzungsdauer W1–W3, Nutzlast P1–P4, Neigung S1–S4, Temperaturen TL1–TL4 und TH1–TH4) und erreicht die in Tab. 23 geforderten Stufen (M, S; W3; P4; S1–S4; TL3, TH3, TL4, TH4) laut ETA bzw. AbP des Herstellers (§6.3.1, §6.3.1.1). Tor REQ-19 blockiert ohne Haken; enthält das Vorhaben keinen Flüssigkunststoff, hat das Feld fachlich keinen Gegenstand.
[EN] Attestation that applies only to liquid-plastic sealings: the product is declared with the Anhang 3 class designations (climate zone M/S, service life W1–W3, imposed load P1–P4, slope S1–S4, temperatures TL1–TL4 and TH1–TH4) and reaches the levels Tab. 23 requires (M, S; W3; P4; S1–S4; TL3, TH3, TL4, TH4) per the manufacturer''s ETA or AbP (§6.3.1, §6.3.1.1). Gate REQ-19 blocks until ticked; if the project contains no liquid plastic, the field has no technical object.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-17' AND x.symbol = 'attest_fll_gar_10_req_19';
UPDATE compliance_requirements x SET description = 'Gilt nur, wenn als Abdichtungsart Flüssigkunststoff gewählt ist. Bestanden, wenn drei Bedingungen erfüllt sind: Trockenschichtdicke ≥ 2,0 mm (Tab. 23), Trockenschichtdicke ≥ Mindestdicke der Zulassung, falls diese höher ist (§6.3.1.2), und Flächengewicht der Einlage ≥ 110 g/m² (§6.3.2). Einzutragen: Stoff nach Tab. 23 (füllt die Mindestwerte), Trockenschichtdicke, Flächengewicht der Einlage, bei Bedarf die ETA-/AbP-Mindestdicke. Grund: „Die Mindestschichtdicke … muss den Angaben der Zulassung entsprechen“ und „Es müssen Einlagen … eingesetzt werden“ — beides Muss-Vorgaben.
[EN] Applies only when liquid-applied plastic is the chosen sealing type. Passes when three conditions hold: dry film thickness ≥ 2.0 mm (Tab. 23), dry film thickness ≥ the approval minimum if that is higher (§6.3.1.2), and insert mass per unit area ≥ 110 g/m² (§6.3.2). Enter: material per Tab. 23 (fills the minima), dry film thickness, insert mass per unit area and, if relevant, the ETA/AbP minimum. Reason: ''the minimum thickness … must match the approval'' and ''inserts … must be used'' are both mandatory wording.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-17' AND x.code = 'REQ-41';
UPDATE compliance_requirements x SET description = 'Besteht, wenn die Bestätigung zur Klassifikation des Flüssigkunststoffs gesetzt ist. Was dafür wahr sein muss: Das Produkt ist mit den Kurzzeichen des Anhangs 3 (Klimazone M/S, Nutzungsdauer W1–W3, Nutzlast P1–P4, Neigung S1–S4, Temperaturen TL1–TL4/TH1–TH4) ausgewiesen und erfüllt die Stufen der Tab. 23 (M, S; W3; P4; S1–S4; TL3, TH3, TL4, TH4) laut ETA bzw. AbP (§6.3.1, §6.3.1.1). Sitzt auf Blatt FLL-GAR-17 (Flüssigkunststoff) und wird nur bei Abdichtungsart Flüssigkunststoff (Wahl in FLL-GAR-09) ausgewertet; dort den Haken setzen.
[EN] Passes when the liquid-plastic classification attestation is ticked. What must be true: the product is declared with the Anhang 3 designations (climate M/S, service life W1–W3, load P1–P4, slope S1–S4, temperatures TL1–TL4/TH1–TH4) and meets the Tab. 23 levels (M, S; W3; P4; S1–S4; TL3, TH3, TL4, TH4) per its ETA or AbP (§6.3.1, §6.3.1.1). Sits on sheet FLL-GAR-17 (liquid-applied plastic) and is evaluated only for the sealing type liquid-applied plastic (chosen in FLL-GAR-09); tick the box there.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-17' AND x.code = 'REQ-19';
UPDATE fields x SET description = 'Überlappung der verschweißten Bahnenränder in mm aus Verlegeplan bzw. Schweißprotokoll oder der Herstellerverlegeanleitung. Die Nahtüberlappung sollte je nach Schweißautomat zwischen 100 und 150 mm betragen; die Nahtgeometrie regelt DVS 2225 Teil 1, geeignete Techniken sind Warmgasextrusions- und Heizkeilschweißen, T-Stöße sind auf ein Minimum zu reduzieren (§6.4.2.1). Tor REQ-36 (Hinweis) prüft 100–150 mm.
[EN] Overlap of the welded sheet edges in mm from the laying plan or welding record, or the manufacturer''s laying instructions. The seam overlap should be between 100 and 150 mm depending on the welding machine; seam geometry follows DVS 2225 Part 1, suitable techniques are hot-gas extrusion and hot-wedge welding, T-joints must be kept to a minimum (§6.4.2.1). Gate REQ-36 (warning) checks 100–150 mm.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'naht_pe_ueberlappung_mm';
UPDATE fields x SET description = 'Beanspruchungsstufe nach Tab. 25; die Einstufung der projektspezifischen Einwirkungen obliegt dem Objektplanenden. gering: geringe hydraulische Gradienten, geringe mechanische Beanspruchung, keine Exposition (private Zier-/Badeteiche, Konvektions-/Rhizomsperre). mittel: mittlere Gradienten oder mittlere Beanspruchung oder geringe Exposition (öffentliche Zierteiche, Bachläufe). hoch: hohe Gradienten oder hohe Beanspruchung oder moderate Exposition (öffentliche Badeteiche, befahrbare Bereiche, Fließgewässer). freiliegend: wie hoch, jedoch Bahn freiliegend oder hohe Exposition (Regenrückhaltebecken, Beschneiungsteiche). Exposition = chemische Faktoren und UV. Steuert die empfohlene Nenndicke.
[EN] Loading class per Tab. 25; classifying the project-specific actions is the designer''s responsibility. low: low hydraulic gradients, low mechanical loading, no exposure (private ornamental/bathing ponds, convection/rhizome barrier). medium: medium gradients or medium loading or low exposure (public ornamental ponds, streams). high: high gradients or high loading or moderate exposure (public bathing ponds, trafficked areas, flowing waters). exposed: as high but liner exposed or high exposure (retention basins, snowmaking ponds). Exposure = chemical factors and UV. Drives the recommended nominal thickness.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'pe_beanspruchung_klasse';
UPDATE fields x SET description = 'Dichte der PEHD-Bahn in g/cm³ aus Leistungserklärung bzw. Hersteller-Datenblatt (Prüfnorm DIN EN ISO 1183). Tab. 24 fordert > 0,940 g/cm³; Dichte, Schmelzrate und Rußanteil sind laut §6.4.1 besonders zu beachten. Für PELD-Bahnen bestehen Anforderungen nur herstellerseits. Geht in die Tab.-24-Kennziffer (Gl. FLL-GAR-18-D2) ein.
[EN] Density of the PEHD liner in g/cm³ from the declaration of performance or manufacturer''s data sheet (test standard DIN EN ISO 1183). Tab. 24 requires > 0.940 g/cm³; density, melt flow rate and carbon black content are singled out in §6.4.1. For PELD liners requirements exist only on the manufacturer''s side. Feeds the Tab. 24 indicator (eq. FLL-GAR-18-D2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'peeh_dichte_g_cm3';
UPDATE fields x SET description = 'Schmelze-Massefließrate (MFR) der PEHD-Bahn in g/10 min aus Leistungserklärung bzw. Datenblatt (Prüfnorm DIN EN ISO 1133). Tab. 24 fordert ≥ 1,0 und ≤ 3,0 g/10 min. Nur für PEHD; geht in die Tab.-24-Kennziffer (Gl. FLL-GAR-18-D2) ein.
[EN] Melt mass-flow rate (MFR) of the PEHD liner in g/10 min from the declaration of performance or data sheet (test standard DIN EN ISO 1133). Tab. 24 requires ≥ 1.0 and ≤ 3.0 g/10 min. PEHD only; feeds the Tab. 24 indicator (eq. FLL-GAR-18-D2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'peeh_mfr';
UPDATE fields x SET description = 'Rußgehalt der PEHD-Bahn in % aus Leistungserklärung bzw. Datenblatt (Prüfnormen ASTM D 1603 / ASTM D 4218). Tab. 24 fordert 2–3 %. Nur für PEHD; geht in die Tab.-24-Kennziffer (Gl. FLL-GAR-18-D2) ein. Die Rußverteilung (Kategorie) wird getrennt erfasst.
[EN] Carbon black content of the PEHD liner in % from the declaration of performance or data sheet (test standards ASTM D 1603 / ASTM D 4218). Tab. 24 requires 2–3 %. PEHD only; feeds the Tab. 24 indicator (eq. FLL-GAR-18-D2). Carbon black dispersion (category) is recorded separately.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'peeh_russgehalt_pct';
UPDATE fields x SET description = 'Werkstoff der Bahn laut Datenblatt: PELD = Polyethylen mit geringer Dichte, PEHD = Polyethylen mit hoher Dichte (§6.4). Für PEHD gelten die werkstoffspezifischen Anforderungen der Tab. 24 und auf eine Prüfung der Wurzel-/Rhizomfestigkeit kann verzichtet werden; für PELD bestehen Anforderungen nur herstellerseits und der Hersteller muss zusätzlich einen Nachweis der Wurzel- bzw. Rhizomfestigkeit gemäß FLL erbringen (§6.4.1, §6.4.1.1). Steuert die Tab.-25-Vorgabe und Gl. FLL-GAR-18-D1.
[EN] Liner material per data sheet: PELD = low-density polyethylene, PEHD = high-density polyethylene (§6.4). For PEHD the material requirements of Tab. 24 apply and the root/rhizome resistance test may be omitted; for PELD requirements exist only on the manufacturer''s side and the manufacturer must additionally provide proof of root/rhizome resistance per FLL (§6.4.1, §6.4.1.1). Drives the Tab. 25 lookup and eq. FLL-GAR-18-D1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'pe_werkstoff';
UPDATE fields x SET description = 'Wird aus Tab. 25 zur gewählten Beanspruchungsstufe übernommen, nur bei PELD: gering ≥ 0,8 mm, mittel ≥ 1,5 mm; für hoch und freiliegend druckt Tab. 25 nur PEHD, daher „—“. Tab. 25 ist eine empfohlene Dicke; die Dicke ergibt sich aus dem konkreten Anwendungsfall und ist projektspezifisch zu prüfen (§6.4.1.2). Vergleichswert für die Ist-Nenndicke in Tor REQ-33 (Hinweis).
[EN] Filled from Tab. 25 for the chosen loading class, PELD only: low ≥ 0.8 mm, medium ≥ 1.5 mm; for high and exposed Tab. 25 prints PEHD only, hence ''—''. Tab. 25 is a recommended thickness; the thickness follows the specific application and must be checked per project (§6.4.1.2). Reference value for the actual nominal thickness in gate REQ-33 (warning).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'peld_nenndicke_min_mm';
UPDATE fields x SET description = 'Wird aus Tab. 25 zur gewählten Beanspruchungsstufe übernommen, nur bei PEHD: mittel ≥ 1,0 mm, hoch ≥ 2,0 mm, freiliegend ≥ 2,5 mm; für gering druckt Tab. 25 nur PELD, daher „—“. Tab. 25 ist eine empfohlene Dicke; die Dicke ergibt sich aus dem konkreten Anwendungsfall (§6.4.1.2). Vergleichswert für die Ist-Nenndicke in Tor REQ-33 (Hinweis).
[EN] Filled from Tab. 25 for the chosen loading class, PEHD only: medium ≥ 1.0 mm, high ≥ 2.0 mm, exposed ≥ 2.5 mm; for low Tab. 25 prints PELD only, hence ''—''. Tab. 25 is a recommended thickness; the thickness follows the specific application (§6.4.1.2). Reference value for the actual nominal thickness in gate REQ-33 (warning).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'pehd_nenndicke_min_mm';
UPDATE fields x SET description = 'Wird aus dem Werkstoff berechnet (Gl. FLL-GAR-18-D1): 1 = PELD, der Hersteller muss einen Nachweis der Wurzel- bzw. Rhizomfestigkeit gemäß FLL erbringen; 0 = PEHD, auf eine Prüfung der Wurzel- und Rhizomfestigkeit kann verzichtet werden (§6.4.1.1). Keine Eingabe; dient als Merker für die Nachweisführung in Blatt 09/24.
[EN] Computed from the material (eq. FLL-GAR-18-D1): 1 = PELD, the manufacturer must provide proof of root/rhizome resistance per FLL; 0 = PEHD, the root and rhizome resistance test may be omitted (§6.4.1.1). No input; serves as a marker for the proof in sheets 09/24.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'pe_rhizom_nachweis_code';
UPDATE fields x SET description = 'Wird berechnet (Gl. FLL-GAR-18-D2): 1, wenn Dichte > 0,940 g/cm³, MFR ≥ 1,0 und ≤ 3,0 g/10 min und Rußgehalt 2–3 % zugleich erfüllt sind (Tab. 24 Zeilen 3–5); sonst 0. Keine Eingabe; die drei Werte stammen aus der Leistungserklärung der PEHD-Bahn.
[EN] Computed (eq. FLL-GAR-18-D2): 1 when density > 0.940 g/cm³, MFR ≥ 1.0 and ≤ 3.0 g/10 min and carbon black content 2–3 % are all met (Tab. 24 rows 3–5); otherwise 0. No input; the three values come from the PEHD liner''s declaration of performance.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'pehd_tab24_code';
UPDATE fields x SET description = 'Tatsächliche Nenndicke der eingebauten PE-Bahn in mm laut Leistungserklärung bzw. Lieferschein (Tab. 24 Zeile 2: „Dicke nominal“, Prüfnorm DIN EN 1849-2). Die Dicke ergibt sich aus dem Anwendungsfall; projektspezifisch ist zu prüfen, welchen mechanischen und chemischen Beanspruchungen die Bahn ausgesetzt ist, Abdichtungen aus PE werden i. d. R. einlagig ausgeführt (§6.4.1.2). Tor REQ-33 (Hinweis) vergleicht mit der empfohlenen Dicke aus Tab. 25.
[EN] Actual nominal thickness of the installed PE liner in mm per declaration of performance or delivery note (Tab. 24 row 2 ''nominal thickness'', test standard DIN EN 1849-2). The thickness follows the application; the mechanical and chemical stresses on the liner must be checked per project, and PE sealings are normally single-layer (§6.4.1.2). Gate REQ-33 (warning) compares it with the recommended thickness from Tab. 25.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'pe_nenndicke_mm';
UPDATE fields x SET description = 'Rußverteilung der PEHD-Bahn als Kategorie nach ASTM D 5596, aus Leistungserklärung bzw. Datenblatt. Tab. 24 Zeile 6 fordert Kategorie 2–3. Nur bei PEHD sichtbar.
[EN] Carbon black dispersion of the PEHD liner as a category per ASTM D 5596, from the declaration of performance or data sheet. Tab. 24 row 6 requires category 2–3. Visible for PEHD only.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'peeh_russverteilung_kat';
UPDATE fields x SET description = 'Maßänderung der PEHD-Bahn nach 1 h bei 100 °C in % nach DIN EN 1107-2, aus Leistungserklärung bzw. Datenblatt. Tab. 24 Zeile 7 fordert ≤ 2 %. Nur bei PEHD sichtbar.
[EN] Dimensional change of the PEHD liner after 1 h at 100 °C in % per DIN EN 1107-2, from the declaration of performance or data sheet. Tab. 24 row 7 requires ≤ 2 %. Visible for PEHD only.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'peeh_massaenderung_pct';
UPDATE fields x SET description = 'Spannungsrissbeständigkeit der PEHD-Bahn im NCTL-Test (stress crack resistance) in h nach ASTM D 5397 app., aus Leistungserklärung bzw. Datenblatt. Tab. 24 Zeile 8 fordert > 500 h. Nur bei PEHD sichtbar.
[EN] Stress crack resistance of the PEHD liner in the NCTL test in h per ASTM D 5397 app., from the declaration of performance or data sheet. Tab. 24 row 8 requires > 500 h. Visible for PEHD only.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'peeh_nctl_h';
UPDATE fields x SET description = 'Stabilisierungsgrad der PEHD-Bahn im OIT-Test in min bei 200 °C nach DIN EN ISO 11357-6, aus Leistungserklärung bzw. Datenblatt. Tab. 24 Zeile 9 fordert > 100 min bei 200 °C. Nur bei PEHD sichtbar.
[EN] Degree of stabilisation of the PEHD liner in the OIT test in min at 200 °C per DIN EN ISO 11357-6, from the declaration of performance or data sheet. Tab. 24 row 9 requires > 100 min at 200 °C. Visible for PEHD only.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'peeh_oit_min';
UPDATE fields x SET description = 'Bestätigung, dass die Umweltverträglichkeit der PEHD-Bahn gemäß BBodSchVO als unbedenklich nachgewiesen ist (Herstellererklärung bzw. Prüfbericht). Tab. 24 Zeile 10 nennt als Anforderung „unbedenklich“ ohne Prüfwert und Testnorm. Nur bei PEHD sichtbar.
[EN] Attest that the environmental compatibility of the PEHD liner per BBodSchVO is proven as harmless (manufacturer''s declaration or test report). Tab. 24 row 10 states the requirement ''harmless'' without a test value or test standard. Visible for PEHD only.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'peeh_bbodschv_unbedenklich';
UPDATE fields x SET description = 'Bestätigung aus dem Verlegeplan: Bei Böschungen ab Neigungen von 1:10 und Längen über 3 m sollten Kunststoffbahnen aus PEHD mit strukturierter Oberfläche in Böschungsfallrichtung verlegt werden (§6.4.2); strukturierte Bahnen brauchen eine dauerhafte Prägung oder Beschichtung, die sich nicht ablösen darf (§6.4.1.1). Tor REQ-34 (Hinweis) verlangt den Haken, wenn die steilste Böschung (FLL-GAR-07) 1:10 oder steiler ist.
[EN] Attest from the laying plan: on slopes from 1:10 and lengths over 3 m, PEHD liners with a textured surface should be laid in the direction of the slope (§6.4.2); textured liners need a durable embossing or coating that must not detach later (§6.4.1.1). Gate REQ-34 (warning) requires the tick when the steepest slope (FLL-GAR-07) is 1:10 or steeper.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'pe_boeschung_strukturiert';
UPDATE fields x SET description = 'Bestätigung aus dem Verlegeplan, dass keine Querüberlappungen in Böschungsfallrichtung angeordnet sind: „Querüberlappungen in Böschungsfallrichtung sind zu vermeiden“ (§6.4.2). Eingang in Tor REQ-34 (Hinweis).
[EN] Attest from the laying plan that no transverse overlaps are arranged in the direction of the slope: ''transverse overlaps in the slope direction are to be avoided'' (§6.4.2). Input to gate REQ-34 (warning).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'pe_querueberlappung_vermieden';
UPDATE fields x SET description = 'Dokumentation der Planungsentscheidung: Bei Neigungen von 1:3,5 oder steiler sind ggf. verdeckte Bermen vorzusehen (§6.4.2). Kein Tor; die Entscheidung ist mit der Böschungsneigung aus FLL-GAR-07 zu begründen.
[EN] Documentation of the design decision: at slopes of 1:3.5 or steeper, concealed berms are to be provided where appropriate (§6.4.2). No gate; justify the decision with the slope from FLL-GAR-07.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'pe_bermen_vorgesehen';
UPDATE fields x SET description = 'Bestätigung, dass die relevanten Kontaktreibungswinkel (Bahn/Boden, Bahn/Schutzlage) durch Scherversuche ermittelt wurden — Prüfbericht des Labors beilegen. „In allen Fällen sollten die relevanten Kontaktreibungswinkel durch Scherversuche ermittelt werden“ (§6.4.2). Eingang in Tor REQ-34 (Hinweis).
[EN] Attest that the relevant interface friction angles (liner/soil, liner/protection layer) were determined by shear tests — attach the laboratory report. ''In all cases the relevant interface friction angles should be determined by shear tests'' (§6.4.2). Input to gate REQ-34 (warning).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'pe_scherversuch_durchgefuehrt';
UPDATE fields x SET description = 'Bestätigung aus dem Schweißprotokoll, dass vor der Verschweißung Probeschweißungen unter Baustellenbedingungen durchgeführt wurden, um Schweißgeräte und Nahtqualität zu beurteilen: „Vor der Verschweißung sind Probeschweißungen durchzuführen“ (§6.4.2.1). Tor REQ-35 sperrt ohne Haken.
[EN] Attest from the welding record that trial welds were carried out under site conditions before welding, to assess the welding equipment and seam quality: ''trial welds are to be carried out before welding'' (§6.4.2.1). Gate REQ-35 blocks until ticked.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'pe_probeschweissung_durchgefuehrt';
UPDATE fields x SET description = 'Länge der Probeschweißung in m aus dem Schweißprotokoll. Die Probeschweißungen sind idealerweise 1,0 m lang (§6.4.2.1). Dokumentation, kein Tor.
[EN] Length of the trial weld in m from the welding record. Trial welds are ideally 1.0 m long (§6.4.2.1). Documentation, no gate.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'pe_probeschweissung_laenge_m';
UPDATE fields x SET description = 'Breite der Probeschweißung in cm aus dem Schweißprotokoll. Die Probeschweißungen sind idealerweise 30 cm breit mit mittiger Schweißnaht (§6.4.2.1). Dokumentation, kein Tor.
[EN] Width of the trial weld in cm from the welding record. Trial welds are ideally 30 cm wide with a centred seam (§6.4.2.1). Documentation, no gate.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'pe_probeschweissung_breite_cm';
UPDATE fields x SET description = 'Verfahren der zerstörungsfreien Nahtprüfung laut Prüfprotokoll. Die Richtlinie nennt beispielhaft die Druckluftprüfung für Doppelnähte und die Vakuumprüfung für Extrusionsschweißnähte („eignen sich z. B.“); ein anderes geeignetes Verfahren ist unter „sonstiges“ zu benennen (§6.4.2.1).
[EN] Non-destructive seam test method per the test record. The guideline names, as examples, the air-pressure test for double seams and the vacuum test for extrusion welds (''suitable are e.g.''); another suitable method is to be named under ''other'' (§6.4.2.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'pe_nahtpruefung_verfahren';
UPDATE fields x SET description = 'Bestätigung, dass alle Nähte zerstörungsfrei über die gesamte Nahtlänge geprüft und die Prüfergebnisse protokolliert wurden — Prüfprotokoll beilegen. „Die Prüfergebnisse sind zu protokollieren“ (§6.4.2.1). Tor REQ-35 sperrt ohne Haken.
[EN] Attest that all seams were tested non-destructively over their full length and the test results recorded — attach the test record. ''The test results are to be recorded'' (§6.4.2.1). Gate REQ-35 blocks until ticked.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'pe_nahtpruefung_protokoll';
UPDATE fields x SET description = 'Breite von Arbeitsfugen oder Rissen des abzudichtenden Bauwerks zum Zeitpunkt ihrer Entstehung in mm, aus dem Tragwerksnachweis bzw. der Bauwerksaufnahme; nur bei Bauwerksabdichtung. Sie dürfen nicht breiter als 0,5 mm sein; PEHD-Bahnen müssen solche Risse überbrücken können (§6.4.2.2). Tor REQ-37 prüft ≤ 0,5 mm, sofern Neurissbildung (FLL-GAR-05) nicht ausgeschlossen ist.
[EN] Width of construction joints or cracks in the structure to be sealed at the time they form, in mm, from the structural verification or building survey; only for structure sealing. They must not be wider than 0.5 mm; PEHD liners must be able to bridge such cracks (§6.4.2.2). Gate REQ-37 checks ≤ 0.5 mm unless new cracking (FLL-GAR-05) is excluded.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'pe_riss_entstehung_mm';
UPDATE fields x SET description = 'Erwartete Aufweitung des Risses durch weitere Bewegung in mm aus dem Tragwerksnachweis. Zulässig ist eine Aufweitung auf höchstens 2,0 mm (§6.4.2.2). Tor REQ-37 prüft ≤ 2,0 mm, sofern Neurissbildung nicht ausgeschlossen ist.
[EN] Expected widening of the crack by further movement in mm from the structural verification. A widening to at most 2.0 mm is permissible (§6.4.2.2). Gate REQ-37 checks ≤ 2.0 mm unless new cracking is excluded.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'pe_riss_aufweitung_mm';
UPDATE fields x SET description = 'Erwarteter Versatz der Risskanten in mm aus dem Tragwerksnachweis. Zulässig ist ein Versatz der Risskanten auf höchstens 1,0 mm (§6.4.2.2). Tor REQ-37 prüft ≤ 1,0 mm, sofern Neurissbildung nicht ausgeschlossen ist.
[EN] Expected offset of the crack edges in mm from the structural verification. An offset of the crack edges of at most 1.0 mm is permissible (§6.4.2.2). Gate REQ-37 checks ≤ 1.0 mm unless new cracking is excluded.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.symbol = 'pe_riss_versatz_mm';
UPDATE equations x SET description = 'Leitet aus dem Werkstoff der Bahn ab, ob ein Nachweis der Wurzel-/Rhizomfestigkeit gemäß FLL zu erbringen ist: pe_rhizom_nachweis_code = 1 bei PELD (Nachweis vom Hersteller zu erbringen), 0 bei PEHD (ausreichende Widerstandsfähigkeit gegenüber Wurzeln und Rhizomen, Prüfung kann entfallen). Keine Formel im Druck; Umsetzung der beiden Sätze in §6.4.1.1.
[EN] Derives from the liner material whether proof of root/rhizome resistance per FLL is required: pe_rhizom_nachweis_code = 1 for PELD (proof to be provided by the manufacturer), 0 for PEHD (sufficient resistance to roots and rhizomes, the test may be omitted). No printed formula; implements the two sentences of §6.4.1.1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.equation_number = 'FLL-GAR-18-D1';
UPDATE equations x SET description = 'Prüft die drei Tab.-24-Werte der PEHD-Bahn gemeinsam: pehd_tab24_code = 1, wenn Dichte > 0,940 g/cm³ (Zeile 3), MFR zwischen 1,0 und 3,0 g/10 min (Zeile 4) und Rußgehalt zwischen 2 und 3 % (Zeile 5) liegen; sonst 0. Eingänge: peeh_dichte_g_cm3, peeh_mfr, peeh_russgehalt_pct aus der Leistungserklärung. Die Grenzen werden aus Tab. 24 gelesen.
[EN] Checks the three Tab. 24 values of the PEHD liner together: pehd_tab24_code = 1 when density > 0.940 g/cm³ (row 3), MFR between 1.0 and 3.0 g/10 min (row 4) and carbon black content between 2 and 3 % (row 5); otherwise 0. Inputs: peeh_dichte_g_cm3, peeh_mfr, peeh_russgehalt_pct from the declaration of performance. The limits are read from Tab. 24.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.equation_number = 'FLL-GAR-18-D2';
UPDATE compliance_requirements x SET description = 'Gilt nur bei Abdichtungsart PE-Bahn. Hinweis (keine Sperre), wenn die Ist-Nenndicke unter der empfohlenen Dicke der Tab. 25 für den Werkstoff und die Beanspruchungsstufe liegt: PELD gering ≥ 0,8 mm, PELD mittel ≥ 1,5 mm, PEHD mittel ≥ 1,0 mm, PEHD hoch ≥ 2,0 mm, PEHD freiliegend ≥ 2,5 mm. Einzutragen: Werkstoff, Beanspruchungsstufe, Nenndicke der Bahn. Grund: Tab. 25 gibt „geeignete“ bzw. „empfohlene“ Dicken, die Einstufung obliegt dem Objektplanenden (§6.4.1.2) — daher Hinweis statt Sperre.
[EN] Applies only for the PE liner sealing type. Warning (no block) when the actual nominal thickness is below the recommended thickness of Tab. 25 for the material and loading class: PELD low ≥ 0.8 mm, PELD medium ≥ 1.5 mm, PEHD medium ≥ 1.0 mm, PEHD high ≥ 2.0 mm, PEHD exposed ≥ 2.5 mm. Enter: material, loading class, nominal thickness of the liner. Reason: Tab. 25 gives ''suitable'' / ''recommended'' thicknesses and the classification is the designer''s responsibility (§6.4.1.2) — hence a warning, not a block.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.code = 'REQ-33';
UPDATE compliance_requirements x SET description = 'Gilt nur bei Abdichtungsart PE-Bahn. Hinweis (keine Sperre), wenn eine der drei Verlegeregeln der Böschung nicht bestätigt ist: Querüberlappungen in Böschungsfallrichtung vermieden, Kontaktreibungswinkel durch Scherversuche ermittelt, und — sobald die steilste Böschung aus FLL-GAR-07 1:10 oder steiler ist — strukturierte PEHD-Bahn in Böschungsfallrichtung verlegt. Einzutragen: die drei Haken dieses Blatts; die Böschungsneigung kommt aus FLL-GAR-07. Grund: §6.4.2 formuliert „sollten“ (Verlegung ab 1:10 und Längen über 3 m, Scherversuche) und „sind zu vermeiden“ (Querüberlappungen).
[EN] Applies only for the PE liner sealing type. Warning (no block) when one of the three slope-laying rules is not confirmed: transverse overlaps in the slope direction avoided, interface friction angles determined by shear tests, and — once the steepest slope from FLL-GAR-07 is 1:10 or steeper — textured PEHD liner laid in the slope direction. Enter: the three ticks on this sheet; the slope comes from FLL-GAR-07. Reason: §6.4.2 uses ''should'' (laying from 1:10 and lengths over 3 m, shear tests) and ''are to be avoided'' (transverse overlaps).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.code = 'REQ-34';
UPDATE compliance_requirements x SET description = 'Gilt nur bei Abdichtungsart PE-Bahn. Bestanden, wenn beide Haken gesetzt sind: Probeschweißungen vor der Verschweißung unter Baustellenbedingungen durchgeführt und alle Nähte zerstörungsfrei über die gesamte Länge geprüft und protokolliert. Einzutragen: die beiden Bestätigungen mit Schweiß- und Prüfprotokoll als Beleg. Grund: „Vor der Verschweißung sind Probeschweißungen durchzuführen“ und „Die Prüfergebnisse sind zu protokollieren“ (§6.4.2.1) — Muss-Vorgaben, daher Sperre.
[EN] Applies only for the PE liner sealing type. Passes when both ticks are set: trial welds carried out under site conditions before welding, and all seams tested non-destructively over their full length and recorded. Enter: the two attestations, with the welding and test records as evidence. Reason: ''trial welds are to be carried out before welding'' and ''the test results are to be recorded'' (§6.4.2.1) — mandatory wording, hence a block.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.code = 'REQ-35';
UPDATE compliance_requirements x SET description = 'Gilt nur bei Abdichtungsart PE-Bahn. Hinweis (keine Sperre), wenn die Nahtüberlappung nicht zwischen 100 und 150 mm liegt. Einzutragen: Nahtüberlappung aus Schweißprotokoll bzw. Herstellerverlegeanleitung. Grund: „Die Nahtüberlappung sollte je nach verwendetem Schweißautomaten zwischen 100 und 150 mm betragen“ (§6.4.2.1) — Soll-Vorgabe.
[EN] Applies only for the PE liner sealing type. Warning (no block) when the seam overlap is not between 100 and 150 mm. Enter: seam overlap from the welding record or the manufacturer''s laying instructions. Reason: ''the seam overlap should be between 100 and 150 mm depending on the welding machine used'' (§6.4.2.1) — ''should'' wording.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.code = 'REQ-36';
UPDATE compliance_requirements x SET description = 'Gilt nur bei Abdichtungsart PE-Bahn und nur, wenn Neurissbildung des Bauwerks (FLL-GAR-05) nicht ausgeschlossen ist — ein Erdbecken ohne Bauwerk lässt die drei Felder leer und wird nicht gesperrt. Bestanden, wenn Rissbreite bei Entstehung ≤ 0,5 mm, Aufweitung ≤ 2,0 mm und Versatz der Risskanten ≤ 1,0 mm. Einzutragen: die drei Risswerte aus dem Tragwerksnachweis. Grund: Risse „dürfen … nicht breiter als 0,5 mm sein“, Aufweitung und Versatz „höchstens“ 2,0 bzw. 1,0 mm; PEHD-Bahnen müssen diese Risse überbrücken können (§6.4.2.2).
[EN] Applies only for the PE liner sealing type and only when new cracking of the structure (FLL-GAR-05) is not excluded — an earth basin without a structure leaves the three fields empty and is not blocked. Passes when crack width at formation ≤ 0.5 mm, widening ≤ 2.0 mm and crack-edge offset ≤ 1.0 mm. Enter: the three crack values from the structural verification. Reason: cracks ''must not be wider than 0.5 mm'', widening and offset ''at most'' 2.0 and 1.0 mm; PEHD liners must be able to bridge these cracks (§6.4.2.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.code = 'REQ-37';
UPDATE compliance_requirements x SET description = 'Gilt nur bei PE-Bahnen aus PEHD und sitzt auf Blatt FLL-GAR-18: dort Werkstoff PEHD wählen und die Tab.-24-Kennwerte eintragen. Besteht, wenn alle Tab.-24-Werte aus dem Herstellerdatenblatt eingehalten sind: Dichte > 0,940 g/cm³, Schmelze-Massefließrate MFR ≥ 1,0 und ≤ 3,0 g/10 min, Rußgehalt 2–3 %, Rußverteilung Kategorie 2–3, Maßänderung (1 h / 100 °C) ≤ 2 %, NCTL-Test > 500 h, OIT-Test > 100 min bei 200 °C, Umweltverträglichkeit gemäß BBodSchV unbedenklich. Ein Wert genau auf der Grenze (z. B. OIT = 100) besteht nicht. PELD-Bahnen brauchen stattdessen den Nachweis der Wurzel-/Rhizomfestigkeit nach FLL (§6.4.1.1).
[EN] Applies only to PE sheets made of PEHD and sits on sheet FLL-GAR-18: select material PEHD there and enter the Tab. 24 values. Passes when every Tab. 24 value from the manufacturer''s data sheet is met: density > 0.940 g/cm³, melt mass-flow rate MFR ≥ 1.0 and ≤ 3.0 g/10 min, carbon-black content 2–3 %, carbon-black dispersion category 2–3, dimensional change (1 h / 100 °C) ≤ 2 %, NCTL test > 500 h, OIT test > 100 min at 200 °C, environmental compatibility per BBodSchV ''unbedenklich''. A value exactly on the limit (e.g. OIT = 100) does not pass. PELD sheets instead need the FLL root/rhizome-resistance proof (§6.4.1.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-18' AND x.code = 'REQ-20';
UPDATE fields x SET description = 'Stahlsorte laut Werkstoffzeugnis des Herstellers. Bevorzugt ist nichtrostender Stahl V2A (1.4301, beständig gegen Trinkwasser); bei höheren Korrosionsanforderungen (Meeresnähe, Industrieatmosphäre) V4A (1.4401); bei Meerwasser oder Solebecken z. B. V5A (1.4539). Wetterfeste Baustähle: 1.8946 (COR-TEN A) bis 12,5 mm, 1.8965 (COR-TEN B) für dickere Bleche; sie bilden nach ca. 3 Jahren eine Sperrschicht, ständiger Wasserkontakt kann sie beeinträchtigen. Unlegierte Stähle müssen verzinkt und ggf. beschichtet werden (§7.1.1.1). Blechdicke: rostfrei mind. 1 mm, COR-TEN und verzinkt/beschichtet mind. 5 mm (§7.1.1.2).
[EN] Steel grade per the manufacturer''s material certificate. Preferred is stainless steel V2A (1.4301, resistant to drinking water); for higher corrosion demands (near the sea, industrial atmosphere) V4A (1.4401); for seawater or brine pools e.g. V5A (1.4539). Weathering steels: 1.8946 (COR-TEN A) up to 12.5 mm, 1.8965 (COR-TEN B) for thicker plate; they form a barrier layer after about 3 years, constant water contact may impair it. Unalloyed steels must be galvanised and coated if needed (§7.1.1.1). Plate thickness: stainless at least 1 mm, COR-TEN and galvanised/coated at least 5 mm (§7.1.1.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-19' AND x.symbol = 'stahl_typ';
UPDATE fields x SET description = 'Zinkschichtdicke in µm aus dem Verzinkungsnachweis (Schichtdickenmessung), nur bei unlegiertem Stahl. Durch Schmelztauchen (Feuerverzinken) soll eine Schichtstärke von wenigstens 100 µm erreicht werden; zusätzlicher Schutz durch Beschichtung nach der Verzinkung mit mindestens einem Vor- und einem Deckanstrich, empfohlen zwei Voranstriche und drei Deckanstriche für wenigstens 320 µm Beschichtungsstärke (§7.1.1.1). Beim Verschweißen verzinkter Bauteile ist die Naht mit Zinkstaubbeschichtung nachzuverzinken (§7.1.2).
[EN] Zinc coating thickness in µm from the galvanising certificate (coating thickness measurement), unalloyed steel only. Hot-dip galvanising should reach a coating thickness of at least 100 µm; additional protection by a coating after galvanising with at least one primer and one top coat, recommended two primers and three top coats for at least 320 µm coating thickness (§7.1.1.1). When welding galvanised parts the seam must be re-galvanised with zinc-dust coating (§7.1.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-19' AND x.symbol = 'verzinkung_dicke_um';
UPDATE fields x SET description = 'Bestätigung nur für Abdichtungen aus Stahl: Der Werkstoff ist nach Korrosionsbelastung gewählt – bevorzugt V2A (1.4301), bei Meeresnähe/Industrieatmosphäre V4A (1.4401), bei Meerwasser/Solebecken z. B. V5A (1.4539), oder wetterfester Baustahl (COR-TEN A 1.8946 bis 12,5 mm, COR-TEN B 1.8965 darüber); unlegierter Stahl ist feuerverzinkt mit wenigstens 100 µm und ggf. beschichtet (§7.1.1.1). Der Anlieferungszustand wurde optisch geprüft und die Stahlqualität liegt als Herstellernachweis vor (§7.1.3.2). Tor REQ-21 blockiert ohne Haken; ohne Stahlabdichtung im Vorhaben ist das Feld gegenstandslos.
[EN] Attestation that applies only to steel sealings: the grade is chosen for the corrosion exposure – preferably V2A (1.4301), V4A (1.4401) near the sea or in industrial atmosphere, e.g. V5A (1.4539) for sea water or brine pools, or weathering steel (COR-TEN A 1.8946 up to 12.5 mm, COR-TEN B 1.8965 above); unalloyed steel is hot-dip galvanised with at least 100 µm and coated where required (§7.1.1.1). The delivered elements were checked visually and the steel quality is proven by the manufacturer (§7.1.3.2). Gate REQ-21 blocks until ticked; without a steel sealing in the project the field has no object.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-19' AND x.symbol = 'attest_fll_gar_10_req_21';
UPDATE compliance_requirements x SET description = 'Besteht, wenn die Bestätigung zur Stahlwerkstoffwahl gesetzt ist. Was dafür wahr sein muss: Der Stahl ist nach Korrosionsbelastung gewählt (V2A 1.4301 bevorzugt; V4A 1.4401 bei Meeresnähe/Industrieatmosphäre; z. B. V5A 1.4539 bei Meerwasser/Sole; COR-TEN A 1.8946 bis 12,5 mm bzw. COR-TEN B 1.8965 darüber), unlegierter Stahl ist feuerverzinkt mit wenigstens 100 µm und ggf. beschichtet (§7.1.1.1); der Anlieferungszustand wurde optisch geprüft und der Herstellernachweis der Stahlqualität liegt vor (§7.1.3.2). Sitzt auf Blatt FLL-GAR-19 (Stahl) und wird nur bei Abdichtungsart Stahl (Wahl in FLL-GAR-09) ausgewertet; dort den Haken setzen.
[EN] Passes when the steel material attestation is ticked. What must be true: the steel is chosen for the corrosion exposure (V2A 1.4301 preferred; V4A 1.4401 near the sea/industrial atmosphere; e.g. V5A 1.4539 for sea water/brine; COR-TEN A 1.8946 up to 12.5 mm or COR-TEN B 1.8965 above), unalloyed steel is hot-dip galvanised with at least 100 µm and coated where required (§7.1.1.1); the delivered elements were checked visually and the manufacturer''s proof of steel quality is on file (§7.1.3.2). Sits on sheet FLL-GAR-19 (steel) and is evaluated only for the sealing type steel (chosen in FLL-GAR-09); tick the box there.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-19' AND x.code = 'REQ-21';
UPDATE fields x SET description = 'Art des Wasserglases laut Hersteller-Datenblatt: Natrium-, Lithium- oder Kalium-Wasserglas, das in Pulverform bindigen Böden beigemischt wird und mit Tonmineralien, Kalkstein und Metallionen wasserunlösliche Gele bildet. Natrium- und Lithium-Wasserglas sind phytotoxisch, Kalium-Wasserglas ist pflanzenverträglich (§7.2) — bei bepflanzter Teichsohle entsprechend wählen.
[EN] Type of water glass per the manufacturer''s data sheet: sodium, lithium or potassium water glass, mixed as a powder into cohesive soils, forming water-insoluble gels with clay minerals, limestone and metal ions. Sodium and lithium water glass are phytotoxic, potassium water glass is plant-compatible (§7.2) — choose accordingly for a planted pond bed.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-20' AND x.symbol = 'alkalisilikat_type';
UPDATE fields x SET description = 'Feinkornanteil < 0,063 mm des anstehenden Bodens in Masse-% aus der Korngrößenanalyse des Bodenlabors. Er soll mind. 20 Masse-% betragen; die Prüfungen nach Abschnitt 5.1.1 gelten, abweichend ist jedoch der Kornanteil < 0,063 mm statt < 0,002 mm zu bestimmen (§7.2.1.1). Tor REQ-22 (Hinweis) prüft ≥ 20 %.
[EN] Fines fraction < 0.063 mm of the in-situ soil in mass % from the soil laboratory''s grain-size analysis. It should be at least 20 mass %; the tests of section 5.1.1 apply, but deviating from them the fraction < 0.063 mm is to be determined instead of < 0.002 mm (§7.2.1.1). Gate REQ-22 (warning) checks ≥ 20 %.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-20' AND x.symbol = 'feinkornanteil_063_pct';
UPDATE fields x SET description = 'Dicke der vergüteten Dichtungsschicht in cm aus dem Einbauplan bzw. der Schichtdickenaufnahme. „Die Dicke der vergüteten Dichtungsschicht soll mind. 25 cm betragen“ (§7.2.1.2); je nach Anforderung ein- oder mehrlagig eingebaut (§7.2.2.1). Tor REQ-22 (Hinweis) prüft ≥ 25 cm.
[EN] Thickness of the treated sealing layer in cm from the installation plan or thickness survey. ''The thickness of the treated sealing layer should be at least 25 cm'' (§7.2.1.2); installed in one or more layers as required (§7.2.2.1). Gate REQ-22 (warning) checks ≥ 25 cm.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-20' AND x.symbol = 'as_schichtdicke_cm';
UPDATE fields x SET description = 'Tiefe in cm, bis zu der die abzudichtende Bodenschicht zur Homogenisierung durchmischt wird (z. B. Auffräsen), aus dem Einbauplan. „Die Lockerungstiefe soll mind. 25 cm betragen“ (§7.2.2.1). Tor REQ-22 (Hinweis) prüft ≥ 25 cm.
[EN] Depth in cm to which the soil layer to be sealed is mixed for homogenisation (e.g. by rotary milling), from the installation plan. ''The loosening depth should be at least 25 cm'' (§7.2.2.1). Gate REQ-22 (warning) checks ≥ 25 cm.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-20' AND x.symbol = 'as_lockerungstiefe_cm';
UPDATE fields x SET description = 'Verdichtungsgrad DPr der eingebauten Dichtungsschicht in % aus der Kontrollprüfung nach DIN 18125-2. „Die Lagerungsdichte DPr beträgt ≥ 97 %“ (§7.2.2.1); Tab. 3 Zeile 6 fordert für die Anforderungen nach Abschnitt 5.1.1 ebenfalls ≥ 97 %. Die Dichtungsschicht ist dynamisch und statisch zu verdichten. Tor REQ-38 sperrt unter 97 %.
[EN] Degree of compaction DPr of the installed sealing layer in % from the control test per DIN 18125-2. ''The density index DPr is ≥ 97 %'' (§7.2.2.1); Tab. 3 row 6 likewise requires ≥ 97 % for the section 5.1.1 requirements. The sealing layer must be compacted dynamically and statically. Gate REQ-38 blocks below 97 %.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-20' AND x.symbol = 'as_dpr_pct';
UPDATE fields x SET description = 'Durchlässigkeitsbeiwert kf der vergüteten Dichtungsschicht in m/s aus dem Laborversuch nach DIN EN ISO 17892-11 bei hydraulischem Gradient i = 30. Die Anforderungen an die vergütete Schicht entsprechen Abschnitt 5.1.1 (§7.2.1.1), d. h. Tab. 3 Zeile 5: ≤ 1·10⁻⁹ m/s; mit Alkalisilikaten sind laut §7.2.1.1 kf < 1·10⁻⁹ bis 5·10⁻¹¹ m/s erzielbar. Tor REQ-38 sperrt über 1·10⁻⁹ m/s.
[EN] Permeability coefficient kf of the treated sealing layer in m/s from the laboratory test per DIN EN ISO 17892-11 at hydraulic gradient i = 30. The requirements for the treated layer match section 5.1.1 (§7.2.1.1), i.e. Tab. 3 row 5: ≤ 1·10⁻⁹ m/s; per §7.2.1.1 alkali silicates achieve kf < 1·10⁻⁹ to 5·10⁻¹¹ m/s. Gate REQ-38 blocks above 1·10⁻⁹ m/s.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-20' AND x.symbol = 'as_kf_m_s';
UPDATE fields x SET description = 'Organische Substanz (Glühverlust VGL) der vergüteten Dichtungsschicht in Masse-% aus dem Laborversuch nach DIN 18128. Über §7.2.1.1 gilt Tab. 3 Zeile 3: ≤ 5 Masse-%. Tor REQ-38 sperrt über 5 %.
[EN] Organic content (loss on ignition VGL) of the treated sealing layer in mass % from the laboratory test per DIN 18128. Via §7.2.1.1 Tab. 3 row 3 applies: ≤ 5 mass %. Gate REQ-38 blocks above 5 %.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-20' AND x.symbol = 'as_organische_substanz_VGL';
UPDATE fields x SET description = 'Kalkgehalt VCA der vergüteten Dichtungsschicht in Masse-% aus dem Laborversuch nach DIN 18129. Über §7.2.1.1 gilt Tab. 3 Zeile 4: ≤ 15 Masse-%. Tor REQ-38 sperrt über 15 %.
[EN] Lime content VCA of the treated sealing layer in mass % from the laboratory test per DIN 18129. Via §7.2.1.1 Tab. 3 row 4 applies: ≤ 15 mass %. Gate REQ-38 blocks above 15 %.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-20' AND x.symbol = 'as_kalkgehalt_VCA';
UPDATE compliance_requirements x SET description = 'Gilt nur bei Abdichtungsart Alkalisilikat. Hinweis (keine Sperre), wenn eine der drei Soll-Werte unterschritten ist: Dicke der vergüteten Dichtungsschicht ≥ 25 cm (§7.2.1.2), Feinkornanteil < 0,063 mm ≥ 20 Masse-% (§7.2.1.1), Lockerungstiefe ≥ 25 cm (§7.2.2.1). Einzutragen: die drei Werte aus Bodenanalyse und Einbauplan. Grund: alle drei sind als „soll mind.“ formuliert. Zusätzlich beachten: Natrium- und Lithium-Wasserglas sind phytotoxisch (§7.2).
[EN] Applies only for the alkali silicate sealing type. Warning (no block) when one of the three ''should'' values is undershot: thickness of the treated sealing layer ≥ 25 cm (§7.2.1.2), fines < 0.063 mm ≥ 20 mass % (§7.2.1.1), loosening depth ≥ 25 cm (§7.2.2.1). Enter: the three values from the soil analysis and installation plan. Reason: all three are worded ''should be at least''. Also note: sodium and lithium water glass are phytotoxic (§7.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-20' AND x.code = 'REQ-22';
UPDATE compliance_requirements x SET description = 'Gilt nur bei Abdichtungsart Alkalisilikat. Bestanden, wenn die vergütete Dichtungsschicht die Tab.-3-Werte einhält: DPr ≥ 97 %, kf ≤ 1·10⁻⁹ m/s (i = 30), organische Substanz VGL ≤ 5 Masse-%, Kalkgehalt VCA ≤ 15 Masse-%. Einzutragen: die vier Laborwerte (DIN 18125-2, DIN EN ISO 17892-11, DIN 18128, DIN 18129). Grund: „Die Anforderungen an die vergütete Dichtungsschicht entsprechen den Anforderungen gemäß Abschnitt 5.1.1“ (§7.2.1.1) und „Die Lagerungsdichte DPr beträgt ≥ 97 %“ (§7.2.2.1). Der Kornanteil wird abweichend als < 0,063 mm in REQ-22 geprüft.
[EN] Applies only for the alkali silicate sealing type. Passes when the treated sealing layer meets the Tab. 3 values: DPr ≥ 97 %, kf ≤ 1·10⁻⁹ m/s (i = 30), organic content VGL ≤ 5 mass %, lime content VCA ≤ 15 mass %. Enter: the four laboratory values (DIN 18125-2, DIN EN ISO 17892-11, DIN 18128, DIN 18129). Reason: ''the requirements for the treated sealing layer match the requirements of section 5.1.1'' (§7.2.1.1) and ''the density index DPr is ≥ 97 %'' (§7.2.2.1). The grain fraction is checked, deviating, as < 0.063 mm in REQ-22.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-20' AND x.code = 'REQ-38';
UPDATE fields x SET description = 'Reaktionsharz laut Hersteller-Datenblatt. Die Richtlinie verlangt ungesättigte Polyesterharze nach DIN 16946 Teil 2 (§7.3.1.1); Laminierharze auf Isophthalsäure-Basis werden zur Verbesserung der Wasserbeständigkeit kobalt-vorbeschleunigt, dem Harz werden je nach Umgebung 2 % bis 4 % Härter beigemischt (§7.3.2.2). Ein anderer Harztyp ist mit Hersteller-Nachweis zu begründen.
[EN] Reaction resin per the manufacturer''s data sheet. The guideline requires unsaturated polyester resins per DIN 16946 Part 2 (§7.3.1.1); isophthalic-acid-based laminating resins are cobalt pre-accelerated to improve water resistance, and 2 % to 4 % hardener is added depending on ambient conditions (§7.3.2.2). Any other resin type needs justification with manufacturer evidence.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-21' AND x.symbol = 'gup_harztyp';
UPDATE fields x SET description = 'Glasgehalt des Laminats in % aus Hersteller-Datenblatt bzw. Laborprüfung einer Rückstellprobe. Unabhängig vom Einbauverfahren soll ein Glasgehalt von 30 % des Laminats angestrebt werden, um die Festigkeitswerte nach DIN 18820 zu erreichen; Verstärkungsfasern sind Glasfasergewebe nach DIN 61850 mit Haftvermittler (§7.3.1.1), bevorzugt pulvergebundene Matten mit 450 bis 600 g/m² (§7.3.2.2). Der Auftraggeber kann Laborprüfungen auf Glasgehalt veranlassen (§7.3.3.3).
[EN] Glass content of the laminate in % from the manufacturer''s data sheet or a laboratory test on a retained sample. Regardless of the installation method a glass content of 30 % of the laminate should be aimed for to reach the strength values per DIN 18820; reinforcing fibres are glass fibre fabrics per DIN 61850 with coupling agents (§7.3.1.1), preferably powder-bound mats of 450 to 600 g/m² (§7.3.2.2). The client may commission laboratory tests on glass content (§7.3.3.3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-21' AND x.symbol = 'gup_glasfaser_anteil';
UPDATE fields x SET description = 'Wanddicke bzw. Laminatdicke der Beschichtung in mm aus der Schichtdickenmessung oder dem Fertigelement-Datenblatt. „Die Wanddicke bzw. die Laminatdicke der Beschichtung soll mind. 4 mm betragen“ (§7.3.1.2); die Matten werden i. d. R. mehrlagig verlegt, um die mind. 4 mm zu erreichen; das Schlusslackharz von ca. 0,5 mm kommt zusätzlich darauf (§7.3.2.2).
[EN] Wall or laminate thickness of the coating in mm from the thickness measurement or the prefabricated element''s data sheet. ''The wall thickness or laminate thickness of the coating should be at least 4 mm'' (§7.3.1.2); the mats are usually laid in several layers to reach the at least 4 mm; the topcoat resin of about 0.5 mm goes on top (§7.3.2.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-21' AND x.symbol = 'gup_laminatdicke';
UPDATE fields x SET description = 'Biegefestigkeit des Laminats in N/mm² aus dem Hersteller-Datenblatt oder einer Laborprüfung. Die Richtlinie nennt keinen Zahlenwert; sie verweist auf „die notwendigen Festigkeitswerte gemäß DIN 18820“, die mit dem angestrebten Glasgehalt von 30 % erreicht werden sollen (§7.3.1.1). Vergleichswert ist die Angabe nach DIN 18820 bzw. des Herstellers.
[EN] Flexural strength of the laminate in N/mm² from the manufacturer''s data sheet or a laboratory test. The guideline prints no number; it refers to ''the necessary strength values per DIN 18820'', to be reached with the targeted glass content of 30 % (§7.3.1.1). Reference value is the figure per DIN 18820 or the manufacturer''s.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-21' AND x.symbol = 'gup_biegefestigkeit';
UPDATE fields x SET description = 'Einbauverfahren laut Ausführungsplanung: industriell hergestellte Fertigelemente oder vor Ort als Beschichtung aufgetragen (§7.3.2). Bei der Beschichtung werden Matten stückweise (ca. 70 × 70 cm) hohlraumfrei mit mind. 50 mm Überlappung getränkt (Handlaminat) oder der Glasfaserauftrag erfolgt mittels Faserspritzen (Glasroving); unter 5 °C Bodentemperatur darf nicht laminiert werden, in der Laminier- und Gelierphase ist vor Regen zu schützen (§7.3.2.2).
[EN] Installation method per the execution design: industrially prefabricated elements or applied on site as a coating (§7.3.2). For the coating, mats are impregnated piece by piece (about 70 × 70 cm) void-free with at least 50 mm overlap (hand lay-up), or the glass fibre is applied by fibre spraying (glass roving); no laminating below 5 °C soil temperature, and protection from rain during the laminating and gelling phase (§7.3.2.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-21' AND x.symbol = 'gup_verarbeitung';
UPDATE fields x SET description = 'Bestätigung, dass nach Aushärtung und Beischleifen ein Schlusslackharz zur Oberflächenversiegelung aufgebracht wurde: „in entsprechender Farbe mit ca. 0,5 mm Schichtdicke“; ein anschließendes Tempern bei ca. 60 °C über acht Stunden erhöht die Festigkeit und reduziert den Rest-Styrolgehalt (§7.3.2.2). Bei Fertigelementen gemäß Hersteller-Datenblatt.
[EN] Attest that, after curing and grinding, a topcoat resin was applied to seal the surface: ''in the corresponding colour with about 0.5 mm thickness''; subsequent tempering at about 60 °C for eight hours increases strength and reduces residual styrene (§7.3.2.2). For prefabricated elements per the manufacturer''s data sheet.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-21' AND x.symbol = 'gup_topcoat';
UPDATE fields x SET description = 'Bestätigung, dass die geplante und vorhandene Bepflanzung gegen die Beispielliste wurzel-/rhizomaggressiver Arten (Tab. 29, z. B. Phragmites australis, Typha, Bambus) geprüft ist und die Wurzel-/Rhizomprüfung nach § 10.4 vorliegt, soweit erforderlich: Mindestnachweis FLL-Testat „rhizomfest gegen Quecken“; bei intensiver Beanspruchung (Pflanzenkläranlagen, Aufbereitungsbereiche von Schwimmteichen) die Prüfung nach den Technischen Prüfbestimmungen zur Rhizomfestigkeit von Gewässerabdichtungen; Stahl, Beton, PEHD ohne gesonderten Nachweis. Sperrtor REQ-25.
[EN] Confirmation that planned and existing planting has been screened against the example list of root-/rhizome-aggressive species (Tab. 29, e.g. Phragmites australis, Typha, bamboo) and that the root/rhizome test per § 10.4 is available where needed: minimum proof FLL certificate ''rhizome-proof against couch grass''; with intensive planting (constructed wetlands, treatment zones of swimming ponds) the test per the FLL technical test specifications for rhizome resistance of water-body sealings; steel, concrete, PEHD need no separate proof. Blocking gate REQ-25.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'attest_fll_gar_22_req_25';
UPDATE fields x SET description = 'Werkstoff der Schutzlage oberhalb der Abdichtung in Worten (Datenblatt). Bei statischer Beanspruchung dieselben Werkstoffe wie unterhalb (Tab. 26); bei dynamischer Beanspruchung (Begehen, Befahren) nach Schutzwirksamkeitsklasse gemäß DIN EN 13719 – Tab. 27 nennt Vliesstoff/Geotextil ≥ 300/500/800 g GRK 5 (§ 8.3.2). Geeignete Werkstoffe nach § 8.2 z. B. PVC-Schutzbahn ≥ 1 mm, Bautenschutzmatten ≥ 6 mm, Vliesstoffe ≥ 300 g/m² GRK 5, Beton ≥ 50 mm, Gussasphalt ≥ 25 mm. Bei Verzicht (z. B. Beckenboden Schwimmteich) Mehrdicke oder Mehrlagigkeit der Abdichtung (§ 8.3.2).
[EN] Material of the protection layer above the sealing in words (data sheet). Under static loading the same materials as below (Tab. 26); under dynamic loading (walking, driving) by protection-efficiency class per DIN EN 13719 – Tab. 27 names nonwoven/geotextile ≥ 300/500/800 g GRK 5 (§ 8.3.2). Suitable materials per § 8.2 e.g. PVC protection sheet ≥ 1 mm, protection mats ≥ 6 mm, nonwovens ≥ 300 g/m² GRK 5, concrete ≥ 50 mm, mastic asphalt ≥ 25 mm. If omitted (e.g. swimming-pond floor) extra thickness or multiple sealing layers (§ 8.3.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'sl_schutzlage_oben_typ';
UPDATE fields x SET description = 'Flächengewicht des Vliesstoffs/Geotextils der oberen Schutzlage in g/m² (Herstellerdatenblatt). Mindestanforderung nach Tab. 27 je Schutzwirksamkeitsklasse: SWK 1 ≥ 300 g, SWK 2 ≥ 500 g, SWK 3 ≥ 800 g, jeweils GRK 5; für statische Beanspruchung Vliesstoffe ≥ 300 g/m² GRK 5 (§ 8.2, Tab. 26). Tor REQ-24 vergleicht den Wert mit dem Tab.-27-Mindestwert, sobald eine SWK gewählt ist.
[EN] Mass per unit area of the nonwoven/geotextile of the upper protection layer in g/m² (manufacturer data sheet). Minimum per Tab. 27 by protection-efficiency class: SWK 1 ≥ 300 g, SWK 2 ≥ 500 g, SWK 3 ≥ 800 g, each GRK 5; for static loading nonwovens ≥ 300 g/m² GRK 5 (§ 8.2, Tab. 26). Gate REQ-24 compares the value with the Tab. 27 minimum once an SWK is selected.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'sl_schutzlage_oben_flaechengewicht';
UPDATE fields x SET description = 'Werkstoff der Schutzlage unterhalb der Abdichtung in Worten (Datenblatt). Geeignet nach § 8.3.1: Vliesstoffe/Geotextilien aus synthetischen Fasern, Kunststoff-/Elastomerbahnen, Bautenschutzmatten/-platten aus Gummi- oder PE-Granulat, Beton/Mörtel, mineralische Schüttstoffe. Welche davon für den Baugrund zulässig sind, zeigt Tab. 26 nach Bodengruppe (nachgeschlagen im Feld „Werkstoffe nach Tab. 26“). Bei Größtkorn d ≤ 2 mm kann auf Schutzlagen verzichtet werden (§ 8.1).
[EN] Material of the protection layer below the sealing in words (data sheet). Suitable per § 8.3.1: synthetic nonwovens/geotextiles, plastic/elastomer sheets, protection mats/boards of rubber or PE granulate, concrete/mortar, mineral fill. Which of these are permitted for the subgrade is shown by Tab. 26 by soil group (looked up in the field ''materials per Tab. 26''). With maximum grain size d ≤ 2 mm protection layers may be omitted (§ 8.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'sl_schutzlage_unten_typ';
UPDATE fields x SET description = 'Flächengewicht des Vliesstoffs/Geotextils der unteren Schutzlage in g/m² (Datenblatt). Tab. 26 setzt für Vliesstoffe bzw. Geotextilien ≥ 300 g/m², GRK 5 voraus – als Werkstoff nur bei den Bodengruppen UL/UM/UA und TL/TM/TA mit „x“ markiert; § 8.2 nennt ebenfalls ≥ 300 g/m², GRK 5. Nur ausfüllen, wenn ein Vliesstoff vorgesehen ist.
[EN] Mass per unit area of the nonwoven/geotextile of the lower protection layer in g/m² (data sheet). Tab. 26 presupposes nonwovens/geotextiles ≥ 300 g/m², GRK 5 – marked ''x'' as a material only for soil groups UL/UM/UA and TL/TM/TA; § 8.2 also states ≥ 300 g/m², GRK 5. Fill in only if a nonwoven is planned.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'sl_schutzlage_unten_flaechengewicht';
UPDATE fields x SET description = 'Ja, wenn unter der Abdichtung eine Dränschicht/Entwässerung erforderlich ist – z. B. wegen Baugrundentwässerung bei entsprechenden hydrologischen Verhältnissen (§ 4.6), Zwischenentwässerung bei Kondensatbildung (§ 4.4) oder Auftriebsgefahr. Soll die Schutzschicht auch eine Dränfunktion übernehmen, muss sie den Anforderungen der DIN 4095 entsprechen (§ 8.3). Keine Rechenprüfung.
[EN] Yes if a drainage layer/dewatering below the sealing is required – e.g. subgrade dewatering under the given hydrological conditions (§ 4.6), intermediate drainage where condensate forms (§ 4.4) or uplift risk. If the protection layer is also to drain, it must meet DIN 4095 (§ 8.3). No numeric check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'sl_drainage_erforderlich';
UPDATE fields x SET description = 'Dicke der Substrat-/Pflanzschicht über der Abdichtung in cm (Planung). Beim Einbau von Substraten und nicht bodengebundener Vegetation (Schwimmpflanzen, Röhrichtmatten) muss die Verträglichkeit mit der Abdichtung sichergestellt werden (§ 10.1); Schutzlagen bzw. -schichten können je nach Zusammensetzung zusätzlich als Auflast wirken (§ 8.1). Die Richtlinien nennen keine Mindestdicke für Substrate; keine Rechenprüfung.
[EN] Thickness of the substrate/planting layer above the sealing in cm (design). When installing substrates and non-soil-bound vegetation (floating plants, reed mats) compatibility with the sealing must be ensured (§ 10.1); depending on their composition, protection layers can additionally act as ballast (§ 8.1). The guideline gives no minimum substrate thickness; no numeric check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'sl_substratschicht_dicke';
UPDATE fields x SET description = 'Erforderliches bzw. vorhandenes Flächengewicht g'' der Auflast gegen Abheben in kN/m² (Anhang 2, informativ, nach BAW-Merkblatt). Berechnet nach Gl. 2a als g'' = γ''D · dD (Anhang 2 druckt verkürzt g'' = γ''D; der Faktor dD folgt aus den Einheiten) und muss die Bedingung Gl. 2b erfüllen: g'' ≥ Δu · γA / cos β − (γ''F · dF + γ''Di · dDi), wobei nur Δu · γA durch cos β geteilt wird. Anwendung, wenn der Grundwasserspiegel über der Gewässeroberfläche liegt – dann ist die Auflast auf den maximalen Wasserüberdruck zu bemessen (§ 4.4). Nicht eingeben.
[EN] Required/available mass per unit area g'' of the ballast against uplift in kN/m² (Annex 2, informative, after the BAW code of practice). Computed per eq. 2a as g'' = γ''D · dD (Annex 2 prints the shortened g'' = γ''D; the factor dD follows from the units) and must satisfy condition eq. 2b: g'' ≥ Δu · γA / cos β − (γ''F · dF + γ''Di · dDi), where only Δu · γA is divided by cos β. Applies when the groundwater table lies above the water surface – the ballast must then be sized for the maximum water overpressure (§ 4.4). Not an entry.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'g_prime';
UPDATE fields x SET description = 'Porenwasserüberdruck Δu unter der Dichtung in kN/m², berechnet nach Gl. 2c: Δu = (ΔhW + za) · γw (Anhang 2). Eingang der Auflastbedingung Gl. 2b. Nicht eingeben; Wasserspiegeldifferenz ΔhW, Absunk za und Wichte γw eintragen.
[EN] Pore-water overpressure Δu under the sealing in kN/m², computed per eq. 2c: Δu = (ΔhW + za) · γw (Annex 2). Input to the ballast condition eq. 2b. Not an entry; enter the level difference ΔhW, the drawdown za and the unit weight γw.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'Delta_u';
UPDATE fields x SET description = 'Dicke der Auflast dD in m (Anhang 2: „Dicke der Auflast [m]“) – die Schicht über der Abdichtung (Schüttstoffe, Substrat), aus der Planung. Mit γ''D ergibt sie das Flächengewicht g'' (Gl. 2a). Hinweis: Das Feld meint die Auflast, nicht die Abdichtung.
[EN] Thickness of the ballast dD in m (Annex 2: ''thickness of the ballast [m]'') – the layer above the sealing (fill, substrate), from the design. With γ''D it gives the mass per unit area g'' (eq. 2a). Note: the field refers to the ballast, not to the sealing.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'd_D';
UPDATE fields x SET description = 'Wichte der Auflast unter Auftrieb γ''D in kN/m³ (Anhang 2), d. h. die Wichte des Auflastmaterials abzüglich des Wasserauftriebs; aus Bodenkennwerten/Lieferdaten des Schüttstoffs. Eingang der Gl. 2a (g'' = γ''D · dD). Die Richtlinien drucken keinen Zahlenwert.
[EN] Buoyant unit weight of the ballast γ''D in kN/m³ (Annex 2), i.e. the unit weight of the ballast material less water buoyancy; from soil parameters/supplier data of the fill. Input to eq. 2a (g'' = γ''D · dD). The guideline prints no numeric value.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'gamma_D_prime';
UPDATE fields x SET description = 'Dicke der Dichtungsschicht dDi in m (Anhang 2: „Dicke der Dichtungsschicht [m]“) – die Abdichtung selbst, aus dem Schichtaufbau (FLL-GAR-09). Geht mit γ''Di als Eigengewicht der Dichtung in die Auflastbedingung Gl. 2b ein. Hinweis: Das englische Feldlabel „drainage layer“ ist irreführend; gemeint ist die Dichtungsschicht.
[EN] Thickness of the sealing layer dDi in m (Annex 2: ''thickness of the sealing layer [m]'') – the sealing itself, from the layer build-up (FLL-GAR-09). Enters the ballast condition eq. 2b with γ''Di as the sealing''s own weight. Note: the English field label ''drainage layer'' is misleading; the printed symbol means the sealing layer.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'd_Di';
UPDATE fields x SET description = 'Dicke des Filters dF in m (Anhang 2: „Dicke des Filters [m]“) – das Schutzvlies/die Filterlage im Deckwerk, aus dem Schichtaufbau. Geht mit γ''F in die Auflastbedingung Gl. 2b ein; 0 eintragen, wenn keine Filterlage vorhanden ist.
[EN] Thickness of the filter dF in m (Annex 2: ''thickness of the filter [m]'') – the protective nonwoven/filter layer in the cover, from the layer build-up. Enters the ballast condition eq. 2b with γ''F; enter 0 if there is no filter layer.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'd_F';
UPDATE fields x SET description = 'Böschungswinkel β in Grad (Anhang 2) des betrachteten Abschnitts, aus der Neigung 1:m der Profilschnitte (FLL-GAR-07). In Gl. 2b wird nur Δu · γA durch cos β geteilt: je steiler, desto größer das erforderliche g''. Für die Sohle 0° eintragen.
[EN] Slope angle β in degrees (Annex 2) of the section considered, from the slope 1:m of the profile sections (FLL-GAR-07). In eq. 2b only Δu · γA is divided by cos β: the steeper, the larger the required g''. Enter 0° for the base.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'beta';
UPDATE fields x SET description = 'Wichte des Dichtungsmaterials unter Auftrieb γ''Di in kN/m³ (Anhang 2) – Eigengewicht der Abdichtung abzüglich Auftrieb, aus Herstellerdaten/Dichte des Abdichtungsstoffs. Eingang der Gl. 2b. Hinweis: Das Feldlabel „Drainage weight“ ist irreführend; gedruckt ist „Wichte des Dichtungsmaterials unter Auftrieb“.
[EN] Buoyant unit weight of the sealing material γ''Di in kN/m³ (Annex 2) – own weight of the sealing less buoyancy, from manufacturer data/density of the sealing material. Input to eq. 2b. Note: the field label ''drainage weight'' is misleading; the printed symbol is ''unit weight of the sealing material under buoyancy''.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'gamma_Di_prime';
UPDATE fields x SET description = 'Wichte des Schutzvlieses unter Auftrieb γ''F in kN/m³ (Anhang 2) – Eigengewicht der Filter-/Schutzvlieslage abzüglich Auftrieb, aus Herstellerdaten. Eingang der Gl. 2b zusammen mit dF; 0 eintragen, wenn keine Filterlage vorhanden ist.
[EN] Buoyant unit weight of the protective nonwoven γ''F in kN/m³ (Annex 2) – own weight of the filter/protective-nonwoven layer less buoyancy, from manufacturer data. Input to eq. 2b together with dF; enter 0 if there is no filter layer.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'gamma_F_prime';
UPDATE fields x SET description = 'Sicherheitsbeiwert gegen Auftrieb γA, dimensionslos. Anhang 2 setzt ihn fest: „γA Sicherheit gegen Auftrieb [-], γA = 1,00“ – diesen Wert eintragen, sofern das Projekt keinen höheren Sicherheitsbeiwert vereinbart. Multipliziert den Porenwasserüberdruck Δu in Gl. 2b. Nicht zu verwechseln mit der Auftriebswichte γ''D.
[EN] Safety factor against uplift γA, dimensionless. Annex 2 fixes it: ''γA safety against uplift [-], γA = 1.00'' – enter this value unless the project agrees a higher safety factor. Multiplies the pore-water overpressure Δu in eq. 2b. Not to be confused with the buoyant unit weight γ''D.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'gamma_A';
UPDATE fields x SET description = 'Höhenunterschied ΔhW in m zwischen Grundwasserspiegel und Ruhewasserspiegel im Gewässer – positiv, wenn der Grundwasserspiegel über dem Ruhewasserspiegel liegt (Anhang 2). Aus Baugrundgutachten (höchster Grundwasserstand) und Planung; Eingang der Gl. 2c. Liegt der Grundwasserspiegel über der Gewässeroberfläche, ist die Auflast auf den maximalen Wasserüberdruck zu bemessen (§ 4.4).
[EN] Height difference ΔhW in m between the groundwater table and the still-water level in the water body – positive when the groundwater table lies above the still-water level (Annex 2). From the geotechnical report (highest groundwater level) and the design; input to eq. 2c. If the groundwater table lies above the water surface, the ballast must be sized for the maximum water overpressure (§ 4.4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'Delta_h_W';
UPDATE fields x SET description = 'Wichte des Wassers γw in kN/m³, Faktor in Gl. 2c (Δu = (ΔhW + za) · γw, Anhang 2). Anhang 2 druckt keinen Zahlenwert; den im Projekt verwendeten Wert (Süßwasser, ggf. Dichte des Füllwassers) eintragen und in der Berechnung ausweisen.
[EN] Unit weight of water γw in kN/m³, factor in eq. 2c (Δu = (ΔhW + za) · γw, Annex 2). Annex 2 prints no numeric value; enter the value used in the project (fresh water, density of the fill water if relevant) and state it in the calculation.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'gamma_w';
UPDATE fields x SET description = 'Maximaler schneller Wasserspiegelabsunk za im Gewässer (z. B. bei schneller Entleerung), Anhang 2; im Blatt in m geführt, da er in Gl. 2c zu ΔhW addiert wird (Anhang 2 druckt bei za die Einheit kN/m², bei ΔhW m). Aus dem Betriebskonzept (Entleerung, Wasserstandsregelung) ableiten; 0, wenn kein schneller Absunk auftritt.
[EN] Maximum rapid drawdown za of the water level (e.g. fast emptying), Annex 2; kept in m on this sheet because eq. 2c adds it to ΔhW (Annex 2 prints kN/m² as the unit of za and m for ΔhW). Derive from the operating concept (emptying, level control); 0 if no rapid drawdown occurs.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'z_a';
UPDATE fields x SET description = 'Bodengruppe des Baugrunds nach DIN 18196 aus dem Baugrundgutachten – Zeilenköpfe der Tab. 26: GE/GW/GI (Kiese), SE/SW/SI (Sande), GU/GU*/GT/GT*, SU/SU*/ST/ST* (gemischtkörnig), UL/UM/UA (Schluffe), TL/TM/TA (Tone). Schlüssel für die Nachschlagefelder Sand-Mindestdicke und Werkstoffe der unteren Schutzlage (§ 8.3.1, Tab. 26).
[EN] Soil group of the subgrade per DIN 18196 from the geotechnical report – row headers of Tab. 26: GE/GW/GI (gravels), SE/SW/SI (sands), GU/GU*/GT/GT*, SU/SU*/ST/ST* (mixed-grained), UL/UM/UA (silts), TL/TM/TA (clays). Key for the lookup fields minimum sand thickness and materials of the lower protection layer (§ 8.3.1, Tab. 26).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'baugrund_klasse_18196';
UPDATE fields x SET description = 'Nachgeschlagene Mindestdicke einer Sand-Schutzschicht (0,063 bis 2 mm) unter der Abdichtung in cm nach Tab. 26, Spalte 2: 10 cm bei GE/GW/GI und GU/GU*/GT/GT*; 5 cm bei SU/SU*/ST/ST*, UL/UM/UA und TL/TM/TA; „–“ bei Sandböden SE/SW/SI (keine Angabe). Vergleichswert für die Ist-Dicke in Tor REQ-24. Bei Größtkorn d ≤ 2 mm kann auf Schutzlagen verzichtet werden (§ 8.1).
[EN] Looked-up minimum thickness of a sand protection layer (0.063 to 2 mm) below the sealing in cm per Tab. 26, column 2: 10 cm for GE/GW/GI and GU/GU*/GT/GT*; 5 cm for SU/SU*/ST/ST*, UL/UM/UA and TL/TM/TA; ''–'' for sandy soils SE/SW/SI (no value). Comparison value for the actual thickness in gate REQ-24. With maximum grain size d ≤ 2 mm protection layers may be omitted (§ 8.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'sl_schutzlage_unten_sand_min_cm';
UPDATE fields x SET description = 'Nachgeschlagene Werkstoffe der unteren Schutzlage, die Tab. 26 für die gewählte Bodengruppe mit „x“ zulässt: Vliesstoffe/Geotextilien ≥ 300 g/m² GRK 5; Bautenschutzmatten/-platten ≥ 6 mm; Kunststoff-/Elastomerbahnen ≥ 1 mm; Beton/Mörtel ≥ 50 mm – plus die Sand-Mindestdicke. Kiese und gemischtkörnige Böden GU/GT: nur Sand 10 cm oder Beton/Mörtel; SU/ST: Sand 5 cm, Matten, Bahnen, Beton; Schluffe und Tone: alle Werkstoffe, Sand 5 cm; SE/SW/SI: keine Angabe. Vergleichstext für das Freitextfeld Schutzlage unten Typ.
[EN] Looked-up materials of the lower protection layer that Tab. 26 marks ''x'' for the selected soil group: nonwovens/geotextiles ≥ 300 g/m² GRK 5; protection mats/boards ≥ 6 mm; plastic/elastomer sheets ≥ 1 mm; concrete/mortar ≥ 50 mm – plus the minimum sand thickness. Gravels and mixed-grained GU/GT: only sand 10 cm or concrete/mortar; SU/ST: sand 5 cm, mats, sheets, concrete; silts and clays: all materials, sand 5 cm; SE/SW/SI: no entry. Reference text for the free-text field lower protection type.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'sl_schutzlage_unten_werkstoffe_tab26';
UPDATE fields x SET description = 'Schutzwirksamkeitsklasse nach DIN EN 13719 für die obere Schutzlage bei dynamischer Beanspruchung (Tab. 27): SWK 1 – dynamische Belastung 8,2 kN, z. B. begehbare Abdichtungen; SWK 2 – 17,1 kN, z. B. befahrbar mit leichten Fahrzeugen bis 2,5 t = 25 kN; SWK 3 – 43,7 kN, z. B. Fahrzeuge bis 16 t = 160 kN. Aus Nutzung und Wartungskonzept wählen; bei abweichendem Baugrund (geringe Lagerungsdichte, weiche Konsistenz) oder weicheren/plastischeren Abdichtungen die nächsthöhere SWK verwenden (§ 8.3.2). Leer lassen bei rein statischer Beanspruchung.
[EN] Protection-efficiency class per DIN EN 13719 for the upper protection layer under dynamic loading (Tab. 27): SWK 1 – dynamic load 8.2 kN, e.g. walkable sealings; SWK 2 – 17.1 kN, e.g. trafficable with light vehicles up to 2.5 t = 25 kN; SWK 3 – 43.7 kN, e.g. vehicles up to 16 t = 160 kN. Choose from use and maintenance concept; with deviating subgrade (low density, soft consistency) or softer/more plastic sealings use the next higher SWK (§ 8.3.2). Leave empty for purely static loading.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'swk_klasse';
UPDATE fields x SET description = 'Nachgeschlagenes Mindestflächengewicht des Vliesstoffs/Geotextils der oberen Schutzlage nach Tab. 27 für die gewählte SWK: ≥ 300 g (SWK 1), ≥ 500 g (SWK 2), ≥ 800 g (SWK 3), jeweils GRK 5. Für die erforderliche SWK gelten die Mindestanforderungen der Tab. 27 (§ 8.3.2). Vergleichswert für das Ist-Flächengewicht in Tor REQ-24.
[EN] Looked-up minimum mass per unit area of the nonwoven/geotextile of the upper protection layer per Tab. 27 for the selected SWK: ≥ 300 g (SWK 1), ≥ 500 g (SWK 2), ≥ 800 g (SWK 3), each GRK 5. The minimum requirements of Tab. 27 apply to the required SWK (§ 8.3.2). Comparison value for the actual mass in gate REQ-24.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'sl_schutzlage_oben_flaechengewicht_min';
UPDATE fields x SET description = 'Bestätigung, dass für den Abdichtungsstoff das FLL-Testat „rhizomfest gegen Quecken“ aus dem „Verfahren zur Untersuchung der Wurzelfestigkeit von Bahnen und Beschichtungen für Dachbegrünungen“ vorliegt – die Mindestanforderung bei vorgesehener Bepflanzung (§ 4.3; § 10.4). Nicht nötig für Abdichtungen, die werkstoffbedingt als wurzel-/rhizomfest gelten (Stahl, Beton, PEHD, § 10.4; PEHD auch § 6.4.1.1). Eingang des Sperrtors REQ-11.
[EN] Confirmation that the FLL certificate ''rhizome-proof against couch grass'' from the ''procedure for testing root resistance of sheets and coatings for green roofs'' is available for the sealing material – the minimum requirement with planned planting (§ 4.3; § 10.4). Not needed for sealings that count as root-/rhizome-resistant by material (steel, concrete, PEHD, § 10.4; PEHD also § 6.4.1.1). Input to blocking gate REQ-11.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'wurzelfestigkeit_testat_quecken';
UPDATE fields x SET description = 'Bestätigung, dass die zusätzliche Prüfung nach dem FLL-„Verfahren zur Bestimmung der Rhizomfestigkeit von Gewässerabdichtungen“ vorliegt. Erforderlich bei Beanspruchung durch wurzelaggressive und rhizombildende Pflanzenarten (z. B. Phragmites australis, § 4.3) und bei intensiverer Beanspruchung wie Pflanzenkläranlagen oder Aufbereitungsbereichen von Schwimmteichen; die Prüfung erfolgt ausschließlich mit Phragmites australis (§ 10.4). Eingang des Sperrtors REQ-11, wenn aggressive Arten in FLL-GAR-24 gezählt sind.
[EN] Confirmation that the additional test per the FLL ''procedure for determining the rhizome resistance of water-body sealings'' is available. Required with root-aggressive and rhizome-forming species (e.g. Phragmites australis, § 4.3) and with intensive planting such as constructed wetlands or treatment zones of swimming ponds; the test uses Phragmites australis exclusively (§ 10.4). Input to blocking gate REQ-11 when aggressive species are counted in FLL-GAR-24.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'rhizomfestigkeit_gewaesser_pruefung';
UPDATE fields x SET description = 'Größtkorn d des Baugrunds in mm aus dem Baugrundgutachten (Sieblinie). Bei Größtkorn d ≤ 2 mm kann auf Schutzlagen bzw. -schichten unter der Abdichtung verzichtet werden (§ 8.1); Tor REQ-24 akzeptiert dann das Fehlen einer unteren Schutzlage. Darüber gelten Werkstoffe und Sand-Mindestdicke nach Tab. 26.
[EN] Maximum grain size d of the subgrade in mm from the geotechnical report (grading curve). With d ≤ 2 mm protection layers below the sealing may be omitted (§ 8.1); gate REQ-24 then accepts a missing lower protection layer. Above that, materials and minimum sand thickness per Tab. 26 apply.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'sl_baugrund_groesstkorn_mm';
UPDATE fields x SET description = 'Ausgeführte Dicke der Sand-Schutzschicht unter der Abdichtung im verdichteten Zustand in cm (Planung/Aufmaß). Mindestens die Tab.-26-Mindestdicke der Bodengruppe (10 bzw. 5 cm); mineralische Schüttstoffgemische 0,063–2 mm brauchen allgemein ≥ 50 mm im verdichteten Zustand, je nach Beanspruchung mehr (§ 8.2). Tor REQ-24 vergleicht mit dem nachgeschlagenen Mindestwert.
[EN] Built thickness of the sand protection layer below the sealing in compacted state in cm (design/measurement). At least the Tab. 26 minimum of the soil group (10 or 5 cm); mineral fill 0.063–2 mm generally needs ≥ 50 mm compacted, more depending on loading (§ 8.2). Gate REQ-24 compares it with the looked-up minimum.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'sl_schutzlage_unten_dicke_cm';
UPDATE fields x SET description = 'Überlappung der Bahnen bzw. Geotextilien der Schutzlagen in cm (Verlegeplan/Ausführung). Bei Schutzlagen aus Kunststoffbahnen und Geotextilien ist eine Überlappung von mind. 10 cm dauerhaft vorzusehen; auf stabilem, ebenem Untergrund ist bei dauerhafter Fixierung auch Verlegung auf Stoß möglich (§ 8.3). Tor REQ-24 verlangt ≥ 10 cm.
[EN] Overlap of the sheets or geotextiles of the protection layers in cm (laying plan/execution). For protection layers of plastic sheets and geotextiles a permanent overlap of at least 10 cm must be provided; on a stable, even substrate butt-laying is possible with permanent fixing (§ 8.3). Gate REQ-24 requires ≥ 10 cm.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'sl_ueberlappung_cm';
UPDATE fields x SET description = 'Nur sichtbar, wenn eine SWK gewählt ist. Bestätigung, dass ein Prüfzeugnis des Herstellers die Eignung der Schutzlage für die Belastungsklasse (SWK nach DIN EN 13719) belegt: Der objektbezogene Nachweis der Schutzwirksamkeit kann nur durch Prüfung des Produkts geführt und muss durch ein Prüfzeugnis belegt werden (§ 8.3.2). Eingang des Sperrtors REQ-24.
[EN] Visible only when an SWK is selected. Confirmation that a manufacturer''s test certificate proves the suitability of the protection layer for the load class (SWK per DIN EN 13719): the object-related proof of protection efficiency can only be provided by product testing and must be documented by a test certificate (§ 8.3.2). Input to blocking gate REQ-24.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.symbol = 'sl_pruefzeugnis_swk';
UPDATE equations x SET description = 'Flächengewicht der Auflast g'' = γ''D · dD (Anhang 2, informativ). Anhang 2 druckt die Gleichung verkürzt als g'' = γ''D; aus den Einheiten (kN/m² = kN/m³ · m) folgt der Faktor dD, den das Blatt verwendet. γ''D = Wichte der Auflast unter Auftrieb [kN/m³], dD = Dicke der Auflast [m], g'' = Flächengewicht der Auflast [kN/m²]. Ergebnis g'' wird mit der Mindestbedingung Gl. 2b verglichen; Anwendung bei Grundwasser über der Gewässeroberfläche (§ 4.4).
[EN] Mass per unit area of the ballast g'' = γ''D · dD (Annex 2, informative). Annex 2 prints the equation shortened as g'' = γ''D; the factor dD follows from the units (kN/m² = kN/m³ · m) and is what the sheet uses. γ''D = buoyant unit weight of the ballast [kN/m³], dD = thickness of the ballast [m], g'' = mass per unit area of the ballast [kN/m²]. The result g'' is compared with the minimum condition eq. 2b; applies with groundwater above the water surface (§ 4.4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.equation_number = '2a';
UPDATE equations x SET description = 'Erforderliches Flächengewicht der Auflast gegen Abheben (Anhang 2, informativ, nach BAW-Merkblatt): g'' ≥ Δu · γA / cos β − (γ''F · dF + γ''Di · dDi). Nur Δu · γA wird durch cos β geteilt; die Klammer wird danach abgezogen. Δu Porenwasserüberdruck [kN/m²] (Gl. 2c), γA = 1,00, β Böschungswinkel [°], γ''F/dF Wichte und Dicke des Schutzvlieses, γ''Di/dDi Wichte und Dicke der Dichtungsschicht. Gesuchte Größe ist g'' in kN/m², wie Überschrift und Symbolliste des Anhangs 2 es definieren (die gedruckte Zeile nennt links dD – eine Unstimmigkeit im Druck); verglichen wird mit g'' aus Gl. 2a.
[EN] Required mass per unit area of the ballast against uplift (Annex 2, informative, after the BAW code of practice): g'' ≥ Δu · γA / cos β − (γ''F · dF + γ''Di · dDi). Only Δu · γA is divided by cos β; the bracket is subtracted afterwards. Δu pore-water overpressure [kN/m²] (eq. 2c), γA = 1.00, β slope angle [°], γ''F/dF unit weight and thickness of the protective nonwoven, γ''Di/dDi unit weight and thickness of the sealing layer. The required quantity is g'' in kN/m², as the heading and the symbol list of Annex 2 define it (the printed line shows dD on the left – a print inconsistency); it is compared with g'' from eq. 2a.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.equation_number = '2b';
UPDATE equations x SET description = 'Porenwasserüberdruck unter der Dichtung: Δu = (ΔhW + za) · γw (Anhang 2). ΔhW = Höhenunterschied [m] zwischen Grundwasserspiegel und Ruhewasserspiegel (positiv bei Grundwasser über dem Ruhewasserspiegel), za = maximaler schneller Wasserspiegelabsunk, γw = Wichte des Wassers [kN/m³] (kein Zahlenwert gedruckt). Ergebnis Δu [kN/m²] geht in Gl. 2b ein.
[EN] Pore-water overpressure under the sealing: Δu = (ΔhW + za) · γw (Annex 2). ΔhW = height difference [m] between groundwater table and still-water level (positive with groundwater above the still-water level), za = maximum rapid drawdown, γw = unit weight of water [kN/m³] (no numeric value printed). The result Δu [kN/m²] feeds eq. 2b.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.equation_number = '2c';
UPDATE compliance_requirements x SET description = 'Gilt nur, wenn in FLL-GAR-24 „mit Bepflanzung“ = Ja. Besteht, wenn (a) die Abdichtung eine PEHD-Bahn ist (Abdichtungsart PE-Bahnen mit Werkstoff PEHD im PE-Blatt – auf eine Prüfung kann verzichtet werden, § 6.4.1.1) oder (b) das FLL-Testat „rhizomfest gegen Quecken“ bestätigt ist und entweder keine aggressiven Arten gezählt sind (FLL-GAR-24) oder die Prüfung der Rhizomfestigkeit von Gewässerabdichtungen vorliegt (§ 4.3; § 10.4). Sperrtor: Bepflanzung, Pflanzenarten-Register und die beiden Nachweise eintragen. Stahl und Beton gelten nach § 10.4 ebenfalls als wurzel-/rhizomfest, werden vom Tor aber nicht automatisch anerkannt.
[EN] Applies only when ''with planting'' = yes in FLL-GAR-24. Passes when (a) the sealing is a PEHD sheet (sealing type PE sheets with material PEHD on the PE sheet – the test may be waived, § 6.4.1.1) or (b) the FLL certificate ''rhizome-proof against couch grass'' is confirmed and either no aggressive species are counted (FLL-GAR-24) or the rhizome-resistance test for water-body sealings is available (§ 4.3; § 10.4). Blocking gate: enter planting, the plant-species register and both attestations. Steel and concrete also count as root-/rhizome-resistant per § 10.4 but are not recognised automatically by the gate.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.code = 'REQ-11';
UPDATE compliance_requirements x SET description = 'Besteht, wenn drei Bedingungen erfüllt sind: (1) Größtkorn des Baugrunds ≤ 2 mm (Verzicht auf Schutzlagen möglich, § 8.1) oder Ist-Dicke der Sand-Schutzschicht unten ≥ Tab.-26-Mindestdicke der Bodengruppe (10 bzw. 5 cm); (2) keine SWK gewählt (statische Beanspruchung) oder Flächengewicht der oberen Schutzlage ≥ Tab.-27-Mindestwert (300/500/800 g GRK 5) und Prüfzeugnis bestätigt (§ 8.3.2); (3) Überlappung der Schutzlagen ≥ 10 cm (§ 8.3). Dazu Bodengruppe, Größtkorn, Ist-Dicke, SWK, Flächengewicht, Prüfzeugnis und Überlappung eintragen. Sperrtor.
[EN] Passes when three conditions hold: (1) maximum grain size of the subgrade ≤ 2 mm (protection layers may be omitted, § 8.1) or actual thickness of the lower sand layer ≥ Tab. 26 minimum of the soil group (10 or 5 cm); (2) no SWK selected (static loading) or mass per unit area of the upper protection layer ≥ Tab. 27 minimum (300/500/800 g GRK 5) with the test certificate confirmed (§ 8.3.2); (3) overlap of the protection layers ≥ 10 cm (§ 8.3). Enter soil group, maximum grain size, actual thickness, SWK, mass per unit area, test certificate and overlap. Blocking gate.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.code = 'REQ-24';
UPDATE compliance_requirements x SET description = 'Besteht, wenn der Nachweis „Bepflanzung und Rhizom-/Wurzelschutz“ bestätigt ist: Die Pflanzenarten sind gegen die Beispiele wurzel-/rhizomaggressiver Arten der Tab. 29 geprüft, für derartige Arten sind bauliche Vorkehrungen (Rhizom-/Wurzelsperre) und Pflegemaßnahmen vorgesehen (§ 10.3), und die Wurzel-/Rhizomprüfung nach § 10.4 liegt vor, soweit die Abdichtung nicht werkstoffbedingt als wurzel-/rhizomfest gilt (Stahl, Beton, PEHD). Sperrtor: Pflanzenliste in FLL-GAR-24 führen und das Attest setzen.
[EN] Passes when the attestation ''planting and rhizome/root protection'' is confirmed: the plant species have been checked against the examples of root-/rhizome-aggressive species in Tab. 29, structural precautions (rhizome/root barrier) and maintenance are planned for such species (§ 10.3), and the root/rhizome test per § 10.4 is available unless the sealing counts as root-/rhizome-resistant by material (steel, concrete, PEHD). Blocking gate: keep the plant list in FLL-GAR-24 and tick the attestation.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-22' AND x.code = 'REQ-25';
UPDATE fields x SET description = 'Anwendungsfall des Randabschlusses nach den Spalten der Tab. 28: Bauteil/Bauwerk (Anschluss an aufgehende Bauteile, z. B. Fassade), Freifläche (Übergang zu Vegetations- oder Belagsflächen) oder Schwimmteich (Nutzung als Schwimmteich). Tab. 28 ordnet jedem Fall die zulässigen An-/Abschlusshöhen zu; X = zugelassen, (X) = nur mit geeigneter Randbefestigung und Sicherung gegen Hinter- und Unterläufigkeit, –¹ = nur als Sonderkonstruktion (§ 9.1).
[EN] Application case of the edge termination per the columns of Tab. 28: component/structure (connection to rising parts, e.g. façade), open space (transition to vegetated or paved areas) or swimming pond (use as a swimming pond). Tab. 28 assigns the permitted connection/termination heights to each case; X = permitted, (X) = only with suitable edge fastening and protection against water passing behind or under, –¹ = only as a special construction (§ 9.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-23' AND x.symbol = 'abschluss_anwendungsfall';
UPDATE fields x SET description = 'Überhöhung der Abdichtungsoberkante über dem geplanten Höchstwasserstand an aufgehenden Bauteilen und Bauwerken in cm (Planung, Schnitt). Regel: i. d. R. 30 cm; nur mit geeigneter Randbefestigung und Sicherung gegen Hinter- und Unterlaufen ist eine Reduzierung auf mind. 15 cm zugelassen (§ 4.8; § 9.1); Tab. 28 druckt für Bauteil/Bauwerk ≥ 15 cm als (X), kleinere Höhen nur als Sonderkonstruktion. Warntor REQ-23 prüft ≥ 30 cm bzw. ≥ 15 cm mit angepasster Randbefestigung.
[EN] Upstand of the sealing top edge above the planned maximum water level at rising components and structures in cm (design, section). Rule: as a rule 30 cm; only with suitable edge fastening and protection against water passing behind or under is a reduction to at least 15 cm permitted (§ 4.8; § 9.1); Tab. 28 prints ≥ 15 cm for component/structure as (X), lower heights only as a special construction. Warning gate REQ-23 checks ≥ 30 cm or ≥ 15 cm with adapted edge fastening.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-23' AND x.symbol = 'freibord_zu_bauwerk_cm';
UPDATE fields x SET description = 'Überhöhung der Abdichtungsoberkante über dem geplanten Höchstwasserstand im frei gestalteten Übergang zum Gelände in cm (Planung). Regel: dauerhaft mind. 5 cm (50 mm), auch bei Schwimm- und Badeteichen in Abhängigkeit vom Wellenschlag; je nach Abdichtung, Befestigung, Bebauung und Nutzung können größere Höhen erforderlich sein (§ 4.8; § 9.1). Tab. 28: Freifläche X bei ≥ 15, ≥ 10 und ≥ 5 cm; Schwimmteich X bei ≥ 15 und ≥ 10 cm, ≥ 5 cm nur als Sonderkonstruktion. Warntor REQ-23 prüft ≥ 5 cm.
[EN] Upstand of the sealing top edge above the planned maximum water level in the free transition to the terrain in cm (design). Rule: permanently at least 5 cm (50 mm), also for swimming and bathing ponds depending on wave action; larger heights may be needed depending on sealing, fastening, adjacent buildings and use (§ 4.8; § 9.1). Tab. 28: open space X at ≥ 15, ≥ 10 and ≥ 5 cm; swimming pond X at ≥ 15 and ≥ 10 cm, ≥ 5 cm only as a special construction. Warning gate REQ-23 checks ≥ 5 cm.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-23' AND x.symbol = 'freibord_zu_gelaende_cm';
UPDATE fields x SET description = 'Register: eine Zeile je Randabschnitt mit Anwendungsfall (Bauteil/Bauwerk, Freifläche, Schwimmteich), An-/Abschlusshöhe über max. Wasserstand in cm, Randbefestigung (z. B. Einbindegraben, Klemmschiene, Los-/Festflansch, Verklebung, § 9.2) und Kapillarsperre. Je Zeile wird die Tab.-28-Zulässigkeit eingeblendet: Zeile ≥ 15 / ≥ 10 / ≥ 5 / 0 cm; X zugelassen, (X) nur mit geeigneter Randbefestigung, –¹ nur als Sonderkonstruktion; die Höhe 0 druckt Tab. 28 für alle Fälle als Sonderkonstruktion. Die Höhen gelten als Mindesthöhen während des Betriebs (§ 9.1). Sonderkonstruktionen zählt FLL-GAR-23-D1.
[EN] Register: one row per edge section with application case (component/structure, open space, swimming pond), connection/termination height above max. water level in cm, edge fastening (e.g. anchor trench, clamping rail, loose/fixed flange, bonding, § 9.2) and capillary barrier. Each row shows the Tab. 28 admissibility: row ≥ 15 / ≥ 10 / ≥ 5 / 0 cm; X permitted, (X) only with suitable edge fastening, –¹ only as a special construction; height 0 is printed as special construction for all cases. The heights are minimum heights during operation (§ 9.1). Special constructions are counted by FLL-GAR-23-D1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-23' AND x.symbol = 'randabschnitte';
UPDATE fields x SET description = 'Berechnet (Gleichung FLL-GAR-23-D1): Anzahl der Randabschnitte, deren Höhe/Anwendungsfall Tab. 28 nur als Sonderkonstruktion zulässt (Fußnote 1: „Nur als Sonderkonstruktion, d. h. als besondere planerische und technische Lösung“). 0 = alle Abschnitte regulär zulässig. Für jeden gezählten Abschnitt ist die besondere Lösung zu planen und zu dokumentieren. Nicht eingeben.
[EN] Computed (equation FLL-GAR-23-D1): number of edge sections whose height/application case Tab. 28 permits only as a special construction (footnote 1: ''only as a special construction, i.e. a special design and technical solution''). 0 = all sections regularly permitted. For every counted section the special solution must be designed and documented. Not an entry.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-23' AND x.symbol = 'randabschnitte_sonder';
UPDATE fields x SET description = 'Ja, wenn am aufgehenden Bauteil eine angepasste Randbefestigung mit Sicherung gegen Hinter- und Unterlaufen vorgesehen ist (Werkstoffspezifisch z. B. Auflast/Widerlager, Verklebung, Los-/Festflanschkonstruktion, Klemmschiene, Klemmprofil, Verbundblech, § 9.2). Nur dann darf die Überhöhung am Bauwerk von i. d. R. 30 cm auf ≥ 15 cm reduziert werden (§ 4.8; § 9.1; Tab. 28 „(X)“). Eingang des Warntors REQ-23.
[EN] Yes if an adapted edge fastening with protection against water passing behind or under is planned at the rising component (material-specific e.g. ballast/abutment, bonding, loose/fixed flange, clamping rail, clamping profile, composite sheet, § 9.2). Only then may the upstand at the structure be reduced from as a rule 30 cm to ≥ 15 cm (§ 4.8; § 9.1; Tab. 28 ''(X)''). Input to warning gate REQ-23.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-23' AND x.symbol = 'randbefestigung_angepasst';
UPDATE equations x SET description = 'Zählt die Zeilen des Registers Randabschnitte, deren Zulässigkeit „Sonderkonstruktion“ ist – d. h. deren Tab.-28-Zelle „–¹“ druckt (Fußnote 1: nur als besondere planerische und technische Lösung): Bauteil/Bauwerk unter 15 cm, Schwimmteich unter 10 cm, alle Fälle bei 0 cm. Keine gedruckte Formel. Ergebnis randabschnitte_sonder; die Mindesthöhen 5/30/15 cm des § 4.8 prüft REQ-23 über die Skalarfelder.
[EN] Counts the rows of the edge-section register whose admissibility is ''special construction'' – i.e. whose Tab. 28 cell prints ''–¹'' (footnote 1: only as a special design and technical solution): component/structure below 15 cm, swimming pond below 10 cm, all cases at 0 cm. No printed formula. Result randabschnitte_sonder; the minimum heights 5/30/15 cm of § 4.8 are checked by REQ-23 via the scalar fields.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-23' AND x.equation_number = 'FLL-GAR-23-D1';
UPDATE compliance_requirements x SET description = 'Warnt, wenn die Überhöhung über dem Höchstwasserstand die Mindestwerte des § 4.8 unterschreitet: im freien Gelände ≥ 5 cm; an aufgehenden Bauteilen ≥ 30 cm oder ≥ 15 cm, wenn eine angepasste Randbefestigung bestätigt ist (§ 4.8; § 9.1). Dazu Freibord zu Gelände, Freibord zu Bauwerk (beide cm) und „Randbefestigung angepasst“ eintragen; Wellenschlag im Höchstwasserstand berücksichtigen (§ 9.1). Warntor: § 4.8 formuliert die Werte mit „sollte“/„i. d. R.“; § 9.1 nennt die 5 cm im freien Gelände jedoch als Muss und Tab. 28 die Höhen als Mindesthöhen – die Werte nicht als optional lesen.
[EN] Warns when the upstand above the maximum water level falls below the § 4.8 minimums: in free terrain ≥ 5 cm; at rising components ≥ 30 cm, or ≥ 15 cm when an adapted edge fastening is confirmed (§ 4.8; § 9.1). Enter freeboard to terrain, freeboard to structure (both cm) and ''edge fastening adapted''; account for wave action in the maximum water level (§ 9.1). Warning gate: § 4.8 phrases the values with should/as a rule; § 9.1 however states the 5 cm in free terrain as a must and Tab. 28 heights as minimums – do not read the values as optional.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-23' AND x.code = 'REQ-23';
UPDATE fields x SET description = 'Ja, wenn das Gewässer bepflanzt wird oder Vegetation im Abdichtungsbereich vorhanden/geplant ist (Pflanzplan). Bepflanzung darf die Abdichtungsfunktion nicht beeinträchtigen (§ 10.1); bei vorgesehener Bepflanzung ist die Wurzel-/Rhizomfestigkeit nachzuweisen (§ 4.3) – Ja aktiviert das Sperrtor REQ-11. Bei Alkalisilikat-Abdichtungen beachten: Natrium- und Lithium-Wasserglas sind phytotoxisch, Kalium-Wasserglas ist pflanzenverträglich (§ 7.2).
[EN] Yes if the water body is planted or vegetation exists/is planned within the sealed area (planting plan). Planting must not impair the sealing function (§ 10.1); with planned planting root/rhizome resistance must be proven (§ 4.3) – yes activates blocking gate REQ-11. For alkali-silicate sealings note: sodium and lithium water glass are phytotoxic, potassium water glass is plant-compatible (§ 7.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-24' AND x.symbol = 'mit_bepflanzung';
UPDATE fields x SET description = 'Freitextliste der geplanten/vorhandenen Pflanzenarten (Pflanzplan). Gegen Tab. 29 prüfen – Beispiele aggressiver Arten: Helophyten/Hydrophyten wie Phragmites australis (Schilfrohr), Phalaris arundinacea, Cyperus longus, Typha (Rohrkolben), Nymphaea, Nuphar; terrestrisch wie Phyllostachys/Bambus, Prunus spinosa, Pyracantha, Hippophae, Rosa rugosa, Arundo donax, Mahonia (§ 10.3). Strukturiert erfasst werden die Arten im Register „Pflanzenarten“; dieses Feld bleibt als Freitext.
[EN] Free-text list of planned/existing plant species (planting plan). Check against Tab. 29 – examples of aggressive species: helophytes/hydrophytes such as Phragmites australis (common reed), Phalaris arundinacea, Cyperus longus, Typha (cattail), Nymphaea, Nuphar; terrestrial such as Phyllostachys/bamboo, Prunus spinosa, Pyracantha, Hippophae, Rosa rugosa, Arundo donax, Mahonia (§ 10.3). The species are recorded in structured form in the ''plant species'' register; this field remains free text.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-24' AND x.symbol = 'bep_pflanzenarten';
UPDATE fields x SET description = 'Ja, wenn für die Abdichtung ein Nachweis der Wurzel-/Rhizomfestigkeit erforderlich ist: bei vorgesehener Bepflanzung grundsätzlich (Mindestnachweis Testat „rhizomfest gegen Quecken“), bei wurzelaggressiven/rhizombildenden Arten zusätzlich die Prüfung nach den Technischen Prüfbestimmungen für Gewässerabdichtungen (§ 4.3; § 10.4). Nein, wenn die Abdichtung werkstoffbedingt als wurzel-/rhizomfest gilt (Stahl, Beton, PEHD, § 10.4). Die Nachweise selbst werden in FLL-GAR-22 bestätigt.
[EN] Yes if a root/rhizome-resistance proof is required for the sealing: generally with planned planting (minimum proof certificate ''rhizome-proof against couch grass''), with root-aggressive/rhizome-forming species additionally the test per the technical test specifications for water-body sealings (§ 4.3; § 10.4). No if the sealing counts as root-/rhizome-resistant by material (steel, concrete, PEHD, § 10.4). The proofs themselves are confirmed in FLL-GAR-22.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-24' AND x.symbol = 'bep_rhizomfestigkeit_erforderlich';
UPDATE fields x SET description = 'Freitext zu Einbauten im Gewässer, z. B. Pflanztröge, Findlinge, Quellsteine, Fundamente von Stegen und Brücken, Treppen. Einbauten und ihre Ausführungs-/Wartungsarbeiten dürfen die Abdichtungsfunktion nicht beeinträchtigen; je nach Abdichtungswerkstoff und statischer/dynamischer Beanspruchung sind zusätzliche Schutzmaßnahmen nach Abschnitt 8 und 9 vorzusehen (§ 10.5). Strukturierte Erfassung im Register „Durchdringungen und Einbauten“.
[EN] Free text on installations in the water body, e.g. planters, boulders, spring stones, foundations of jetties and bridges, steps. Installations and their construction/maintenance work must not impair the sealing function; depending on sealing material and static/dynamic loading additional protection per sections 8 and 9 must be provided (§ 10.5). Structured recording in the register ''penetrations and installations''.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-24' AND x.symbol = 'bep_einbauten_typen';
UPDATE fields x SET description = 'Manuell gezählte Anzahl der Durchdringungen der Abdichtung (Zu-/Abläufe, Leitungen für Wasser-, Stromversorgung, Entwässerung). Durchdringungen sind auf das notwendige Maß zu beschränken und so anzuordnen, dass die Abdichtung werkstoffgerecht angeschlossen werden kann (§ 4.12); sie müssen Abdichtungsstoff und Wasserbeanspruchung entsprechen und ihre Funktion auch bei Bewegungen behalten (§ 4.9). Das Register liefert daneben die berechnete Anzahl (FLL-GAR-24-D1).
[EN] Manually counted number of penetrations through the sealing (inlets/outlets, pipes for water and power supply, drainage). Penetrations must be limited to the necessary minimum and arranged so that the sealing can be connected in a material-appropriate way (§ 4.12); they must suit the sealing material and water loading and keep their function under movements (§ 4.9). The register also provides the computed count (FLL-GAR-24-D1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-24' AND x.symbol = 'bep_durchdringungen_anzahl';
UPDATE fields x SET description = 'Register: eine Zeile je Durchdringung oder Einbau mit Typ (z. B. Ablauf, Leitung, Stegfundament), Lage, Fugenabdichtung/Anschlussdetail und Rhizomfestigkeitsnachweis des Anschlusses. Grundlage: bauliche Vorgaben wie Randausbildung, Anschlüsse, Durchdringungen und technische Einbauten sind Kriterien der Systemwahl (§ 4.7); Durchdringungen auf das notwendige Maß beschränken und werkstoffgerecht anschließen (§ 4.12; § 4.9); Einbauten dürfen die Abdichtung nicht beeinträchtigen (§ 10.5). Zeilenzahl → FLL-GAR-24-D1.
[EN] Register: one row per penetration or installation with type (e.g. outlet, pipe, jetty foundation), position, joint sealing/connection detail and rhizome-resistance proof of the connection. Basis: structural constraints such as edge design, connections, penetrations and technical installations are criteria for the system choice (§ 4.7); limit penetrations to the necessary minimum and connect them material-appropriately (§ 4.12; § 4.9); installations must not impair the sealing (§ 10.5). Row count → FLL-GAR-24-D1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-24' AND x.symbol = 'durchdringungen';
UPDATE fields x SET description = 'Register: eine Zeile je Pflanzenart mit botanischem Namen, Kennzeichen „aggressiv wurzelnd/rhizombildend“ (Einschätzung des Planers) und Tab.-29-Treffer (automatisch, wenn die Art in der Beispielliste der Tab. 29 steht – z. B. Phragmites australis, Typha, Carex riparia, Bambus, Prunus spinosa). Bei derartigen Arten sind bauliche Vorkehrungen (Rhizom-/Wurzelsperre) und besondere Pflege vorzusehen (§ 10.3); bei vorgesehener Bepflanzung ist die Wurzel-/Rhizomfestigkeit nachzuweisen (§ 4.3). Zahl der aggressiven Arten → FLL-GAR-24-D2 → Tor REQ-11.
[EN] Register: one row per plant species with botanical name, flag ''aggressive rooting/rhizome-forming'' (designer''s assessment) and Tab. 29 match (automatic when the species is in the example list of Tab. 29 – e.g. Phragmites australis, Typha, Carex riparia, bamboo, Prunus spinosa). For such species structural precautions (rhizome/root barrier) and special maintenance must be provided (§ 10.3); with planned planting root/rhizome resistance must be proven (§ 4.3). Number of aggressive species → FLL-GAR-24-D2 → gate REQ-11.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-24' AND x.symbol = 'pflanzenarten';
UPDATE fields x SET description = 'Berechnet (Gleichung FLL-GAR-24-D1): Anzahl der Zeilen im Register „Durchdringungen und Einbauten“. Nicht eingeben; Kontrolle zur manuellen Anzahl Durchdringungen. Durchdringungen sind auf das notwendige Maß zu beschränken (§ 4.12).
[EN] Computed (equation FLL-GAR-24-D1): number of rows in the register ''penetrations and installations''. Not an entry; cross-check for the manual number of penetrations. Penetrations must be limited to the necessary minimum (§ 4.12).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-24' AND x.symbol = 'durchdringungen_count';
UPDATE fields x SET description = 'Berechnet (Gleichung FLL-GAR-24-D2): Anzahl der Pflanzenarten im Register, die als aggressiv wurzelnd/rhizombildend markiert sind oder in Tab. 29 stehen. 0 = Mindestnachweis „rhizomfest gegen Quecken“ genügt; > 0 = zusätzlich die Prüfung nach dem Verfahren zur Bestimmung der Rhizomfestigkeit von Gewässerabdichtungen erforderlich (§ 4.3; § 10.4) – Tor REQ-11 in FLL-GAR-22. Nicht eingeben.
[EN] Computed (equation FLL-GAR-24-D2): number of plant species in the register flagged as aggressive rooting/rhizome-forming or listed in Tab. 29. 0 = the minimum proof ''rhizome-proof against couch grass'' suffices; > 0 = additionally the test per the procedure for determining the rhizome resistance of water-body sealings is required (§ 4.3; § 10.4) – gate REQ-11 in FLL-GAR-22. Not an entry.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-24' AND x.symbol = 'pflanzen_aggressiv_count';
UPDATE equations x SET description = 'Anzahl der Durchdringungen/Einbauten = Zahl der Zeilen im Register „Durchdringungen und Einbauten“. Keine gedruckte Formel; Bezug § 4.12 (Durchdringungen für technische Einbauten auf das notwendige Maß beschränken) und § 4.9 (Anschlüsse, Abschlüsse, Durchdringungen müssen Abdichtungsstoff und Wasserbeanspruchung entsprechen). Ergebnis durchdringungen_count als Kontrolle des manuellen Zählers.
[EN] Number of penetrations/installations = count of rows in the register ''penetrations and installations''. No printed formula; reference § 4.12 (limit penetrations for technical installations to the necessary minimum) and § 4.9 (connections, terminations and penetrations must suit sealing material and water loading). Result durchdringungen_count as a check of the manual counter.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-24' AND x.equation_number = 'FLL-GAR-24-D1';
UPDATE equations x SET description = 'Anzahl aggressiver Arten = Zahl der Registerzeilen „Pflanzenarten“, bei denen das Kennzeichen „aggressiv“ gesetzt ist oder der Tab.-29-Treffer 1 ist. Keine gedruckte Formel; Grundlage § 10.3 mit Tab. 29 (Beispiele von Pflanzen mit aggressiven Wurzeln oder Rhizomen) und § 4.3 (bei wurzelaggressiven/rhizombildenden Arten zusätzliche Rhizomfestigkeitsprüfung). Ergebnis pflanzen_aggressiv_count steuert Tor REQ-11.
[EN] Number of aggressive species = count of ''plant species'' register rows where the ''aggressive'' flag is set or the Tab. 29 match is 1. No printed formula; basis § 10.3 with Tab. 29 (examples of plants with aggressive roots or rhizomes) and § 4.3 (with root-aggressive/rhizome-forming species an additional rhizome-resistance test). Result pflanzen_aggressiv_count drives gate REQ-11.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-24' AND x.equation_number = 'FLL-GAR-24-D2';
UPDATE fields x SET description = 'Bestätigung, dass die Prüfkaskade für den gewählten Abdichtungswerkstoff vollständig ist: Voruntersuchungen (Auftraggeber, Grundlagenermittlung), Eignungsprüfungen (Nachweis der Eignung, vom Vorgebenden zu erbringen), Eigenüberwachungsprüfungen (Auftragnehmer), Kontrollprüfungen (Auftraggeber) und Fremdüberwachung (beauftragte Dritte) nach den Begriffen in §3. Maßgebend sind die werkstoffspezifischen Abschnitte 5.1.3, 6.3.3, 6.4.3, 7.1.3, 7.2.3 bzw. 7.3.3. Tor REQ-26 sperrt ohne Haken; die Einzelnachweise werden im Prüfregister eingetragen.
[EN] Attest that the test cascade for the chosen sealing material is complete: preliminary investigations (client, basic data), suitability tests (proof of suitability, by whoever specifies the material), self-monitoring tests (contractor), control tests (client) and external supervision (commissioned third parties) as defined in §3. The material-specific sections 5.1.3, 6.3.3, 6.4.3, 7.1.3, 7.2.3 or 7.3.3 govern. Gate REQ-26 blocks until ticked; the individual proofs are entered in the test register.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-25' AND x.symbol = 'attest_fll_gar_25_req_26';
UPDATE fields x SET description = 'Bestätigung, dass die Eignungsprüfung dokumentiert und bestanden ist — der Nachweis, dass Baustoffe und Bauteile für den vorgesehenen Zweck geeignet sind, zu erbringen von demjenigen, der den Baustoff vorgibt (§3). Werkstoffabhängig: mineralisch vor dem Einbau gegen Tab. 3 (§5.1.3.1); Flüssigkunststoff objektspezifische Überprüfung der Eigenschaften (§6.3.3.1); PE-Bahnen Herstellerwerte auf den Anwendungsbereich prüfen (§6.4.3.1); Alkalisilikate Dosierung vorab in der Eignungsprüfung festlegen (§7.2.1.1); Stahl und GUP Mindestanforderungen der Abschnitte 7.1 / 7.3 (§7.1.3.1, §7.3.3.1).
[EN] Attest that the suitability test is documented and passed — the proof that materials and components are suitable for the intended purpose, provided by whoever specifies the material (§3). By material: mineral before installation against Tab. 3 (§5.1.3.1); liquid plastics object-specific check of the properties (§6.3.3.1); PE liners manufacturer values checked for the application (§6.4.3.1); alkali silicates dosage fixed beforehand in the suitability test (§7.2.1.1); steel and GRP minimum requirements of sections 7.1 / 7.3 (§7.1.3.1, §7.3.3.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-25' AND x.symbol = 'eignungspruefung_durchgefuehrt';
UPDATE fields x SET description = 'Bezeichnung und Nummer des Fremdüberwachungs- bzw. Konformitätsnachweises des Herstellers (Prüfungen durch beauftragte, anerkannte Dritte, §3). Flüssigkunststoffe: CE-Kennzeichnung mit Leistungserklärung nach DIN 18531-2 und Ü-Kennzeichnung mit Übereinstimmungszertifikat (§6.3.3.2); PE-Bahnen: CE-Dokumentation und Leistungserklärung (§6.4.3.2); Stahl und GUP: Qualitätsnachweis des Herstellers im Rahmen der Fremdüberwachung (§7.1.3.2, §7.3.3.2); Alkalisilikate: Fremdüberwachung ist vom Auftraggeber zu beauftragen (§7.2.3.2); mineralisch: keine gesetzliche Pflicht (§5.1.3.2).
[EN] Name and number of the manufacturer''s external-supervision or conformity certificate (tests by commissioned, recognised third parties, §3). Liquid plastics: CE marking with declaration of performance per DIN 18531-2 and Ü marking with certificate of conformity (§6.3.3.2); PE liners: CE documentation and declaration of performance (§6.4.3.2); steel and GRP: manufacturer''s quality proof within external supervision (§7.1.3.2, §7.3.3.2); alkali silicates: external supervision to be commissioned by the client (§7.2.3.2); mineral: no legal obligation (§5.1.3.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-25' AND x.symbol = 'fremdueberwachung_zertifikat';
UPDATE fields x SET description = 'Bestätigung, dass die Kontrollprüfungen des Auftraggebers dokumentiert sind (§3). Mineralisch: nach Einbau Einbauwassergehalt, Verdichtungsgrad, Schichtdicke, kf-Wert und visuelle Homogenitätskontrolle; die Ergebnisse werden der Abnahme und Abrechnung zugrunde gelegt (§5.1.3.3), ebenso bei Alkalisilikaten mit den Parametern nach 5.1.1/5.1.2 (§7.2.3.3). Flüssigkunststoffe und PE-Bahnen sind europäisch genormte Produkte, spezielle Kontrollprüfungen auf der Baustelle sind nicht erforderlich (§6.3.3.3, §6.4.3.3); bei Stahl, Alkalisilikat und GUP sind Produktkontrollprüfungen nicht durchführbar, der Herstellernachweis genügt (§7.1.3.3, §7.2.3.3, §7.3.3.3) — dann diesen dokumentieren.
[EN] Attest that the client''s control tests are documented (§3). Mineral: after installation water content, degree of compaction, layer thickness, kf value and visual homogeneity check; the results form the basis of acceptance and invoicing (§5.1.3.3), likewise for alkali silicates with the parameters of 5.1.1/5.1.2 (§7.2.3.3). Liquid plastics and PE liners are European-standardised products, special control tests on site are not required (§6.3.3.3, §6.4.3.3); for steel, alkali silicate and GRP product control tests are not feasible on site and the manufacturer''s proof counts as sufficient (§7.1.3.3, §7.2.3.3, §7.3.3.3) — then document that proof.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-25' AND x.symbol = 'kontrollpruefung_dokumentiert';
UPDATE fields x SET description = 'Register der durchgeführten Prüfungen, eine Zeile je Prüfung: Art (Voruntersuchung, Eignungsprüfung, Eigenüberwachung, Fremdüberwachung, Kontrollprüfung nach §3), Werkstoff bzw. Bauteil, Datum, Zertifikat/Prüfbericht und ob bestanden. Welche Prüfungen je Werkstoff anfallen, steht in den Abschnitten 5.1.3, 6.3.3, 6.4.3, 7.1.3, 7.2.3 und 7.3.3; die Ergebnisse der Kontrollprüfung werden der Abnahme und Abrechnung zugrunde gelegt (§5.1.3.3, §7.2.3.3). Belegt die Haken dieses Blatts.
[EN] Register of the tests performed, one row per test: type (preliminary investigation, suitability test, self-monitoring, external supervision, control test per §3), material or component, date, certificate/test report and whether passed. Which tests arise per material is given in sections 5.1.3, 6.3.3, 6.4.3, 7.1.3, 7.2.3 and 7.3.3; the control test results form the basis of acceptance and invoicing (§5.1.3.3, §7.2.3.3). Backs the ticks on this sheet.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-25' AND x.symbol = 'pruefungen';
UPDATE compliance_requirements x SET description = 'Bestanden, wenn der Haken „Nachweis: Sec.5.x.3/6.x.3/7.x.3“ gesetzt ist, d. h. Voruntersuchung, Eignungsprüfung, Eigen-/Fremdüberwachung und Kontrollprüfungen für den gewählten Werkstoff liegen vor oder sind nach dem jeweiligen Abschnitt nicht erforderlich. Einzutragen: der Haken, die drei Einzelbestätigungen und das Prüfregister mit Zertifikaten. Grund: Jeder Werkstoffabschnitt enthält einen Unterabschnitt „Prüfungen“ mit Eignungsprüfung, Eigen-/Fremdüberwachung und Kontrollprüfungen (§5.1.3, §6.3.3, §6.4.3, §7.1.3, §7.2.3, §7.3.3); die Kontrollprüfung ist Grundlage von Abnahme und Abrechnung (§5.1.3.3).
[EN] Passes when the tick ''proof: Sec.5.x.3/6.x.3/7.x.3'' is set, i.e. preliminary investigation, suitability test, self-monitoring/external supervision and control tests for the chosen material are on file or are not required per the respective section. Enter: the tick, the three individual attestations and the test register with certificates. Reason: every material section has a ''tests'' subsection with suitability test, self-monitoring/external supervision and control tests (§5.1.3, §6.3.3, §6.4.3, §7.1.3, §7.2.3, §7.3.3); the control test is the basis of acceptance and invoicing (§5.1.3.3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-25' AND x.code = 'REQ-26';
UPDATE fields x SET description = 'Datum der förmlichen Abnahme aus dem Abnahmeprotokoll. Abnahme ist die körperliche Hinnahme der Leistung durch den Auftraggeber mit der Erklärung, dass er das Werk als im Wesentlichen vertragsgemäß anerkennt; wegen unwesentlicher Mängel kann sie nicht verweigert werden (§ 640 Abs. 1 BGB). Teilabnahmen (z. B. Fertigstellung der Abdichtung) nur bei vertraglicher Vereinbarung, z. B. nach VOB. Bei Abdichtung in Verbindung mit weiteren Arbeiten ist die ordnungsgemäße Ausführung gemeinsam festzustellen und schriftlich niederzulegen (§11.1). Tor REQ-27 sperrt ohne Datum.
[EN] Date of formal acceptance from the acceptance record. Acceptance is the client''s physical taking-over of the work with the declaration that he recognises it as essentially in accordance with the contract; it cannot be refused for minor defects (§ 640 para. 1 BGB). Partial acceptances (e.g. completion of the sealing) only where contractually agreed, e.g. under VOB. Where sealing is combined with further works, proper execution must be jointly established and recorded in writing (§11.1). Gate REQ-27 blocks without a date.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-26' AND x.symbol = 'abnahme_datum';
UPDATE fields x SET description = 'Bestätigung, dass die Verjährungsfrist für Mängelansprüche vertraglich entsprechend §11.2 angesetzt ist: bei Arbeiten an einem Bauwerk fünf Jahre (vier Jahre bei VOB-Verträgen), bei Herstellung, Wartung oder Veränderung einer Sache zwei Jahre. Bei deutlichem Übergewicht der Abdichtungsarbeiten gilt i. d. R. die fünfjährige Frist auch für die vegetationstechnischen Arbeiten (§11.2). Ohne vertragliche Regelung gelten die gesetzlichen Bestimmungen (§11).
[EN] Attest that the limitation period for defect claims is set contractually per §11.2: five years for work on a structure (four years under VOB contracts), two years for the production, maintenance or alteration of an item. Where sealing works clearly predominate, the five-year period as a rule also covers the vegetation works (§11.2). Without a contractual provision the statutory rules apply (§11).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-26' AND x.symbol = 'maengelfrist_5_jahre';
UPDATE compliance_requirements x SET description = 'Bestanden, wenn ein Abnahmedatum eingetragen ist. Einzutragen: das Datum aus dem schriftlich niedergelegten Abnahmeprotokoll der gemeinsamen Feststellung von Auftraggeber und Auftragnehmer. Grund: Die Abnahme ist die körperliche Hinnahme der Leistung mit der Erklärung der Vertragsgemäßheit, mit ihr sind zahlreiche Rechtswirkungen verbunden, und das Ergebnis der gemeinsamen Feststellung ist schriftlich niederzulegen (§11.1).
[EN] Passes when an acceptance date is entered. Enter: the date from the written acceptance record of the joint determination by client and contractor. Reason: acceptance is the physical taking-over of the work with the declaration of contractual conformity, numerous legal effects attach to it, and the result of the joint determination must be recorded in writing (§11.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-26' AND x.code = 'REQ-27';
UPDATE fields x SET description = 'Datum der Inbetriebnahme aus dem Inbetriebnahmeprotokoll. Zur Inbetriebnahme gehören die Aktivierung der technischen Einrichtungen (z. B. Pumpen, Entwässerungseinrichtungen) und die Erstbefüllung des Gewässers (§12). Eingang in Tor REQ-28 (Hinweis).
[EN] Commissioning date from the commissioning record. Commissioning comprises activating the technical installations (e.g. pumps, drainage devices) and the first filling of the water body (§12). Input to gate REQ-28 (warning).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-27' AND x.symbol = 'ibn_datum';
UPDATE fields x SET description = 'Beschreibung der Erstbefüllung aus dem Befüllkonzept: Herkunft und Eignung des Füllwassers (pH-Wert, Wasserhärte, Nährstoffgehalte, Inhaltsstoffe) für die Abdichtung, Vermeidung mechanischer Beschädigung und einer Lageveränderung der Dichtungsbahnen durch den Wasserdruck, Glättung etwaiger Falten, Überprüfung von Randausbildung mit Kapillarsperre und technischen Einrichtungen wie dem Notüberlauf (§12). Die Erstbefüllung ist nur Bestandteil der Abdichtungsleistung, wenn vertraglich vereinbart (§11.1). Eingang in Tor REQ-28.
[EN] Description of the first filling from the filling plan: origin and suitability of the fill water (pH, hardness, nutrient contents, constituents) for the sealing, avoidance of mechanical damage and of liner displacement by water pressure, smoothing of any folds, check of the edge detail with capillary barrier and of technical installations such as the emergency overflow (§12). First filling is part of the sealing service only if contractually agreed (§11.1). Input to gate REQ-28.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-27' AND x.symbol = 'ibn_befuellung_methode';
UPDATE fields x SET description = 'Dauer der Erstbefüllung in Tagen aus dem Befüllprotokoll. Die Richtlinie nennt keine Zeitvorgabe; die Angabe dokumentiert, wie langsam befüllt wurde, um Lageveränderungen der Bahnen zu vermeiden und Falten glätten zu können. Reine Dokumentation, keine Prüfung.
[EN] Duration of the first filling in days from the filling record. The guideline sets no time requirement; the entry documents how slowly filling proceeded so that liner displacement is avoided and folds can be smoothed. Documentation only, no check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-27' AND x.symbol = 'ibn_befuellung_dauer';
UPDATE fields x SET description = 'Verfahren, mit dem die Dichtheit nachgewiesen wurde. Mit einer Erstbefüllung kann die Funktionsfähigkeit der Abdichtung nachgewiesen werden; Art und Umfang sind in der Leistungsbeschreibung zu regeln (§11.1). Zur Ortung von Undichtigkeiten nennt §13.3 Anstauverfahren, visuelle Leckortung mit Farbstoffen, Rauchgas- und Tracergas-Leckortung sowie elektronische Leckortung (Elektroimpulsverfahren).
[EN] Method by which water-tightness was proven. A first filling can prove the function of the sealing; type and scope are to be set in the specification (§11.1). For locating leaks §13.3 names the ponding method, visual leak detection with dyes, smoke and tracer gas detection and electronic leak detection (electrical impulse method).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-27' AND x.symbol = 'ibn_dichtheitspruefung_methode';
UPDATE fields x SET description = 'Abflusswirksame Fläche in m², die dem Notüberlauf zufließt (Wasserfläche plus angeschlossene Flächen), aus dem Entwässerungsplan. Entspricht der Größe „Abflusswirksame Fläche“ des Anhang-1-Beispiels (800 m²) und ist dieselbe Größe wie das Feld A der Gl. 1 — denselben Wert eintragen.
[EN] Effective runoff area in m² draining to the emergency overflow (water surface plus connected areas), from the drainage plan. Corresponds to the ''effective runoff area'' of the Annex 1 example (800 m²) and is the same quantity as field A of eq. 1 — enter the same value.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-27' AND x.symbol = 'A_einzugsflaeche';
UPDATE fields x SET description = 'Abflusswirksame Fläche A in m² für die Notüberlauf-Bemessung nach Gl. 1, aus dem Entwässerungsplan. Im Anhang-1-Beispiel 800 m²; in der Formel wird A durch 10.000 geteilt, um von m² auf ha zu kommen. Bei mehreren Teilflächen die Summe aus dem Register der Einzugsflächen verwenden.
[EN] Effective runoff area A in m² for sizing the emergency overflow per eq. 1, from the drainage plan. 800 m² in the Annex 1 example; in the formula A is divided by 10,000 to convert m² to ha. With several partial areas use the sum from the catchment register.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-27' AND x.symbol = 'A';
UPDATE fields x SET description = 'Abflussbeiwert C (dimensionslos) der Einzugsfläche für Gl. 1, nach DIN 1986-100, auf die die Richtlinie verweist. Die Richtlinie selbst druckt nur den Wert des Beispiels: C = 1 (Anhang 1). Einen anderen Wert mit der DIN-1986-100-Tabelle belegen; bei mehreren Teilflächen den flächengewichteten Wert aus dem Register verwenden.
[EN] Runoff coefficient C (dimensionless) of the catchment for eq. 1, per DIN 1986-100, to which the guideline refers. The guideline itself prints only the example value: C = 1 (Annex 1). Substantiate any other value with the DIN 1986-100 table; with several partial areas use the area-weighted value from the register.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-27' AND x.symbol = 'C';
UPDATE fields x SET description = 'Örtliche Regenspende r5,100 in l/(s·ha): fünfminütiges Regenereignis, das statistisch alle 100 Jahre auftritt, nach DIN 1986-100 für den Standort (örtliche Regenspende). Der Notüberlauf an aufgehenden Gebäudeteilen ist nach DIN 1986-100 mit r5,100 zu dimensionieren (§4.10). Beispiel Düsseldorf: r5,100 = 607 l/(s·ha) (Anhang 1). Eingang in Gl. 1.
[EN] Local rainfall intensity r5,100 in l/(s·ha): five-minute rain event with a statistical return period of 100 years, per DIN 1986-100 for the site (local rainfall intensity). The emergency overflow at rising building parts is to be sized per DIN 1986-100 with r5,100 (§4.10). Example Düsseldorf: r5,100 = 607 l/(s·ha) (Annex 1). Input to eq. 1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-27' AND x.symbol = 'r_5_100';
UPDATE fields x SET description = 'Örtliche Regenspende r5,5 in l/(s·ha): fünfminütiges Regenereignis, das statistisch alle fünf Jahre auftritt, nach DIN 1986-100 für den Standort (örtliche Regenspende). Der Regelüberlauf wird in Anlehnung an DIN 1986-100 mit r5,5 dimensioniert (§4.10). Beispiel Düsseldorf: r5,5 = 316 l/(s·ha) (Anhang 1). In Gl. 1 wird r5,5 · C vom r5,100 abgezogen.
[EN] Local rainfall intensity r5,5 in l/(s·ha): five-minute rain event with a statistical return period of five years, per DIN 1986-100 for the site (local rainfall intensity). The regular overflow is sized following DIN 1986-100 with r5,5 (§4.10). Example Düsseldorf: r5,5 = 316 l/(s·ha) (Annex 1). In eq. 1 r5,5 · C is subtracted from r5,100.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-27' AND x.symbol = 'r_5_5';
UPDATE fields x SET description = 'Bestätigung, dass der Dichtheitsnachweis bestanden ist — in der Regel über die Erstbefüllung, mit der die Funktionsfähigkeit der Abdichtung nachgewiesen werden kann (§11.1), einschließlich der Überprüfung von Randausbildung mit Kapillarsperre und technischen Einrichtungen (§12). Protokoll der Wasserstandsbeobachtung beilegen.
[EN] Attest that the leak test was passed — usually via the first filling, by which the function of the sealing can be proven (§11.1), including the check of the edge detail with capillary barrier and of the technical installations (§12). Attach the water-level observation record.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-27' AND x.symbol = 'ibn_dichtheit_bestanden';
UPDATE fields x SET description = 'Bemessungsabfluss des Notüberlaufs in l/s, berechnet nach Gl. 1 aus r5,100, r5,5, C und A — keine Eingabe. Beispiel Anhang 1: (607 − 316) · 800/10.000 = 23,28 l/s. Die Abflusskapazität des Notüberlaufs muss mindestens Q_NOT erreichen (Tor REQ-40).
[EN] Design discharge of the emergency overflow in l/s, computed per eq. 1 from r5,100, r5,5, C and A — no input. Annex 1 example: (607 − 316) · 800/10,000 = 23.28 l/s. The discharge capacity of the emergency overflow must reach at least Q_NOT (gate REQ-40).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-27' AND x.symbol = 'Q_NOT';
UPDATE fields x SET description = 'Register der Teilflächen, die dem Notüberlauf zufließen, eine Zeile je Teilfläche mit Bezeichnung, abflusswirksamer Fläche a_m2 in m² und Abflussbeiwert c nach DIN 1986-100 (Beispiel Anhang 1: 800 m², C = 1). Aus den Zeilen werden Σ A und Σ A·C gebildet (Gl. FLL-GAR-27-D1/-D2); die Skalare A und C der Gl. 1 sind damit konsistent zu belegen.
[EN] Register of the partial areas draining to the emergency overflow, one row per area with name, effective runoff area a_m2 in m² and runoff coefficient c per DIN 1986-100 (Annex 1 example: 800 m², C = 1). From the rows Σ A and Σ A·C are formed (eqs. FLL-GAR-27-D1/-D2); the scalars A and C of eq. 1 must be filled consistently with them.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-27' AND x.symbol = 'einzugsflaechen_not';
UPDATE fields x SET description = 'Berechnete Summe der abflusswirksamen Flächen aller Zeilen des Einzugsflächen-Registers in m² (Gl. FLL-GAR-27-D1) — keine Eingabe. Entspricht der „Abflusswirksamen Fläche“ des Anhang-1-Beispiels und soll mit dem Skalar A der Gl. 1 übereinstimmen.
[EN] Computed sum of the effective runoff areas of all rows of the catchment register in m² (eq. FLL-GAR-27-D1) — no input. Corresponds to the ''effective runoff area'' of the Annex 1 example and should match the scalar A of eq. 1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-27' AND x.symbol = 'sum_a_m2';
UPDATE fields x SET description = 'Berechnete Summe der Produkte Fläche · Abflussbeiwert über alle Zeilen des Registers in m² (Gl. FLL-GAR-27-D2) — keine Eingabe. Sie ist der Zähler des Terms r5,5 · C in der Summenform von Gl. 1; bei C = 1 (Anhang-1-Beispiel) ist sie gleich Σ A.
[EN] Computed sum of the products area · runoff coefficient over all rows of the register in m² (eq. FLL-GAR-27-D2) — no input. It is the numerator of the term r5,5 · C in the summed form of eq. 1; with C = 1 (Annex 1 example) it equals Σ A.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-27' AND x.symbol = 'sum_ac';
UPDATE fields x SET description = 'Bestätigung aus dem Entwässerungsplan, dass ein Notüberlauf mit kanalunabhängigem Entwässerungskonzept vorhanden ist. „Werden Gewässer an aufgehenden Gebäudeteilen ausgeführt, ist ein Notüberlauf mit kanalunabhängigem Entwässerungskonzept nach DIN 1986-100 mit örtlicher 100-Jahres-Regenspende r5,100 zu dimensionieren“ (§4.10). Tor REQ-40 sperrt ohne Haken, wenn das Gewässer an Gebäudeteilen liegt.
[EN] Attest from the drainage plan that an emergency overflow with a sewer-independent drainage concept exists. ''Where water bodies are built against rising building parts, an emergency overflow with a sewer-independent drainage concept is to be sized per DIN 1986-100 with the local 100-year rainfall intensity r5,100'' (§4.10). Gate REQ-40 blocks without the tick when the water body adjoins building parts.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-27' AND x.symbol = 'notueberlauf_vorhanden';
UPDATE fields x SET description = 'Abflusskapazität des eingebauten Notüberlaufs in l/s aus der hydraulischen Bemessung (Rohrleitungsquerschnitte nach DIN EN 12056-3, §4.10). Sie muss mindestens dem berechneten Q_NOT aus Gl. 1 entsprechen; Tor REQ-40 vergleicht beide Werte.
[EN] Discharge capacity of the installed emergency overflow in l/s from the hydraulic design (pipe cross-sections per DIN EN 12056-3, §4.10). It must at least equal the computed Q_NOT from eq. 1; gate REQ-40 compares the two values.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-27' AND x.symbol = 'notueberlauf_kapazitaet_l_s';
UPDATE fields x SET description = 'Bestätigung aus den Höhenangaben des Entwässerungsplans, dass der Notüberlauf höher liegt als der Regelüberlauf: „Der Notüberlauf ist als kanalunabhängige Notentwässerung höher als der Regelüberlauf einzubauen“ (Anhang 1, informativ). Eingang in Tor REQ-40.
[EN] Attest from the level data of the drainage plan that the emergency overflow is set higher than the regular overflow: ''the emergency overflow is to be installed as sewer-independent emergency drainage higher than the regular overflow'' (Annex 1, informative). Input to gate REQ-40.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-27' AND x.symbol = 'notueberlauf_hoeher_als_regelueberlauf';
UPDATE equations x SET description = 'Beispielsberechnung des Notüberlauf-Abflusses nach DIN 1986-100: Q_NOT = [r5,100 − (r5,5 · C)] · (A / 10.000). Symbole: r5,100 und r5,5 = örtliche fünfminütige Regenspenden mit 100- bzw. 5-jährlicher Wiederkehr in l/(s·ha); C = Abflussbeiwert (−); A = abflusswirksame Fläche in m², durch 10.000 in ha umgerechnet; Ergebnis Q_NOT in l/s. Beispiel Düsseldorf: (607 − 316) · 800/10.000 = 23,28 l/s. Der Anhang ist informativ; das Ergebnis ist der Vergleichswert für die Kapazität des Notüberlaufs (REQ-40).
[EN] Example calculation of the emergency overflow discharge per DIN 1986-100: Q_NOT = [r5,100 − (r5,5 · C)] · (A / 10,000). Symbols: r5,100 and r5,5 = local five-minute rainfall intensities with 100-year and 5-year return periods in l/(s·ha); C = runoff coefficient (−); A = effective runoff area in m², converted to ha by dividing by 10,000; result Q_NOT in l/s. Düsseldorf example: (607 − 316) · 800/10,000 = 23.28 l/s. The annex is informative; the result is the reference value for the emergency overflow capacity (REQ-40).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-27' AND x.equation_number = '1';
UPDATE equations x SET description = 'Summiert die abflusswirksamen Flächen a_m2 aller Zeilen des Einzugsflächen-Registers: sum_a_m2 = Σ a_m2 in m². Keine gedruckte Formel; bildet die „Abflusswirksame Fläche“ des Anhang-1-Beispiels (800 m²) aus Teilflächen nach. Das Ergebnis ist die Fläche A für Gl. 1.
[EN] Sums the effective runoff areas a_m2 of all rows of the catchment register: sum_a_m2 = Σ a_m2 in m². No printed formula; reproduces the ''effective runoff area'' of the Annex 1 example (800 m²) from partial areas. The result is the area A for eq. 1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-27' AND x.equation_number = 'FLL-GAR-27-D1';
UPDATE equations x SET description = 'Summiert die Produkte Fläche · Abflussbeiwert aller Registerzeilen: sum_ac = Σ (a_m2 · c) in m². Keine gedruckte Formel; sie liefert den Term r5,5 · C der Gl. 1 in Summenform, Q_NOT = (r5,100 · Σ A − r5,5 · Σ A·C) / 10.000, die bei C = 1 mit dem Anhang-1-Beispiel übereinstimmt.
[EN] Sums the products area · runoff coefficient of all register rows: sum_ac = Σ (a_m2 · c) in m². No printed formula; it supplies the term r5,5 · C of eq. 1 in summed form, Q_NOT = (r5,100 · Σ A − r5,5 · Σ A·C) / 10,000, which agrees with the Annex 1 example for C = 1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-27' AND x.equation_number = 'FLL-GAR-27-D2';
UPDATE compliance_requirements x SET description = 'Hinweis (keine Sperre), wenn Inbetriebnahme-Datum oder Erstbefüllungs-Methode fehlen. Einzutragen: das Datum und eine Beschreibung der Erstbefüllung, die die Punkte des §12 abdeckt — Eignung des Füllwassers (pH-Wert, Wasserhärte, Nährstoffgehalte, Inhaltsstoffe), Vermeidung mechanischer Beschädigung und Lageveränderung der Bahnen, Glättung von Falten, Überprüfung von Randausbildung und Notüberlauf. Grund: „Auf folgende Punkte ist besonders zu achten“ (§12).
[EN] Warning (no block) when the commissioning date or the first-filling method is missing. Enter: the date and a description of the first filling covering the §12 points — suitability of the fill water (pH, hardness, nutrient contents, constituents), avoidance of mechanical damage and liner displacement, smoothing of folds, check of edge detail and emergency overflow. Reason: ''particular attention is to be paid to the following points'' (§12).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-27' AND x.code = 'REQ-28';
UPDATE compliance_requirements x SET description = 'Gilt nur, wenn das Gewässer an aufgehenden Gebäudeteilen ausgeführt wird (Angabe aus FLL-GAR-08). Bestanden, wenn ein Notüberlauf mit kanalunabhängigem Entwässerungskonzept vorhanden ist, höher als der Regelüberlauf liegt und seine Abflusskapazität ≥ Q_NOT aus Gl. 1 ist. Einzutragen: die beiden Haken, die Kapazität in l/s sowie r5,100, r5,5, C und A für Q_NOT. Grund: §4.10 verlangt die Dimensionierung mit r5,100 („ist … zu dimensionieren“); die Höhenlage über dem Regelüberlauf stammt aus dem informativen Anhang 1.
[EN] Applies only when the water body is built against rising building parts (entry from FLL-GAR-08). Passes when an emergency overflow with a sewer-independent drainage concept exists, lies higher than the regular overflow and its discharge capacity is ≥ Q_NOT from eq. 1. Enter: the two ticks, the capacity in l/s and r5,100, r5,5, C and A for Q_NOT. Reason: §4.10 requires sizing with r5,100 (''is to be sized''); the level above the regular overflow comes from the informative Annex 1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-27' AND x.code = 'REQ-40';
UPDATE fields x SET description = 'Geplanter Abstand zwischen zwei Inspektionen in Jahren aus dem Instandhaltungskonzept. Inspektionen sind in regelmäßigen Abständen vorzusehen, die Richtlinie nennt als Beispiel mindestens einmal im Jahr; das gilt für die Dauer der Mängelanspruchsfrist und die Nutzungszeit danach (§13.1). Tor REQ-29 (Hinweis) meldet Intervalle über 1 Jahr.
[EN] Planned interval between two inspections in years from the maintenance concept. Inspections are to be scheduled at regular intervals; the guideline names at least once a year as the example; this applies during the defects liability period and the service life thereafter (§13.1). Gate REQ-29 (warning) flags intervals above 1 year.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-28' AND x.symbol = 'inspektion_intervall_jahr';
UPDATE fields x SET description = 'Textliche Beschreibung des Inspektionsrhythmus (z. B. jährlich im Frühjahr, zusätzlich nach Hochwasser oder Frostperioden). Art, Umfang und Zeitpunkt der Kontrollen richten sich nach Art der Abdichtung, den Standortverhältnissen, dem Entwicklungszustand der Vegetation und dem Grad der Nutzung (§13.1). Der Zahlenwert in Jahren steht im Feld „Inspektionsintervall (Jahr)“.
[EN] Textual description of the inspection rhythm (e.g. yearly in spring, additionally after floods or frost periods). Type, scope and timing of the checks depend on the sealing type, site conditions, vegetation development and degree of use (§13.1). The numeric value in years goes in the field ''inspection interval (year)''.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-28' AND x.symbol = 'inst_inspektionsintervall';
UPDATE fields x SET description = 'Wartungsintervalle aus dem Wartungskonzept, das mindestens Art und Umfang der Wartung, Voraussetzungen (Wasser, Strom, Infrastruktur), Wartungsintervalle, Zeitpunkt der Wartung und Abrechnungseinheiten enthalten sollte (§13.2). Wartung umfasst u. a. Reinigung und Wartung der technischen und hydraulischen Einrichtungen nach Herstellerangaben, Entfernen von Fremdstoffen (Laub, Holz, Algen, Faulschlamm) und die Vegetationspflege; fachgerechte Wartung ist Voraussetzung für die Gewährleistung (§13.2).
[EN] Maintenance intervals from the maintenance concept, which should contain at least type and scope of maintenance, prerequisites (water, power, infrastructure), maintenance intervals, timing and billing units (§13.2). Maintenance includes cleaning and servicing of the technical and hydraulic installations per manufacturer''s instructions, removal of foreign matter (leaves, wood, algae, sludge) and vegetation care; proper maintenance is a prerequisite for the warranty (§13.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-28' AND x.symbol = 'inst_wartungsintervall';
UPDATE fields x SET description = 'Angabe, wer die Inspektionen durchführt und welche Qualifikation diese Person oder Firma hat (z. B. Fachbetrieb des Abdichtungssystems, Planer). Die Richtlinie schreibt für die Inspektion keine bestimmte Qualifikation vor; die Angabe dient der Nachvollziehbarkeit des Instandhaltungskonzepts.
[EN] Statement of who carries out the inspections and what qualification that person or firm holds (e.g. specialist contractor of the sealing system, designer). The guideline prescribes no particular qualification for inspection; the entry serves the traceability of the maintenance concept.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-28' AND x.symbol = 'inst_qualifikation_pruefer';
UPDATE fields x SET description = 'Form, in der die Inspektionsergebnisse festgehalten werden (z. B. Inspektionsbericht mit Fotos, Betriebstagebuch). „Die Ergebnisse der Inspektion sind schriftlich zu dokumentieren“; sie sind Grundlage für Wartung und ggf. Instandsetzung (§13.1). Die Dokumentation von Inspektionsintervallen und Wartungskonzepten gehört zum Instandhaltungsmanagement nach DIN EN 13306 und DIN 31051 (§13).
[EN] Form in which the inspection results are recorded (e.g. inspection report with photos, operating log). ''The inspection results are to be documented in writing''; they form the basis for maintenance and, if needed, repair (§13.1). Documenting inspection intervals and maintenance concepts is part of maintenance management per DIN EN 13306 and DIN 31051 (§13).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-28' AND x.symbol = 'inst_protokollierung';
UPDATE fields x SET description = 'Register des Inspektions- und Wartungsplans, eine Zeile je Maßnahme mit Maßnahme, Intervall und Qualifikation. Inspektionspunkte nach §13.1: mechanische, thermische und photochemische Beanspruchungen, Spannungen, Quetschungen, Risse, Funktion der Kapillarsperre, der Zu-, Ab- und Überläufe, Lagestabilität und Dicke der Auflast bei mineralischen Abdichtungen, Schutzschichten, Standfestigkeit des Gewässerrandes, Winterschäden (Eisdruck), Durchdringungen, Eckausbildungen, Vegetation. Wartungspunkte nach §13.2: Reinigung technischer Einrichtungen, Entfernen von Fremdstoffen, Vegetationspflege. Keine Stoffe eintragen, die wassergefährdend sind oder die Abdichtung gefährden (§13).
[EN] Register of the inspection and maintenance plan, one row per measure with measure, interval and qualification. Inspection items per §13.1: mechanical, thermal and photochemical stresses, tensions, crushing, cracks, function of the capillary barrier and of inlets, outlets and overflows, position and thickness of the ballast on mineral sealings, protection layers, stability of the pond edge, winter damage (ice pressure), penetrations, corner details, vegetation. Maintenance items per §13.2: cleaning of technical installations, removal of foreign matter, vegetation care. Do not introduce substances that are hazardous to water or endanger the sealing (§13).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-28' AND x.symbol = 'wartungsmassnahmen';
UPDATE compliance_requirements x SET description = 'Hinweis (keine Sperre), wenn das Inspektionsintervall mehr als 1 Jahr beträgt. Einzutragen: das Intervall in Jahren sowie das Instandhaltungskonzept mit Inspektions- und Wartungsmaßnahmen. Grund: Inspektionen sind in regelmäßigen Abständen vorzusehen, „z. B. mindestens einmal im Jahr“ (§13.1) — ein Beispielwert, daher Hinweis; die Instandhaltung umfasst Inspektion, Wartung und Instandsetzung (§13).
[EN] Warning (no block) when the inspection interval exceeds 1 year. Enter: the interval in years and the maintenance concept with inspection and maintenance measures. Reason: inspections are to be scheduled at regular intervals, ''e.g. at least once a year'' (§13.1) — an example value, hence a warning; maintenance comprises inspection, servicing and repair (§13).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-28' AND x.code = 'REQ-29';
UPDATE fields x SET description = 'Abschließendes Urteil des verantwortlichen Ingenieurs über das gesamte Projekt: konform = alle Tore der Blätter 01–28 bestanden; konform mit Auflagen = bestanden mit dokumentierten Bedingungen (z. B. offene Hinweise, nachzureichende Nachweise); nicht konform = mindestens eine Sperre nicht erfüllt; unzureichende Daten = Nachweise noch nicht entscheidbar. Tor REQ-30 lässt die Freigabe nur bei „konform“ oder „konform mit Auflagen“ zu. Keine Vorgabe der Richtlinie — Wizard-Zusammenfassung.
[EN] Final verdict of the responsible engineer on the whole project: compliant = all gates of sheets 01–28 passed; compliant with conditions = passed with documented conditions (e.g. open warnings, evidence to be supplied); not compliant = at least one block not met; insufficient data = proofs not yet decidable. Gate REQ-30 allows sign-off only for ''compliant'' or ''compliant with conditions''. Not a guideline requirement — Wizard summary.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-29' AND x.symbol = 'compliance_verdict_final';
UPDATE fields x SET description = 'Kurzbezeichnung des gewählten Abdichtungssystems für den Berichtskopf (z. B. „PEHD-Bahn 2,0 mm, strukturiert“), übereinstimmend mit der Systemwahl in FLL-GAR-09 und dem Werkstoffblatt 10–21. Reine Zusammenfassung, keine Prüfung.
[EN] Short name of the selected sealing system for the report header (e.g. ''PEHD liner 2.0 mm, textured''), consistent with the system choice in FLL-GAR-09 and the material sheet 10–21. Summary only, no check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-29' AND x.symbol = 'konf_abdichtungssystem_gewaehlt';
UPDATE fields x SET description = 'Bestätigung, dass alle Nachweise der Blätter 01–28 bestanden sind oder ihre offenen Punkte in den Bemerkungen benannt sind. Dient der Freigabe; der Haken ersetzt keine Einzelprüfung und wird vom Wizard nicht gegen die Tore abgeglichen.
[EN] Attest that all proofs of sheets 01–28 are passed or that their open items are named in the notes. Serves the sign-off; the tick replaces no individual check and is not reconciled by the Wizard against the gates.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-29' AND x.symbol = 'konf_alle_nachweise_bestanden';
UPDATE fields x SET description = 'Datum, an dem der verantwortliche Ingenieur die Konformitätszusammenfassung freigibt. Verwaltungsangabe für den Bericht; keine Prüfung.
[EN] Date on which the responsible engineer signs off the compliance summary. Administrative entry for the report; no check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-29' AND x.symbol = 'konf_freigabe_datum';
UPDATE fields x SET description = 'Freitext für Auflagen, offene Hinweise, nachzureichende Nachweise und Abweichungen, die das Urteil „konform mit Auflagen“ begründen. Wird in den Bericht übernommen; keine Prüfung.
[EN] Free text for conditions, open warnings, evidence still to be supplied and deviations that justify a ''compliant with conditions'' verdict. Carried into the report; no check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-29' AND x.symbol = 'konf_bemerkungen';
UPDATE compliance_requirements x SET description = 'Bestanden, wenn das Konformitätsurteil „konform“ oder „konform mit Auflagen“ lautet. Einzutragen: das Urteil nach Durchsicht aller Blätter 01–28, dazu Freigabedatum und Bemerkungen mit den Auflagen. Grund: Wizard-Abschluss — die Freigabe setzt ein positives Gesamturteil des verantwortlichen Ingenieurs voraus; die Richtlinie selbst enthält keine Konformitätszusammenfassung.
[EN] Passes when the compliance verdict is ''compliant'' or ''compliant with conditions''. Enter: the verdict after reviewing all sheets 01–28, plus sign-off date and notes listing the conditions. Reason: Wizard close-out — sign-off requires a positive overall verdict by the responsible engineer; the guideline itself contains no compliance summary.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-29' AND x.code = 'REQ-30';
COMMIT;
